export function solve(text: string): string | null {
  const m = /(?<!\d)(\d{1,16})(?:\.(\d{1,16}))?(?:\.(\d{1,16}))?(?!\d)/.exec(text);
  if (!m) return null;
  return `${m[1]}.${m[2] ?? "0"}.${m[3] ?? "0"}`;
}

export function solve(name: string, namespace: string): string {
    // Parse the namespace UUID into 16 bytes.
    const nsHex = namespace.replace(/-/g, "");
    if (!/^[0-9a-fA-F]{32}$/.test(nsHex)) {
        throw new Error("Invalid namespace UUID");
    }
    const nsBytes: number[] = [];
    for (let i = 0; i < 16; i++) {
        nsBytes.push(parseInt(nsHex.slice(i * 2, i * 2 + 2), 16));
    }

    // Encode the name as UTF-8 manually (no TextEncoder, which is not ECMAScript).
    // Lone surrogates are replaced with U+FFFD, matching standard UTF-8 encoders.
    const nameBytes: number[] = [];
    for (const ch of name) {
        let cp = ch.codePointAt(0) as number;
        if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd;
        }
        if (cp < 0x80) {
            nameBytes.push(cp);
        } else if (cp < 0x800) {
            nameBytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            nameBytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            nameBytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    // SHA-1 over namespace bytes followed by name bytes.
    const data = new Uint8Array(16 + nameBytes.length);
    data.set(nsBytes, 0);
    data.set(nameBytes, 16);
    const digest = lib.sha1(data);

    // Take the first 16 bytes and set version (5) and RFC 4122 variant bits.
    const bytes = new Uint8Array(16);
    for (let i = 0; i < 16; i++) {
        bytes[i] = digest[i];
    }
    bytes[6] = (bytes[6] & 0x0f) | 0x50;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;

    // Format as lowercase 8-4-4-4-12.
    const h = Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
    return (
        h.slice(0, 8) + "-" +
        h.slice(8, 12) + "-" +
        h.slice(12, 16) + "-" +
        h.slice(16, 20) + "-" +
        h.slice(20, 32)
    );
}

export function solve(stamps: string[]): number[] {
  // lib.parseISO's no-offset branch builds the result with local-time setters,
  // so its output depends on the host time zone. To keep results in UTC, every
  // input is given an explicit offset before parsing. Strings without one get
  // "Z" appended, which routes them through the offset branch.
  const toEpoch = (input: string): number => {
    if (typeof input !== "string") {
      throw new RangeError(`Not a valid date: ${String(input)}`);
    }

    const sep = input.search(/[T ]/);
    let normalized: string;

    if (sep === -1) {
      // Date-only: allow only calendar, week, or ordinal date characters.
      // ISO 8601 does not permit an offset without a time.
      if (!/^[0-9W-]+$/.test(input)) {
        throw new RangeError(`Not a valid date: ${input}`);
      }
      normalized = input + "T00:00Z";
    } else {
      const timePart = input.slice(sep + 1);
      const hasOffset = /(?:Z|[+-]\d{2}(?::?\d{2})?)$/.test(timePart);
      normalized = hasOffset ? input : input + "Z";
    }

    const date = lib.parseISO(normalized);
    const ms = date.getTime();
    if (Number.isNaN(ms)) {
      throw new RangeError(`Not a valid date: ${input}`);
    }
    return ms;
  };

  return stamps.map(toEpoch).sort((a, b) => a - b);
}

export function solve(version: string, range: string): boolean {
