}

export function solve(versions: string[]): string[] {
  const parse = (v: string) => {
    const m = v.split('+')[0];
    const d = m.indexOf('-');
    return {
      n: (d < 0 ? m : m.slice(0, d)).split('.').map(Number),
      p: d < 0 ? [] : m.slice(d + 1).split('.'),
    };
  };
  const id = (a: string, b: string): number => {
    const an = /^\d+$/.test(a), bn = /^\d+$/.test(b);
    if (an && bn) return a.length - b.length || (a < b ? -1 : +(a > b));
    if (an !== bn) return an ? -1 : 1;
    return a < b ? -1 : +(a > b);
  };
  const cmp = (x: string, y: string): number => {
    const a = parse(x), b = parse(y);
    for (let i = 0; i < 3; i++) if (a.n[i] !== b.n[i]) return a.n[i] - b.n[i];
    if (!a.p.length || !b.p.length) return +!!b.p.length - +!!a.p.length;
    for (let i = 0; i < Math.min(a.p.length, b.p.length); i++) {
      const c = id(a.p[i], b.p[i]);
      if (c) return c;
    }
    return a.p.length - b.p.length;
  };
  return [...versions].sort((x, y) => cmp(x, y) || (x < y ? -1 : +(x > y)));
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  const s = isbn.replace(/[ -]/g, "");
  const ok10 = /^\d{9}[\dX]$/.test(s) &&
    [...s].reduce((sum, c, i) => sum + (10 - i) * (c === "X" ? 10 : Number(c)), 0) % 11 === 0;
  const ok13 = /^\d{13}$/.test(s) &&
    [...s].reduce((sum, c, i) => sum + (i % 2 ? 3 : 1) * Number(c), 0) % 10 === 0;
  if (version === 10) return ok10;
  if (version === 13) return ok13;
  return ok10 || ok13;
}

export function solve(name: string, namespace: string): string {
  const uuidPattern = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
  if (typeof namespace !== "string" || !uuidPattern.test(namespace)) {
    throw new TypeError(`Invalid UUID namespace: ${String(namespace)}`);
  }
  return lib.v3(name, namespace.toLowerCase()).toLowerCase();
}

export function solve(text: string): string {
    // Encode the string as UTF-8 manually (no TextEncoder, since it is not ECMAScript).
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < text.length) {
            const lo = text.charCodeAt(i + 1);
            if (lo >= 0xdc00 && lo <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
                i++;
            } else {
                cp = 0xfffd; // lone high surrogate
            }
        } else if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd; // lone low surrogate
        }

        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            bytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            bytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    const digest = lib.sha1(Uint8Array.from(bytes));

    let hex = "";
    for (let i = 0; i < digest.length; i++) {
        hex += digest[i].toString(16).padStart(2, "0");
    }
    return hex;
}

export function solve(isin: string): boolean {
  if (!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) return false;
  const digits = [...isin]
    .map((c) => (/[0-9]/.test(c) ? c : String(c.charCodeAt(0) - 55)))
    .join("");
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48;
    if (double) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    double = !double;
  }
  return sum % 10 === 0;
}

export function solve(iban: string): boolean {
  const normalized = iban.replace(/[\s-]/g, "").toUpperCase();
  return lib.isIBAN(normalized);
}

export function solve(mac: string): boolean {
  const patterns = [
    /^[0-9a-f]{2}(:[0-9a-f]{2}){5}$/i,      // EUI-48, colon
    /^[0-9a-f]{2}(:[0-9a-f]{2}){7}$/i,      // EUI-64, colon
    /^[0-9a-f]{2}(-[0-9a-f]{2}){5}$/i,      // EUI-48, hyphen
    /^[0-9a-f]{2}(-[0-9a-f]{2}){7}$/i,      // EUI-64, hyphen
    /^[0-9a-f]{4}(\.[0-9a-f]{4}){2}$/i,     // dotted, 3 groups
    /^[0-9a-f]{4}(\.[0-9a-f]{4}){3}$/i,     // dotted, 4 groups
  ];
  return patterns.some((p) => p.test(mac));
}

export function solve(version: string, kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease', id?: string): string | null {
  const m = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*)?$/.exec(version);
  if (!m) return null;
  const parts = [m[1], m[2], m[3]].map(Number);
  const pre = m[4] ? m[4].split('.') : [];
  const i = ['major', 'minor', 'patch'].indexOf(kind.replace('pre', ''));
  const isPreKind = kind.startsWith('pre');
  const fresh = id === undefined ? ['0'] : [id, '0'];
  let next: string[] = [];
  if (kind === 'prerelease') {
    if (!pre.length) {
      parts[2]++;
      next = fresh;
    } else if (id === undefined || pre[0] === id) {
      next = [...pre];
      const n = next.length - 1;
      if (/^\d+$/.test(next[n])) next[n] = String(+next[n] + 1);
      else next.push('0');
    } else {
      next = [id, '0'];
    }
  } else if (isPreKind || !pre.length || !parts.slice(i + 1).every(n => n === 0)) {
    parts[i]++;
    parts.fill(0, i + 1);
    if (isPreKind) next = fresh;
  }
  return parts.join('.') + (next.length ? '-' + next.join('.') : '');
}

export function solve(card: string): boolean {
  const s = card.replace(/[ -]/g, "");
  if (!/^\d+$/.test(s)) return false;
  const n = s.length;
  const p = (k: number) => Number(s.slice(0, k));
  const between = (k: number, lo: number, hi: number) => p(k) >= lo && p(k) <= hi;
  const len = (...ls: number[]) => ls.includes(n);
  const inLen = (lo: number, hi: number) => n >= lo && n <= hi;
  const issuerOk =
    (s[0] === "4" && len(13, 16, 19)) ||
    ((between(2, 51, 55) || between(4, 2221, 2720)) && len(16)) ||
    ((p(2) === 34 || p(2) === 37) && len(15)) ||
    ((p(4) === 6011 || between(6, 622126, 622925) || between(3, 644, 649) || p(2) === 65) && len(16, 19)) ||
    ((between(3, 300, 305) || p(2) === 36 || p(2) === 38) && inLen(14, 19)) ||
    (between(4, 3528, 3589) && inLen(16, 19)) ||
    (p(2) === 62 && inLen(16, 19));
  if (!issuerOk) return false;
  let sum = 0;
  for (let i = 0; i < n; i++) {
    let d = Number(s[n - 1 - i]);
    if (i % 2 === 1) d = d * 2 > 9 ? d * 2 - 9 : d * 2;
    sum += d;
  }
  return sum % 10 === 0;
}

export function solve(code: string): boolean {
  if (!/^\d+$/.test(code)) return false;
  if (![8, 13, 14].includes(code.length)) return false;
  const digits = code.split('').map(Number);
  const check = digits.pop()!;
  let sum = 0;
  digits.reverse().forEach((d, i) => {
    sum += d * (i % 2 === 0 ? 3 : 1);
  });
  return (10 - (sum % 10)) % 10 === check;
}

export function solve(issn: string): boolean {
  if (!/^\d{4}-?\d{3}[\dXx]$/.test(issn)) return false;
  const digits = issn.replace("-", "");
  let sum = 0;
  for (let i = 0; i < 8; i++) {
    const c = digits[i];
    const v = c.toUpperCase() === "X" ? 10 : Number(c);
    sum += (8 - i) * v;
  }
  return sum % 11 === 0;
}

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === "") return doc;
  if (!pointer.startsWith("/")) throw new Error("Invalid JSON Pointer: must be empty or start with '/'");
  const tokens = pointer.slice(1).split("/").map(t => t.replace(/~1/g, "/").replace(/~0/g, "~"));
  let cur: unknown = doc;
  for (const tok of tokens) {
    if (Array.isArray(cur)) {
      if (!/^(0|[1-9]\d*)$/.test(tok)) return undefined;
      const i = Number(tok);
      if (i >= cur.length) return undefined;
      cur = cur[i];
    } else if (typeof cur === "object" && cur !== null && Object.prototype.hasOwnProperty.call(cur, tok)) {
      cur = (cur as Record<string, unknown>)[tok];
    } else {
      return undefined;
    }
  }
  return cur;
}

export function solve(a: string, b: string): number {
  if (a.length < b.length) [a, b] = [b, a];
  let prev: number[] = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur: number[] = [i];
    for (let j = 1; j <= b.length; j++) {
      const cost = a.charCodeAt(i - 1) === b.charCodeAt(j - 1) ? 0 : 1;
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost);
    }
    prev = cur;
  }
  return prev[b.length];
}

export function solve(text: string): boolean {
  const s = /^\(.*\)$/.test(text) ? text.slice(1, -1) : text;
  const num = '([+\\-\u2212]?(?:\\d+\\.?\\d*|\\.\\d+))';
  const m = new RegExp(`^${num},  *${num}$`.replace('  *', ' *')).exec(s);
  if (!m) return false;
  const v = (t: string) => Number(t.replace('\u2212', '-'));
  const lat = v(m[1]);
  const lon = v(m[2]);
  return Math.abs(lat) <= 90 && Math.abs(lon) <= 180;
}

export function solve(name: string): boolean {
  if (name.length > 253 || name.endsWith('.')) return false;
  const labels = name.split('.');
  if (labels.length < 2) return false;
  const label = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/;
  const tld = labels[labels.length - 1];
  if (!labels.slice(0, -1).every(l => label.test(l))) return false;
  if (/^xn--/i.test(tld)) return label.test(tld);
  return /^\p{L}{2,63}$/u.test(tld);
}

export function solve<T>(value: T): T {
  return lib.cloneDeep(value) as T;
