export function solve(installed: string[], range: string): string | null {
  // lib.maxSatisfying skips any entry that Range.test rejects, which includes
  // strings that are not valid versions. It returns null for an invalid range
  // or when nothing matches.
  const result: string | null = lib.maxSatisfying(installed, range, undefined)
  return result ?? null
}

