export function solve(text: string): string {
    // Encode the string as UTF-8 manually (no TextEncoder, which is not part of ECMAScript).
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < text.length) {
            const next = text.charCodeAt(i + 1);
            if (next >= 0xdc00 && next <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
                i++;
            } else {
                cp = 0xfffd; // lone high surrogate
            }
        } else if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd; // lone low surrogate
        }

        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            bytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            bytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    // Delegate the MD5 computation to the library function.
    const digest: ArrayLike<number> = lib.md5(Uint8Array.from(bytes));

    // Convert the 16 digest bytes to 32 lowercase hex characters.
    return Array.from(digest, (b: number) => b.toString(16).padStart(2, "0")).join("");
}

export function solve(urls: string[]): string[] {
  const options = {
    protocols: ['http', 'https'],
    require_protocol: true,
    require_valid_protocol: true,
    require_tld: true,
    allow_underscores: false,
    allow_fragments: true,
    allow_query_components: true,
    validate_length: true,
  };

  // Captures: 1 = scheme, 2 = host (optionally preceded by userinfo), 3 = port
  const urlPattern = /^(https?):\/\/(?:[^\s@\/?#]*@)?([^\/?#:]+)(?::(\d{1,5}))?(?=[\/?#]|$)/i;

  const isFullyQualifiedDomain = (host: string): boolean => {
    const labels = host.split('.');
    if (labels.length < 2) {
      return false;
    }
    const tld = labels[labels.length - 1];
    if (!/^[a-z]{2,63}$/i.test(tld)) {
      return false;
    }
    return labels.every((label) => /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/i.test(label));
  };

  return urls.filter((url) => {
    if (!lib.isURL(url, options)) {
      return false;
    }

    const match = urlPattern.exec(url);
    if (!match) {
      return false;
    }

    const host = match[2];
    const port = match[3];
    if (port !== undefined && Number(port) > 65535) {
      return false;
    }

    return isFullyQualifiedDomain(host);
  });
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 input: length must be a multiple of 4");
  }
  return Array.from(lib.toByteArray(text));
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  // lib.toposort throws on unknown nodes and on cyclic dependencies.
  return lib.toposort(nodes, edges);
}

export function solve(a: string, b: string): boolean {
  return lib.intersects(a, b);
}

export function solve(range: string): string | null {
  try {
    const minver = lib.minVersion(range);
    return minver ? minver.version : null;
  } catch {
    // An invalid range makes the library throw; report it as "no version".
    return null;
  }
}

export function solve(epochMs: number): string {
  // lib.formatISO reads the local-time fields of a Date. To get UTC fields,
  // shift the instant so its local fields equal the UTC fields of epochMs.
  // The shift depends on the offset at the shifted instant (DST), so iterate
  // to a fixed point. Flooring first keeps sub-second handling consistent.
  const t = Math.floor(epochMs);
  let d = t;
  for (let i = 0; i < 3; i++) {
    const offset = new Date(d).getTimezoneOffset(); // minutes, UTC - local
    const next = t + offset * 60000;
    if (next === d) break;
    d = next;
  }

  // Use the library for the heavy lifting. Its output is
  // "yyyy-MM-ddTHH:mm:ss" followed by a local offset suffix, which we drop.
  const local = lib.formatISO(new Date(d), { representation: "complete" });
  return local.slice(0, 19) + "Z";
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  return lib.inc(version, kind, id) ?? null;
}

export function solve(version: string, range: string): boolean {
  return lib.gtr(version, range);
}

const GMAIL_DOMAINS = new Set(['gmail.com', 'googlemail.com']);
const PLUS_SUFFIX_DOMAINS = new Set(['outlook.com', 'hotmail.com', 'live.com']);

// Disable every library-side removal so only the flags we need are enabled per call.
// This keeps the library from stripping suffixes on domains outside the spec
// (e.g. msn.com is in the library's Outlook list).
const NO_REMOVALS = {
  gmail_remove_subaddress: false,
  gmail_remove_dots: false,
  gmail_convert_googlemaildotcom: false,
  icloud_remove_subaddress: false,
  outlookdotcom_remove_subaddress: false,
  yahoo_remove_subaddress: false,
  yandex_convert_yandexru: false,
};

function canonicalize(raw: string): string {
  const at = raw.lastIndexOf('@');
  if (at < 0) {
    return raw.toLowerCase();
  }
  const domain = raw.slice(at + 1).toLowerCase();

  if (GMAIL_DOMAINS.has(domain)) {
    const r = lib.normalizeEmail(raw, {
      ...NO_REMOVALS,
      all_lowercase: true,
      gmail_remove_subaddress: true,
      gmail_convert_googlemaildotcom: true,
    });
    // The library keeps consecutive dots; the spec says to remove all dots,
    // so strip them from the local part here.
    const user = r === false ? '' : r.slice(0, r.lastIndexOf('@')).replace(/\./g, '');
    return `${user}@gmail.com`;
  }

  if (PLUS_SUFFIX_DOMAINS.has(domain)) {
    const r = lib.normalizeEmail(raw, {
      ...NO_REMOVALS,
      all_lowercase: true,
      outlookdotcom_remove_subaddress: true,
    });
    // false means the local part was empty after processing
    return r === false ? `@${domain}` : r;
  }

  // Any other domain: lowercase only
  const r = lib.normalizeEmail(raw, {
    ...NO_REMOVALS,
    all_lowercase: true,
  });
  return r === false ? `@${domain}` : r;
}

export function solve(emails: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const email of emails) {
    const canonical = canonicalize(email);
    if (!seen.has(canonical)) {
      seen.add(canonical);
      result.push(canonical);
    }
  }
  return result;
}

export function solve(name: string, namespace: string): string {
  const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (typeof namespace !== "string" || !uuidPattern.test(namespace)) {
    throw new TypeError(`Invalid namespace UUID: ${String(namespace)}`);
  }
  return lib.v3(name, namespace.toLowerCase()).toLowerCase();
}

export function solve(text: string): string | null {
  // Strip leading zeros from digit runs of at most 16 digits so that inputs
  // like "v01.02" are accepted by the library's strict version parser.
  // Longer runs are left untouched so the 16-digit limit is preserved.
  const normalized = text.replace(/\d+/g, (run: string): string =>
    run.length <= 16 ? run.replace(/^0+(?=\d)/, '') : run
  );

  const v = lib.coerce(normalized);
  if (v === null || v === undefined) {
    return null;
  }

  return `${v.major}.${v.minor}.${v.patch}`;
}

export function solve(iban: string): boolean {
  if (typeof iban !== "string") return false;
  const normalized = iban.replace(/[\s-]/g, "").toUpperCase();
  return lib.isIBAN(normalized);
}

export function solve(stamps: string[]): number[] {
  // Calendar, week, or ordinal date, optionally followed by a time with
  // optional fractional seconds and an optional Z or ±hh:mm offset.
  const PATTERN =
    /^(\d{4}-\d{2}-\d{2}|\d{4}-W\d{2}-\d|\d{4}-\d{3})(?:[T ]\d{2}:\d{2}(?::\d{2}(?:\.\d+)?)?(Z|[+-]\d{2}:\d{2})?)?$/;

  return stamps
    .map((s) => {
      const m = PATTERN.exec(s);
      if (m === null) {
        throw new RangeError(`Invalid ISO 8601 date: ${s}`);
      }

      // lib.parseISO interprets strings without an offset in local time,
      // but the spec requires UTC, so an explicit "Z" is appended when no
      // offset is present.
      const normalized = m[2] === undefined ? `${s}Z` : s;

      const ms = +lib.parseISO(normalized);
      if (Number.isNaN(ms)) {
        throw new RangeError(`Invalid ISO 8601 date: ${s}`);
      }
      return ms;
    })
    .sort((a, b) => a - b);
}

export function solve(text: string): string {
    // Encode the string as UTF-8 manually (no TextEncoder, which is not ECMAScript).
    // Lone surrogates are replaced with U+FFFD, matching TextEncoder behavior.
    const out: number[] = [];
    for (const ch of text) {
        let cp = ch.codePointAt(0)!;
        if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd;
        }
        if (cp < 0x80) {
            out.push(cp);
        } else if (cp < 0x800) {
            out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            out.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            out.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    const digest = lib.sha1(Uint8Array.from(out));

    let hex = "";
    for (let i = 0; i < digest.length; i++) {
        hex += digest[i].toString(16).padStart(2, "0");
    }
    return hex;
}

export function solve(text: string, version?: 4 | 6): boolean {
  const wantV4 = version === undefined || version === 4;
  const wantV6 = version === undefined || version === 6;

  // lib.isIP's IPv4 pattern accepts leading zeros ("01"), which the spec forbids.
  const hasNoLeadingZeros = (dotted: string): boolean =>
    dotted.split('.').every((octet) => octet.length === 1 || octet[0] !== '0');

  const checkV4 = (s: string): boolean =>
    wantV4 && lib.isIP(s, { version: 4 }) && hasNoLeadingZeros(s);

  const checkV6 = (s: string): boolean => {
    if (!wantV6) return false;

    let addr = s;

    // Optional zone index: only valid after a link-local address (fe80::/10).
    const pct = s.indexOf('%');
    if (pct !== -1) {
      addr = s.slice(0, pct);
      const zone = s.slice(pct + 1);
      if (!/^[A-Za-z0-9]+$/.test(zone)) return false;
      if (addr.startsWith('::')) return false;
      const first = parseInt(addr.split(':')[0], 16);
      if (Number.isNaN(first) || (first & 0xffc0) !== 0xfe80) return false;
    }

    // Core syntax (groups, single "::", embedded IPv4) is delegated to the library.
    if (!lib.isIP(addr, { version: 6 })) return false;

    // Embedded IPv4 tail must also obey the no-leading-zeros rule.
    const tail = addr.slice(addr.lastIndexOf(':') + 1);
    const hasV4Tail = tail.includes('.');
    if (hasV4Tail && !hasNoLeadingZeros(tail)) return false;

    // Count groups: each hextet is 1, a dotted IPv4 tail is 2.
    const units =
      addr.split(':').filter((p) => p !== '').length + (hasV4Tail ? 1 : 0);

    // "::" must stand for at least one zero group; without it, exactly 8 groups.
    if (addr.includes('::')) return units <= 7;
    return units === 8;
  };

  return checkV4(text) || checkV6(text);
}

export function solve(isin: string): boolean {
  if (typeof isin !== "string") {
    return false;
  }
  return lib.isISIN(isin);
}

type ParsedVersion = {
  major: string;
  minor: string;
  patch: string;
  pre: string | null;
};

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

function parseVersion(v: string): ParsedVersion | null {
  const m = SEMVER_RE.exec(v);
  if (!m) return null;
  return {
    major: m[1],
    minor: m[2],
    patch: m[3],
    pre: m[4] ?? null,
  };
}

// Compare numeric strings without leading zeros (avoids precision loss).
function cmpNumeric(a: string, b: string): number {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

function cmpIdentifierIsNumeric(s: string): boolean {
  return /^\d+$/.test(s);
}

function cmpPrerelease(a: string | null, b: string | null): number {
  if (a === null && b === null) return 0;
  if (a === null) return 1; // release > prerelease
  if (b === null) return -1;

  const ai = a.split(".");
  const bi = b.split(".");
  const n = Math.min(ai.length, bi.length);

  for (let i = 0; i < n; i++) {
    const x = ai[i];
    const y = bi[i];
    if (x === y) continue;

    const xNum = cmpIdentifierIsNumeric(x);
    const yNum = cmpIdentifierIsNumeric(y);

    if (xNum && yNum) return cmpNumeric(x, y);
    if (xNum) return -1; // numeric < alphanumeric
    if (yNum) return 1;
    return x < y ? -1 : 1; // ASCII lexical
  }

  // All shared identifiers equal: shorter list is lower
  if (ai.length === bi.length) return 0;
  return ai.length < bi.length ? -1 : 1;
}

function cmpPrecedence(a: ParsedVersion, b: ParsedVersion): number {
  return (
    cmpNumeric(a.major, b.major) ||
    cmpNumeric(a.minor, b.minor) ||
    cmpNumeric(a.patch, b.patch) ||
    cmpPrerelease(a.pre, b.pre)
  );
}

export function solve(versions: string[]): string[] {
  // Keep only valid semver versions (a new array).
  const valid = versions.filter((v) => SEMVER_RE.test(v));

  // Heavy lifting via the library sort (sorts in place on our own copy).
  const sorted = lib.sort(valid, false);

  // Ensure the full specified ordering: precedence first, then ties broken
  // lexically by the full version string (build metadata order).
  const parsed = new Map<string, ParsedVersion>();
  for (const v of sorted) {
    if (!parsed.has(v)) {
      const p = parseVersion(v);
      if (p) parsed.set(v, p);
    }
  }

  return [...sorted].sort((a, b) => {
    const pa = parsed.get(a);
    const pb = parsed.get(b);
    if (!pa || !pb) return 0;
    const byPrecedence = cmpPrecedence(pa, pb);
    if (byPrecedence !== 0) return byPrecedence;
    return a < b ? -1 : a > b ? 1 : 0;
  });
}

export function solve(a: string, b: string): string | null {
  // Let the library do the heavy lifting (handles equality, prerelease
  // rules, and the `pre` prefixing).
  const result = lib.diff(a, b);
  if (result === null) {
    return null;
  }

  // Extract the numeric core and prerelease flag, ignoring build metadata.
  const parse = (v: string): { nums: [number, number, number]; pre: boolean } => {
    const noBuild = v.split('+')[0];
    const dash = noBuild.indexOf('-');
    const main = dash === -1 ? noBuild : noBuild.slice(0, dash);
    const [M, m, p] = main.split('.').map(Number) as [number, number, number];
    return { nums: [M, m, p], pre: dash !== -1 };
  };

  const A = parse(a);
  const B = parse(b);

  // Compare cores only (build metadata and prerelease are not relevant here).
  let c = 0;
  for (let i = 0; i < 3; i++) {
    if (A.nums[i] !== B.nums[i]) {
      c = A.nums[i] - B.nums[i];
      break;
    }
  }

  // Equal cores: the library's answer already follows the specified rules.
  if (c === 0) {
    return result;
  }

  const low = c < 0 ? A : B;
  const high = c < 0 ? B : A;

  // Specified rule: when going from a prerelease to a release, the answer is
  // the highest differing core part. The library reports `major` whenever the
  // lower core has minor and patch of 0, even if only minor/patch changed.
  // Only `major` should be reported when the major part actually differs.
  if (
    low.pre &&
    !high.pre &&
    low.nums[1] === 0 &&
    low.nums[2] === 0 &&
    low.nums[0] === high.nums[0]
  ) {
    return high.nums[1] !== low.nums[1] ? 'minor' : 'patch';
  }

  return result;
}

export function solve(mac: string): boolean {
  if (typeof mac !== 'string') return false;
  // The library accepts ':' and '-' mixed within one address, so separator
  // consistency is checked separately below.
  if (!lib.isMACAddress(mac)) return false;
  // Dotted form (0123.4567.89ab): the library only accepts consistent dots.
  if (mac.includes('.')) return true;
  // Colon/hyphen form: every non-hex character must be the same separator.
  const seps = mac.replace(/[0-9a-fA-F]/g, '');
  return seps.length > 0 && seps.split('').every((c) => c === seps[0]);
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  if (version === undefined) {
    return lib.isISBN(isbn);
  }
  if (version !== 10 && version !== 13) {
    return false;
  }
  return lib.isISBN(isbn, { version });
}

export function solve(text: string, version?: 4 | 6): boolean {
  if (typeof text !== 'string') return false;

  const wantV4 = version === undefined || version === 4;
  const wantV6 = version === undefined || version === 6;

  if (wantV4 && lib.isIP(text, 4)) return true;
  if (!wantV6) return false;

  const pct = text.indexOf('%');
  if (pct === -1) return lib.isIP(text, 6);

  // Zone index: only valid after a link-local IPv6 address.
  const addr = text.slice(0, pct);
  const zone = text.slice(pct + 1);
  if (!/^[0-9A-Za-z]+$/.test(zone)) return false;
  if (!lib.isIP(addr, 6)) return false;
  return isLinkLocalIPv6(addr);
}

// Link-local unicast is fe80::/10, i.e. the first hextet is in 0xfe80..0xfebf.
function isLinkLocalIPv6(addr: string): boolean {
  const first = addr.split(':')[0];
  if (first === '') return false; // address begins with "::" -> first hextet is 0
  const value = parseInt(first, 16);
  return value >= 0xfe80 && value <= 0xfebf;
}

export function solve(issn: string): boolean {
  if (typeof issn !== 'string') {
    return false;
  }
  return lib.isISSN(issn);
}

export function solve(code: string): boolean {
  // Only ASCII digits are allowed.
  if (!/^[0-9]+$/.test(code)) return false;

  switch (code.length) {
    case 8:
    case 13:
      // lib.isEAN handles EAN-8 and EAN-13 directly.
      return lib.isEAN(code);

    case 14: {
      // GTIN-14 check: weights 3 and 1 alternating from the rightmost data digit.
      // lib.isEAN does not accept 14-digit input, so compute it here.
      let sum = 0;
      for (let i = 0; i < 13; i++) {
        const digit = code.charCodeAt(i) - 48;
        const fromRight = 12 - i; // index 12 is the rightmost data digit
        sum += digit * (fromRight % 2 === 0 ? 3 : 1);
      }
      const check = (10 - (sum % 10)) % 10;
      return check === code.charCodeAt(13) - 48;
    }

    default:
      return false;
  }
}

export function solve(a: string, b: string): number {
    return lib.distance(a, b);
}

export function solve(text: string): boolean {
  if (typeof text !== 'string') return false;

  // Strip one pair of outer parentheses, if the whole text is wrapped in them.
  let inner: string = text;
  if (text.length >= 2 && text[0] === '(' && text[text.length - 1] === ')') {
    inner = text.slice(1, -1);
  }

  // Any remaining parentheses are invalid (only one wrapping pair is allowed).
  if (/[()]/.test(inner)) return false;

  // Exactly one comma separates latitude and longitude.
  const parts = inner.split(',');
  if (parts.length !== 2) return false;

  const lat = parts[0];
  // Allow optional spaces after the comma; nothing else is stripped.
  const lng = parts[1].replace(/^ +/, '');

  // Delegate the numeric/format validation (sign, decimals, ranges) to the library.
  return lib.isLatLong(`${lat},${lng}`);
}

// lib.isCreditCard is not used: its issuer table differs from the spec
// (e.g. it only allows 16-digit Discover, 14-digit Diners, and 16-digit
// JCB/Visa-length rules), so it would reject valid numbers the spec accepts.
// Prefix/length rules and the Luhn check are implemented here directly.
export function solve(card: string): boolean {
  const digits = card.replace(/[ -]/g, "");
  if (!/^\d+$/.test(digits)) return false;

  const len = digits.length;

  // Numeric value of the first n digits, or NaN if the card is too short.
  const p = (n: number): number =>
    len >= n ? Number(digits.slice(0, n)) : NaN;

  const between = (n: number, lo: number, hi: number): boolean => {
    const v = p(n);
    return v >= lo && v <= hi;
  };

  const visa =
    p(1) === 4 && (len === 13 || len === 16 || len === 19);

  const mastercard =
    (between(2, 51, 55) || between(4, 2221, 2720)) && len === 16;

  const amex =
    (p(2) === 34 || p(2) === 37) && len === 15;

  const discover =
    (p(4) === 6011 ||
      between(6, 622126, 622925) ||
      between(3, 644, 649) ||
      p(2) === 65) &&
    (len === 16 || len === 19);

  const diners =
    (between(3, 300, 305) || p(2) === 36 || p(2) === 38) &&
    len >= 14 && len <= 19;

  const jcb =
    between(4, 3528, 3589) && len >= 16 && len <= 19;

  const unionpay =
    p(2) === 62 && len >= 16 && len <= 19;

  if (!(visa || mastercard || amex || discover || diners || jcb || unionpay)) {
    return false;
  }

  // Luhn check
  let sum = 0;
  let double = false;
  for (let i = len - 1; i >= 0; i--) {
    let n = digits.charCodeAt(i) - 48;
    if (double) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    double = !double;
  }
  return sum % 10 === 0;
}

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === '') return doc;
  if (!pointer.startsWith('/')) {
    throw new Error('Invalid JSON pointer: must be empty or start with "/".');
  }

  // lib.get throws on non-object documents and on null, so handle those here.
  if (typeof doc !== 'object' || doc === null) return undefined;

  // lib.get reads inherited properties (e.g. "/toString") and array
  // "length" or "-" as ordinary members. Verify each step is a real
  // member or valid array index before delegating to lib.get.
  const tokens = pointer
    .slice(1)
    .split('/')
    .map((t) => t.replace(/~1/g, '/').replace(/~0/g, '~'));

  let cur: unknown = doc;
  for (const tok of tokens) {
    if (typeof cur !== 'object' || cur === null) return undefined;
    if (Array.isArray(cur)) {
      if (!/^(0|[1-9]\d*)$/.test(tok) || Number(tok) >= cur.length) return undefined;
    } else if (!Object.prototype.hasOwnProperty.call(cur, tok)) {
      return undefined;
    }
    cur = (cur as Record<string, unknown>)[tok];
  }

  return lib.get(doc, pointer);
}

const PLUS_SUFFIX_DOMAINS = new Set<string>(["outlook.com", "hotmail.com", "live.com"]);
const GMAIL_DOMAINS = new Set<string>(["gmail.com", "googlemail.com"]);

function stripPlusSuffix(local: string): string {
  const plus = local.indexOf("+");
  return plus === -1 ? local : local.slice(0, plus);
}

export function solve(emails: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];

  for (const raw of emails) {
    const lower = raw.toLowerCase();
    const at = lower.lastIndexOf("@");

    let canonical: string;
    if (at === -1) {
      canonical = lower;
    } else {
      let local = lower.slice(0, at);
      let domain = lower.slice(at + 1);

      if (GMAIL_DOMAINS.has(domain)) {
        local = stripPlusSuffix(local).replace(/\./g, "");
        domain = "gmail.com";
      } else if (PLUS_SUFFIX_DOMAINS.has(domain)) {
        local = stripPlusSuffix(local);
      }

      canonical = `${local}@${domain}`;
    }

    if (!seen.has(canonical)) {
      seen.add(canonical);
      result.push(canonical);
    }
  }

  return result;
}

export function solve(name: string): boolean {
  if (typeof name !== "string") return false;

  // Total length limit (lib.isFQDN does not enforce this)
  if (name.length === 0 || name.length > 253) return false;

  // No trailing dot
  if (name.endsWith(".")) return false;

  // Heavy lifting: structural checks delegated to the library
  if (
    !lib.isFQDN(name, {
      require_tld: true,
      allow_trailing_dot: false,
      allow_wildcard: false,
      allow_numeric_tld: false,
      allow_underscores: false,
      ignore_max_length: false,
    })
  ) {
    return false;
  }

  const labels = name.split(".");

  // At least two labels
  if (labels.length < 2) return false;

  // Per-label rules: 1–63 chars, no leading/trailing hyphen
  for (const label of labels) {
    if (label.length < 1 || label.length > 63) return false;
    if (label.startsWith("-") || label.endsWith("-")) return false;
  }

  // Non-TLD labels: ASCII letters, digits and hyphens only (no underscores)
  for (let i = 0; i < labels.length - 1; i++) {
    if (!/^[A-Za-z0-9-]+$/.test(labels[i])) return false;
  }

  // TLD rules
  const tld = labels[labels.length - 1];
  if (tld.length < 2) return false;

  if (/^xn--/i.test(tld)) {
    // Punycode TLD: xn-- followed by ASCII letters, digits or hyphens
    if (!/^xn--[A-Za-z0-9-]*$/i.test(tld)) return false;
  } else {
    // Otherwise the TLD must be entirely letters (international letters allowed)
    if (!/^\p{L}{2,}$/u.test(tld)) return false;
  }

  return true;
}

type Key = string | number;
type Container = Record<string | number, unknown>;

function parsePath(path: string): Key[] {
  const keys: Key[] = [];
  let buf = "";
  const flush = (): void => {
    if (buf !== "") {
      keys.push(buf);
      buf = "";
    }
  };

  let i = 0;
  while (i < path.length) {
    const c = path[i];
    if (c === ".") {
      flush();
      i++;
    } else if (c === "[") {
      flush();
      i++; // skip '['
      const q = path[i];
      if (q === '"' || q === "'") {
        i++; // skip opening quote
        let s = "";
        while (i < path.length && path[i] !== q) {
          if (path[i] === "\\" && i + 1 < path.length) {
            s += path[i + 1];
            i += 2;
          } else {
            s += path[i];
            i++;
          }
        }
        if (i >= path.length) throw new SyntaxError(`Unterminated quoted key in path: ${path}`);
        i++; // skip closing quote
        if (path[i] !== "]") throw new SyntaxError(`Expected ']' in path: ${path}`);
        i++;
        keys.push(s);
      } else {
        const end = path.indexOf("]", i);
        if (end === -1) throw new SyntaxError(`Unterminated '[' in path: ${path}`);
        const content = path.slice(i, end).trim();
        i = end + 1;
        keys.push(/^\d+$/.test(content) ? Number(content) : content);
      }
    } else {
      buf += c;
      i++;
    }
  }
  flush();
  return keys;
}

function isIndex(key: Key): boolean {
  if (typeof key === "number") return Number.isInteger(key) && key >= 0;
  return /^(0|[1-9]\d*)$/.test(key);
}

function assertSafeKey(key: Key): void {
  if (key === "__proto__") {
    throw new TypeError("Refusing to write to '__proto__'");
  }
}

export function solve(
  obj: object,
  updates: [string | (string | number)[], unknown][]
): object {
  for (const [path, value] of updates) {
    const keys: Key[] = typeof path === "string" ? parsePath(path) : path;
    if (keys.length === 0) continue;

    let cur = obj as Container;
    for (let i = 0; i < keys.length - 1; i++) {
      const key = keys[i];
      assertSafeKey(key);
      let next = cur[key] as unknown;
      if (typeof next !== "object" || next === null) {
        next = isIndex(keys[i + 1]) ? [] : {};
        cur[key] = next;
      }
      cur = next as Container;
    }

    const last = keys[keys.length - 1];
    assertSafeKey(last);
    cur[last] = value;
  }
  return obj;
}

export function solve(urls: string[]): string[] {
  // Scheme: http or https (case-insensitive).
  // Optional userinfo (no whitespace, no '@', '/', '?', '#' before the '@').
  // Host: one or more labels of letters/digits/hyphens (no leading or trailing hyphen),
  //       followed by a TLD that is alphabetic (2-63 chars) or a punycode "xn--" label.
  //       IP addresses are rejected because the TLD must contain letters.
  // Optional port of 1-5 digits (range checked separately).
  // Optional path, query, or fragment with no whitespace.
  const pattern =
    /^https?:\/\/(?:[^\s@/?#]+@)?((?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+(?:[a-z]{2,63}|xn--[a-z0-9-]{1,59}[a-z0-9]))(?::(\d{1,5}))?(?:[/?#]\S*)?$/i;

  const result: string[] = [];

  for (const url of urls) {
    const match = pattern.exec(url);
    if (!match) continue;

    const host = match[1];
    const port = match[2];

    if (host.length > 253) continue;
    if (port !== undefined && Number(port) > 65535) continue;

    result.push(url);
  }

  return result;
}

export function solve(word: string, dictionary: string[]): string {
  if (dictionary.length === 0) return "";

  let best = dictionary[0];
  let bestDist = levenshtein(word, best);

  for (let i = 1; i < dictionary.length; i++) {
    if (bestDist === 0) break; // exact match found; the first one already wins ties
    const d = levenshtein(word, dictionary[i]);
    if (d < bestDist) {
      bestDist = d;
      best = dictionary[i];
    }
  }

  return best;
}

function levenshtein(a: string, b: string): number {
  if (a === b) return 0;
  const m = a.length;
  const n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;

  let prev: number[] = new Array<number>(n + 1);
  let curr: number[] = new Array<number>(n + 1);

  for (let j = 0; j <= n; j++) prev[j] = j;

  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(
        prev[j] + 1,        // deletion
        curr[j - 1] + 1,    // insertion
        prev[j - 1] + cost  // substitution (or match)
      );
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[n];
}

type Seen = Map<object, unknown>;

function cloneValue(input: unknown, seen: Seen): unknown {
  // Primitives and functions are returned as-is.
  if (typeof input !== "object" || input === null) {
    return input;
  }

  // Already copied (or currently being copied): reuse the copy.
  // This is what preserves circular and shared references.
  if (seen.has(input)) {
    return seen.get(input);
  }

  if (input instanceof Date) {
    const copy = new Date(input.getTime());
    seen.set(input, copy);
    return copy;
  }

  if (input instanceof RegExp) {
    const copy = new RegExp(input.source, input.flags);
    copy.lastIndex = input.lastIndex;
    seen.set(input, copy);
    return copy;
  }

  if (input instanceof Map) {
    const copy = new Map<unknown, unknown>();
    seen.set(input, copy); // register before recursing to handle cycles
    input.forEach((v, k) => {
      copy.set(cloneValue(k, seen), cloneValue(v, seen));
    });
    return copy;
  }

  if (input instanceof Set) {
    const copy = new Set<unknown>();
    seen.set(input, copy);
    input.forEach((v) => {
      copy.add(cloneValue(v, seen));
    });
    return copy;
  }

  if (input instanceof ArrayBuffer) {
    const copy = input.slice(0);
    seen.set(input, copy);
    return copy;
  }

  if (ArrayBuffer.isView(input)) {
    const source = input as ArrayBufferView;
    const srcBuffer = source.buffer;

    // Shared buffers stay shared by definition; regular buffers are copied once
    // and reused by every view that references them.
    const buffer: ArrayBuffer =
      srcBuffer instanceof ArrayBuffer
        ? (cloneValue(srcBuffer, seen) as ArrayBuffer)
        : (srcBuffer as ArrayBuffer);

    if (source instanceof DataView) {
      const copy = new DataView(buffer, source.byteOffset, source.byteLength);
      seen.set(input, copy);
      return copy;
    }

    const Ctor = source.constructor as new (
      buffer: ArrayBuffer,
      byteOffset: number,
      length: number
    ) => ArrayBufferView;
    const length = (source as unknown as { length: number }).length;
    const copy = new Ctor(buffer, source.byteOffset, length);
    seen.set(input, copy);
    return copy;
  }

  if (Array.isArray(input)) {
    const copy: unknown[] = new Array(input.length);
    seen.set(input, copy);
    copyOwnProperties(input, copy, seen, ["length"]);
    return copy;
  }

  // Plain objects and class instances: keep the prototype, copy own properties.
  const copy = Object.create(Object.getPrototypeOf(input)) as object;
  seen.set(input, copy);
  copyOwnProperties(input, copy, seen, []);
  return copy;
}

function copyOwnProperties(
  source: object,
  target: object,
  seen: Seen,
  skip: PropertyKey[]
): void {
  for (const key of Reflect.ownKeys(source)) {
    if (skip.includes(key)) {
      continue;
    }
    const descriptor = Object.getOwnPropertyDescriptor(source, key);
    if (!descriptor) {
      continue;
    }
    if ("value" in descriptor) {
      descriptor.value = cloneValue(descriptor.value, seen);
    }
    Object.defineProperty(target, key, descriptor);
  }
}

export function solve<T>(value: T): T {
  return cloneValue(value, new Map()) as T;
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  const index = new Map<string, number>();
  nodes.forEach((name, i) => {
    if (index.has(name)) {
      throw new Error(`Duplicate node: ${name}`);
    }
    index.set(name, i);
  });

  const n = nodes.length;
  const adj: number[][] = Array.from({ length: n }, () => [] as number[]);
  const indegree: number[] = new Array<number>(n).fill(0);

  for (const [a, b] of edges) {
    const ia = index.get(a);
    const ib = index.get(b);
    if (ia === undefined) {
      throw new Error(`Edge references unknown node: ${a}`);
    }
    if (ib === undefined) {
      throw new Error(`Edge references unknown node: ${b}`);
    }
    adj[ia].push(ib);
    indegree[ib]++;
  }

  // Min-heap of available node indices, so ties are broken by input order.
  const heap: number[] = [];

  const heapPush = (v: number): void => {
    heap.push(v);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p] <= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };

  const heapPop = (): number => {
    const top = heap[0];
    const last = heap.pop() as number;
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let m = i;
        if (l < heap.length && heap[l] < heap[m]) m = l;
        if (r < heap.length && heap[r] < heap[m]) m = r;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]];
        i = m;
      }
    }
    return top;
  };

  for (let i = 0; i < n; i++) {
    if (indegree[i] === 0) heapPush(i);
  }

  const result: string[] = [];
  while (heap.length > 0) {
    const v = heapPop();
    result.push(nodes[v]);
    for (const w of adj[v]) {
      indegree[w]--;
      if (indegree[w] === 0) heapPush(w);
    }
  }

  if (result.length !== n) {
    throw new Error("Cycle detected in edges");
  }

  return result;
}

const BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function base64Value(ch: string): number {
  const index = ch.length === 1 ? BASE64_ALPHABET.indexOf(ch) : -1;
  if (index < 0) {
    throw new Error(`Invalid base64 character: ${JSON.stringify(ch)}`);
  }
  return index;
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 length: must be a multiple of 4");
  }

  const bytes: number[] = [];

  for (let i = 0; i < text.length; i += 4) {
    const c0 = text.charAt(i);
    const c1 = text.charAt(i + 1);
    const c2 = text.charAt(i + 2);
    const c3 = text.charAt(i + 3);

    const isLastQuad = i + 4 === text.length;
    const pad2 = c2 === "=";
    const pad3 = c3 === "=";

    if ((pad2 || pad3) && !isLastQuad) {
      throw new Error("Invalid base64: padding found before end of input");
    }
    if (pad2 && !pad3) {
      throw new Error("Invalid base64: incorrect padding");
    }

    const v0 = base64Value(c0);
    const v1 = base64Value(c1);
    const v2 = pad2 ? 0 : base64Value(c2);
    const v3 = pad3 ? 0 : base64Value(c3);

    bytes.push(((v0 << 2) | (v1 >> 4)) & 0xff);

    if (!pad2) {
      bytes.push((((v1 & 0x0f) << 4) | (v2 >> 2)) & 0xff);
    }

    if (!pad3) {
      bytes.push((((v2 & 0x03) << 6) | v3) & 0xff);
    }
  }

  return bytes;
}

export function solve(name: string, namespace: string): string {
  // Parse the namespace UUID into 16 bytes.
  const nsHex = namespace.replace(/-/g, "");
  if (!/^[0-9a-fA-F]{32}$/.test(nsHex)) {
    throw new Error("invalid namespace UUID");
  }
  const nsBytes: number[] = [];
  for (let i = 0; i < 32; i += 2) {
    nsBytes.push(parseInt(nsHex.slice(i, i + 2), 16));
  }

  // UTF-8 encode the name manually (lone surrogates become U+FFFD).
  const nameBytes = utf8Encode(name);

  // Message = namespace bytes || name bytes.
  const msg = new Uint8Array(nsBytes.length + nameBytes.length);
  msg.set(nsBytes, 0);
  msg.set(nameBytes, nsBytes.length);

  // SHA-1 and truncate to 16 bytes.
  const digest = sha1(msg);
  const out = digest.slice(0, 16);

  // Set version (5) and RFC 4122 variant bits.
  out[6] = (out[6] & 0x0f) | 0x50;
  out[8] = (out[8] & 0x3f) | 0x80;

  // Format as lowercase 8-4-4-4-12.
  const hex: string[] = [];
  for (let i = 0; i < 16; i++) {
    hex.push(out[i].toString(16).padStart(2, "0"));
  }
  const s = hex.join("");
  return (
    s.slice(0, 8) + "-" +
    s.slice(8, 12) + "-" +
    s.slice(12, 16) + "-" +
    s.slice(16, 20) + "-" +
    s.slice(20, 32)
  );
}

function utf8Encode(str: string): number[] {
  const bytes: number[] = [];
  for (const ch of str) {
    let cp = ch.codePointAt(0) as number;
    if (cp >= 0xd800 && cp <= 0xdfff) {
      cp = 0xfffd;
    }
    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }
  return bytes;
}

function rotl(x: number, n: number): number {
  return ((x << n) | (x >>> (32 - n))) >>> 0;
}

function sha1(data: Uint8Array): Uint8Array {
  const bitLen = data.length * 8;
  const total = Math.ceil((data.length + 9) / 64) * 64;
  const buf = new Uint8Array(total);
  buf.set(data, 0);
  buf[data.length] = 0x80;

  // 64-bit big-endian message length in bits.
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  for (let i = 0; i < 4; i++) {
    buf[total - 8 + i] = (hi >>> (24 - 8 * i)) & 0xff;
    buf[total - 4 + i] = (lo >>> (24 - 8 * i)) & 0xff;
  }

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  const w = new Uint32Array(80);

  for (let off = 0; off < total; off += 64) {
    for (let i = 0; i < 16; i++) {
      const j = off + i * 4;
      w[i] =
        ((buf[j] << 24) | (buf[j + 1] << 16) | (buf[j + 2] << 8) | buf[j + 3]) >>> 0;
    }
    for (let i = 16; i < 80; i++) {
      w[i] = rotl(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let i = 0; i < 80; i++) {
      let f: number;
      let k: number;
      if (i < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (i < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (i < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (rotl(a, 5) + (f >>> 0) + e + k + w[i]) >>> 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }

  const out = new Uint8Array(20);
  const hs = [h0, h1, h2, h3, h4];
  for (let i = 0; i < 5; i++) {
    out[i * 4] = (hs[i] >>> 24) & 0xff;
    out[i * 4 + 1] = (hs[i] >>> 16) & 0xff;
    out[i * 4 + 2] = (hs[i] >>> 8) & 0xff;
    out[i * 4 + 3] = hs[i] & 0xff;
  }
  return out;
}

export function solve(epochMs: number): string {
  if (!Number.isFinite(epochMs)) {
    throw new RangeError("Invalid time value");
  }

  // Floor to an integer millisecond, then floor to a whole second using exact integer arithmetic.
  const whole = Math.floor(epochMs);
  const msPart = ((whole % 1000) + 1000) % 1000;
  const floored = whole - msPart;

  // toISOString always emits ".sssZ"; the milliseconds are now zero, so strip them.
  return new Date(floored).toISOString().replace(/\.000Z$/, "Z");
}

export function solve(text: string): string {
  // Encode the input as UTF-8 manually (lone surrogates become U+FFFD, as TextEncoder does).
  const bytes: number[] = [];
  for (const ch of text) {
    let cp = ch.codePointAt(0) as number;
    if (cp >= 0xd800 && cp <= 0xdfff) cp = 0xfffd;
    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  // Padding (RFC 1321 section 3.1 and 3.2)
  const origLen = bytes.length;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);

  const bitLo = (origLen * 8) >>> 0;
  const bitHi = Math.floor(origLen / 0x20000000) >>> 0;
  for (let i = 0; i < 4; i++) bytes.push((bitLo >>> (8 * i)) & 0xff);
  for (let i = 0; i < 4; i++) bytes.push((bitHi >>> (8 * i)) & 0xff);

  // Per-round shift amounts
  const S: number[] = [
    7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
    5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
    4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
    6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
  ];

  // K[i] = floor(|sin(i + 1)| * 2^32)
  const K: number[] = [];
  for (let i = 0; i < 64; i++) {
    K.push(Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296) >>> 0);
  }

  const rotl = (x: number, c: number): number => (x << c) | (x >>> (32 - c));

  let a0 = 0x67452301;
  let b0 = 0xefcdab89 | 0;
  let c0 = 0x98badcfe | 0;
  let d0 = 0x10325476;

  for (let off = 0; off < bytes.length; off += 64) {
    const M: number[] = new Array(16);
    for (let j = 0; j < 16; j++) {
      const p = off + 4 * j;
      M[j] =
        bytes[p] |
        (bytes[p + 1] << 8) |
        (bytes[p + 2] << 16) |
        (bytes[p + 3] << 24);
    }

    let A = a0;
    let B = b0;
    let C = c0;
    let D = d0;

    for (let i = 0; i < 64; i++) {
      let F: number;
      let g: number;
      if (i < 16) {
        F = (B & C) | (~B & D);
        g = i;
      } else if (i < 32) {
        F = (D & B) | (~D & C);
        g = (5 * i + 1) % 16;
      } else if (i < 48) {
        F = B ^ C ^ D;
        g = (3 * i + 5) % 16;
      } else {
        F = C ^ (B | ~D);
        g = (7 * i) % 16;
      }
      F = (F + A + K[i] + M[g]) | 0;
      A = D;
      D = C;
      C = B;
      B = (B + rotl(F, S[i])) | 0;
    }

    a0 = (a0 + A) | 0;
    b0 = (b0 + B) | 0;
    c0 = (c0 + C) | 0;
    d0 = (d0 + D) | 0;
  }

  // Output digest bytes in little-endian order for each word
  let out = "";
  for (const w of [a0, b0, c0, d0]) {
    for (let j = 0; j < 4; j++) {
      const byte = (w >>> (8 * j)) & 0xff;
      out += byte.toString(16).padStart(2, "0");
    }
  }
  return out;
}

const DAY_MS = 86_400_000;
const HOUR_MS = 3_600_000;
const MINUTE_MS = 60_000;

const PATTERN =
  /^(?:(\d{4})-(\d{2})-(\d{2})|(\d{4})-W(\d{2})-(\d)|(\d{4})-(\d{3}))(?:T(\d{2})(?::(\d{2})(?::(\d{2})(?:[.,](\d+))?)?)?(Z|[+-]\d{2}:\d{2})?)?$/;

const MONTH_DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeap(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, m: number): number {
  return m === 2 && isLeap(y) ? 29 : MONTH_DAYS[m - 1];
}

/** Monday-based weekday helper: 0 = Sunday for the p-function below. */
function p(y: number): number {
  const v = y + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400);
  return ((v % 7) + 7) % 7;
}

function isoWeeksInYear(y: number): number {
  return p(y) === 4 || p(y - 1) === 3 ? 53 : 52;
}

/** Epoch ms of 00:00:00.000 UTC on the given calendar date (valid for all years). */
function utcMs(y: number, m: number, d: number): number {
  const dt = new Date(0);
  dt.setUTCFullYear(y, m - 1, d);
  return dt.getTime();
}

function parseOne(s: string): number {
  if (typeof s !== "string") {
    throw new RangeError(`Invalid ISO 8601 date: ${String(s)}`);
  }

  const m: (string | undefined)[] | null = PATTERN.exec(s);
  if (!m) {
    throw new RangeError(`Invalid ISO 8601 date: ${s}`);
  }

  const [
    , cy, cm, cd,
    wy, ww, wdStr,
    oy, od,
    hh, mi, ss, frac, off,
  ] = m;

  let base: number;

  if (cy !== undefined) {
    // Calendar date: YYYY-MM-DD
    const y = Number(cy);
    const mo = Number(cm);
    const d = Number(cd);
    if (mo < 1 || mo > 12 || d < 1 || d > daysInMonth(y, mo)) {
      throw new RangeError(`Invalid calendar date: ${s}`);
    }
    base = utcMs(y, mo, d);
  } else if (wy !== undefined) {
    // Week date: YYYY-Www-D
    const y = Number(wy);
    const w = Number(ww);
    const dow = Number(wdStr);
    if (w < 1 || w > isoWeeksInYear(y) || dow < 1 || dow > 7) {
      throw new RangeError(`Invalid week date: ${s}`);
    }
    // ISO week 1 is the week containing January 4th.
    const t4 = utcMs(y, 1, 4);
    const isoDow4 = ((new Date(t4).getUTCDay() + 6) % 7) + 1; // Mon=1..Sun=7
    const week1Monday = t4 - (isoDow4 - 1) * DAY_MS;
    base = week1Monday + ((w - 1) * 7 + (dow - 1)) * DAY_MS;
  } else {
    // Ordinal date: YYYY-DDD
    const y = Number(oy);
    const o = Number(od);
    const maxDay = isLeap(y) ? 366 : 365;
    if (o < 1 || o > maxDay) {
      throw new RangeError(`Invalid ordinal date: ${s}`);
    }
    base = utcMs(y, 1, 1) + (o - 1) * DAY_MS;
  }

  let t = base;

  if (hh !== undefined) {
    const h = Number(hh);
    const mn = mi === undefined ? 0 : Number(mi);
    const sec = ss === undefined ? 0 : Number(ss);
    const ms = frac === undefined ? 0 : parseInt((frac + "00").slice(0, 3), 10);
    const fracNonZero = frac !== undefined && /[1-9]/.test(frac);

    if (h === 24) {
      // ISO 8601 allows 24:00:00 meaning midnight at the end of the day.
      if (mn !== 0 || sec !== 0 || fracNonZero) {
        throw new RangeError(`Invalid time: ${s}`);
      }
    } else if (h > 23) {
      throw new RangeError(`Invalid time: ${s}`);
    }
    if (mn > 59 || sec > 59) {
      throw new RangeError(`Invalid time: ${s}`);
    }

    t += h * HOUR_MS + mn * MINUTE_MS + sec * 1000 + ms;

    if (off !== undefined && off !== "Z") {
      const sign = off[0] === "+" ? 1 : -1;
      const oh = Number(off.slice(1, 3));
      const om = Number(off.slice(4, 6));
      if (oh > 23 || om > 59) {
        throw new RangeError(`Invalid offset: ${s}`);
      }
      t -= sign * (oh * HOUR_MS + om * MINUTE_MS);
    }
  }

  if (!Number.isFinite(t)) {
    throw new RangeError(`Invalid ISO 8601 date: ${s}`);
  }
  return t;
}

export function solve(stamps: string[]): number[] {
  if (!Array.isArray(stamps)) {
    throw new RangeError("Input must be an array of strings");
  }
  return stamps.map(parseOne).sort((a, b) => a - b);
}

export function solve(text: string): string | null {
  // Maximal runs of digits, optionally joined by single dots.
  const runs = text.match(/\d+(?:\.\d+)*/g);
  if (!runs) return null;

  for (const run of runs) {
    // Only the first three dot-separated numbers matter; the rest are ignored.
    const parts = run.split(".").slice(0, 3);

    // Each used component must be at most 16 digits; otherwise this run is not version-like.
    if (parts.some((p) => p.length > 16)) continue;

    // Normalize by stripping leading zeros (keeping at least one digit).
    const nums = parts.map((p) => p.replace(/^0+(?=\d)/, ""));
    while (nums.length < 3) nums.push("0");

    return nums.join(".");
  }

  return null;
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

interface ParsedVersion {
  raw: string;
  major: string;
  minor: string;
  patch: string;
  pre: string[] | null;
}

function cmpNumericString(a: string, b: string): number {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

function cmpPreIdentifier(a: string, b: string): number {
  const aNum = /^\d+$/.test(a);
  const bNum = /^\d+$/.test(b);
  if (aNum && bNum) return cmpNumericString(a, b);
  if (aNum) return -1; // numeric identifiers have lower precedence
  if (bNum) return 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

function parse(v: string): ParsedVersion | null {
  const m = SEMVER_RE.exec(v);
  if (!m) return null;
  return {
    raw: v,
    major: m[1],
    minor: m[2],
    patch: m[3],
    pre: m[4] !== undefined ? m[4].split(".") : null,
  };
}

function compareVersions(a: ParsedVersion, b: ParsedVersion): number {
  let c = cmpNumericString(a.major, b.major);
  if (c !== 0) return c;
  c = cmpNumericString(a.minor, b.minor);
  if (c !== 0) return c;
  c = cmpNumericString(a.patch, b.patch);
  if (c !== 0) return c;

  // Prerelease: a version without prerelease has higher precedence.
  if (a.pre === null && b.pre === null) {
    // equal precedence; fall through to build-metadata tie-break
  } else if (a.pre === null) {
    return 1;
  } else if (b.pre === null) {
    return -1;
  } else {
    const len = Math.min(a.pre.length, b.pre.length);
    for (let i = 0; i < len; i++) {
      c = cmpPreIdentifier(a.pre[i], b.pre[i]);
      if (c !== 0) return c;
    }
    if (a.pre.length !== b.pre.length) {
      return a.pre.length < b.pre.length ? -1 : 1;
    }
  }

  // Equal precedence: order by full string lexically.
  return a.raw < b.raw ? -1 : a.raw > b.raw ? 1 : 0;
}

export function solve(versions: string[]): string[] {
  const parsed: ParsedVersion[] = [];
  for (const v of versions) {
    const p = parse(v);
    if (p !== null) parsed.push(p);
  }
  parsed.sort(compareVersions);
  return parsed.map((p) => p.raw);
}

export function solve(text: string): string {
  // Encode the string as UTF-8 manually (no TextEncoder, no Node/browser APIs).
  const bytes: number[] = [];
  for (let i = 0; i < text.length; i++) {
    let cp = text.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff) {
      // High surrogate: combine with a following low surrogate if present.
      const lo = i + 1 < text.length ? text.charCodeAt(i + 1) : 0;
      if (lo >= 0xdc00 && lo <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
        i++;
      } else {
        cp = 0xfffd; // unpaired surrogate
      }
    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
      cp = 0xfffd; // unpaired low surrogate
    }

    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  // Padding (FIPS 180-4, section 5.1.1).
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) {
    bytes.push(0);
  }
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  bytes.push(
    (hi >>> 24) & 0xff, (hi >>> 16) & 0xff, (hi >>> 8) & 0xff, hi & 0xff,
    (lo >>> 24) & 0xff, (lo >>> 16) & 0xff, (lo >>> 8) & 0xff, lo & 0xff
  );

  const rotl = (x: number, n: number): number => (x << n) | (x >>> (32 - n));

  // Initial hash values (section 5.3.1).
  let h0 = 0x67452301;
  let h1 = 0xefcdab89 | 0;
  let h2 = 0x98badcfe | 0;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0 | 0;

  const W: number[] = new Array(80);

  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const p = off + t * 4;
      W[t] =
        (bytes[p] << 24) |
        (bytes[p + 1] << 16) |
        (bytes[p + 2] << 8) |
        bytes[p + 3];
    }
    for (let t = 16; t < 80; t++) {
      W[t] = rotl(W[t - 3] ^ W[t - 8] ^ W[t - 14] ^ W[t - 16], 1);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let t = 0; t < 80; t++) {
      let f: number;
      let k: number;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (rotl(a, 5) + f + e + k + W[t]) | 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) | 0;
    h1 = (h1 + b) | 0;
    h2 = (h2 + c) | 0;
    h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0;
  }

  const hex = (x: number): string => (x >>> 0).toString(16).padStart(8, "0");
  return hex(h0) + hex(h1) + hex(h2) + hex(h3) + hex(h4);
}

type Parsed = {
  core: [string, string, string];
  pre: string[] | null;
};

const SEMVER =
  /^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$/;

function parse(v: string): Parsed {
  const m = SEMVER.exec(v);
  if (!m) throw new TypeError(`Invalid semver version: ${JSON.stringify(v)}`);
  return {
    core: [m[1], m[2], m[3]],
    pre: m[4] === undefined ? null : m[4].split("."),
  };
}

// Compare numeric identifiers (no leading zeros in valid semver) without precision loss.
function cmpNum(a: string, b: string): number {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

// Compare a single prerelease identifier per semver precedence rules.
function cmpPreId(x: string, y: string): number {
  const xNum = /^\d+$/.test(x);
  const yNum = /^\d+$/.test(y);
  if (xNum && yNum) return cmpNum(x, y);
  if (xNum) return -1; // numeric identifiers sort before alphanumeric ones
  if (yNum) return 1;
  return x < y ? -1 : x > y ? 1 : 0;
}

// Semver precedence (build metadata ignored).
function comparePrecedence(x: Parsed, y: Parsed): number {
  for (let i = 0; i < 3; i++) {
    const c = cmpNum(x.core[i], y.core[i]);
    if (c !== 0) return c;
  }
  if (x.pre === null && y.pre === null) return 0;
  if (x.pre === null) return 1; // release > prerelease
  if (y.pre === null) return -1;

  const n = Math.min(x.pre.length, y.pre.length);
  for (let i = 0; i < n; i++) {
    const c = cmpPreId(x.pre[i], y.pre[i]);
    if (c !== 0) return c;
  }
  return x.pre.length === y.pre.length
    ? 0
    : x.pre.length < y.pre.length
      ? -1
      : 1;
}

// Index of the highest differing core part (0=major, 1=minor, 2=patch), or -1 if cores are equal.
function highestDiff(lo: [string, string, string], hi: [string, string, string]): number {
  for (let i = 0; i < 3; i++) {
    if (cmpNum(lo[i], hi[i]) !== 0) return i;
  }
  return -1;
}

const PARTS = ["major", "minor", "patch"];

export function solve(a: string, b: string): string | null {
  const pa = parse(a);
  const pb = parse(b);

  const c = comparePrecedence(pa, pb);
  if (c === 0) return null;

  const [lo, hi] = c < 0 ? [pa, pb] : [pb, pa];
  const idx = highestDiff(lo.core, hi.core);
  const hiIsPre = hi.pre !== null;
  const loIsPre = lo.pre !== null;

  // Higher version is a prerelease: "pre" + highest differing part, or "prerelease" if cores match.
  if (hiIsPre) {
    return idx === -1 ? "prerelease" : "pre" + PARTS[idx];
  }

  // Higher version is a release and lower is a prerelease: special cases.
  if (loIsPre) {
    const [, loMinor, loPatch] = lo.core;
    const [, hiMinor, hiPatch] = hi.core;

    // Lower minor and patch are 0 and only the major changed (or cores equal): major.
    if (loMinor === "0" && loPatch === "0" && hiMinor === "0" && hiPatch === "0") {
      return "major";
    }

    // Cores equal, lower patch is 0 (minor nonzero): minor; otherwise patch.
    if (idx === -1) {
      return loPatch === "0" ? "minor" : "patch";
    }
  }

  // Default: highest differing core part.
  return PARTS[idx];
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$/;

// A prerelease id must be a single alphanumeric identifier that starts with a letter or hyphen.
const ID_RE = /^[A-Za-z-][0-9A-Za-z-]*$/;
const NUMERIC_RE = /^\d+$/;

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  const m = SEMVER_RE.exec(version);
  if (!m) return null;

  const zero = BigInt(0);
  const one = BigInt(1);

  let major = BigInt(m[1]);
  let minor = BigInt(m[2]);
  let patch = BigInt(m[3]);
  // Build metadata (after '+') is discarded, as semver's inc does.
  let pre: string[] = m[4] !== undefined ? m[4].split('.') : [];

  const tag = id === undefined || id === '' ? undefined : id;

  // All pre* kinds start with "pre"; reject an invalid id only when it would be used.
  if (kind.startsWith('pre') && tag !== undefined && !ID_RE.test(tag)) {
    return null;
  }

  const newPre = (): string[] => (tag !== undefined ? [tag, '0'] : ['0']);

  switch (kind) {
    case 'major':
      // From a prerelease whose minor and patch are zero, major just releases it.
      if (!(pre.length > 0 && minor === zero && patch === zero)) {
        major += one;
      }
      minor = zero;
      patch = zero;
      pre = [];
      break;

    case 'minor':
      // From a prerelease whose patch is zero, minor just releases it.
      if (!(pre.length > 0 && patch === zero)) {
        minor += one;
      }
      patch = zero;
      pre = [];
      break;

    case 'patch':
      // From a prerelease, patch just releases it.
      if (pre.length === 0) {
        patch += one;
      }
      pre = [];
      break;

    case 'premajor':
      major += one;
      minor = zero;
      patch = zero;
      pre = newPre();
      break;

    case 'preminor':
      minor += one;
      patch = zero;
      pre = newPre();
      break;

    case 'prepatch':
      patch += one;
      pre = newPre();
      break;

    case 'prerelease': {
      if (pre.length === 0) {
        // Release: bump patch and start a new prerelease.
        patch += one;
        pre = newPre();
        break;
      }

      // A prerelease "has the same id" if its leading identifier matches the
      // requested id. With no id, that means the prerelease has no alphabetic prefix.
      const sameId = tag === undefined ? NUMERIC_RE.test(pre[0]) : pre[0] === tag;

      let bumped = false;
      if (sameId) {
        for (let i = pre.length - 1; i >= 0; i--) {
          if (NUMERIC_RE.test(pre[i])) {
            pre[i] = (BigInt(pre[i]) + one).toString();
            bumped = true;
            break;
          }
        }
      }
      if (!bumped) {
        // Different id, or no numeric part to increment: switch to <id>.0 (or 0).
        pre = newPre();
      }
      break;
    }

    default:
      return null;
  }

  const core = `${major}.${minor}.${patch}`;
  return pre.length > 0 ? `${core}-${pre.join('.')}` : core;
}

export function solve(name: string, namespace: string): string {
  const uuidPattern = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
  if (typeof namespace !== "string" || !uuidPattern.test(namespace)) {
    throw new TypeError("namespace is not a valid UUID");
  }

  // Namespace UUID -> 16 bytes
  const nsHex = namespace.replace(/-/g, "");
  const nsBytes: number[] = [];
  for (let i = 0; i < 32; i += 2) {
    nsBytes.push(parseInt(nsHex.substr(i, 2), 16));
  }

  // name -> UTF-8 bytes (lone surrogates are replaced by U+FFFD)
  const nameBytes = utf8Encode(String(name));

  const digest = md5(nsBytes.concat(nameBytes));

  // Set version (3) and RFC 4122 variant
  digest[6] = (digest[6] & 0x0f) | 0x30;
  digest[8] = (digest[8] & 0x3f) | 0x80;

  let hex = "";
  for (let i = 0; i < 16; i++) {
    const b = digest[i];
    hex += (b < 16 ? "0" : "") + b.toString(16);
  }

  return (
    hex.slice(0, 8) + "-" +
    hex.slice(8, 12) + "-" +
    hex.slice(12, 16) + "-" +
    hex.slice(16, 20) + "-" +
    hex.slice(20, 32)
  );
}

function utf8Encode(s: string): number[] {
  const out: number[] = [];
  for (const ch of s) {
    let cp = ch.codePointAt(0) as number;
    if (cp >= 0xd800 && cp <= 0xdfff) {
      cp = 0xfffd; // lone surrogate
    }
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }
  return out;
}

function md5(msg: number[]): number[] {
  const S: number[] = [
    7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
    5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
    4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
    6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
  ];

  const K: number[] = [];
  for (let i = 0; i < 64; i++) {
    K[i] = Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296);
  }

  const len = msg.length;
  const blocks = ((len + 8) >>> 6) + 1;
  const total = blocks * 64;
  const buf: number[] = [];
  for (let i = 0; i < total; i++) buf.push(0);
  for (let i = 0; i < len; i++) buf[i] = msg[i];
  buf[len] = 0x80;

  const bitLo = (len * 8) >>> 0;
  const bitHi = Math.floor(len / 0x20000000) >>> 0;
  for (let k = 0; k < 4; k++) {
    buf[total - 8 + k] = (bitLo >>> (8 * k)) & 0xff;
    buf[total - 4 + k] = (bitHi >>> (8 * k)) & 0xff;
  }

  let a0 = 0x67452301;
  let b0 = 0xefcdab89 | 0;
  let c0 = 0x98badcfe | 0;
  let d0 = 0x10325476;

  const M: number[] = new Array<number>(16);

  for (let off = 0; off < total; off += 64) {
    for (let j = 0; j < 16; j++) {
      const p = off + j * 4;
      M[j] = (buf[p] | (buf[p + 1] << 8) | (buf[p + 2] << 16) | (buf[p + 3] << 24)) | 0;
    }

    let A = a0;
    let B = b0;
    let C = c0;
    let D = d0;

    for (let i = 0; i < 64; i++) {
      let F: number;
      let g: number;
      if (i < 16) {
        F = (B & C) | (~B & D);
        g = i;
      } else if (i < 32) {
        F = (D & B) | (~D & C);
        g = (5 * i + 1) % 16;
      } else if (i < 48) {
        F = B ^ C ^ D;
        g = (3 * i + 5) % 16;
      } else {
        F = C ^ (B | ~D);
        g = (7 * i) % 16;
      }
      F = (F + A + K[i] + M[g]) | 0;
      A = D;
      D = C;
      C = B;
      const s = S[i];
      B = (B + ((F << s) | (F >>> (32 - s)))) | 0;
    }

    a0 = (a0 + A) | 0;
    b0 = (b0 + B) | 0;
    c0 = (c0 + C) | 0;
    d0 = (d0 + D) | 0;
  }

  const out: number[] = [];
  const words = [a0, b0, c0, d0];
  for (let w = 0; w < 4; w++) {
    for (let k = 0; k < 4; k++) {
      out.push((words[w] >>> (8 * k)) & 0xff);
    }
  }
  return out;
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  const s = isbn.replace(/[ -]/g, "");

  const isValidTen = (): boolean => {
    if (!/^[0-9]{9}[0-9X]$/.test(s)) return false;
    let sum = 0;
    for (let i = 0; i < 10; i++) {
      const ch = s[i];
      const d = ch === "X" ? 10 : ch.charCodeAt(0) - 48;
      sum += (10 - i) * d;
    }
    return sum % 11 === 0;
  };

  const isValidThirteen = (): boolean => {
    if (!/^[0-9]{13}$/.test(s)) return false;
    let sum = 0;
    for (let i = 0; i < 13; i++) {
      const d = s.charCodeAt(i) - 48;
      sum += i % 2 === 0 ? d : 3 * d;
    }
    return sum % 10 === 0;
  };

  if (version === 10) return isValidTen();
  if (version === 13) return isValidThirteen();
  return isValidTen() || isValidThirteen();
}

type Rule = {
  matches: (digits: string) => boolean;
  lengths: readonly number[];
};

const range = (lo: number, hi: number): number[] => {
  const out: number[] = [];
  for (let i = lo; i <= hi; i++) out.push(i);
  return out;
};

// True if the first `width` digits, read as a number, fall within [lo, hi].
const prefixInRange = (digits: string, width: number, lo: number, hi: number): boolean => {
  if (digits.length < width) return false;
  const prefix = Number(digits.slice(0, width));
  return prefix >= lo && prefix <= hi;
};

const RULES: readonly Rule[] = [
  // Visa
  { matches: d => d.startsWith("4"), lengths: [13, 16, 19] },
  // Mastercard
  {
    matches: d =>
      prefixInRange(d, 2, 51, 55) || prefixInRange(d, 4, 2221, 2720),
    lengths: [16],
  },
  // American Express
  { matches: d => d.startsWith("34") || d.startsWith("37"), lengths: [15] },
  // Discover
  {
    matches: d =>
      d.startsWith("6011") ||
      prefixInRange(d, 6, 622126, 622925) ||
      prefixInRange(d, 3, 644, 649) ||
      d.startsWith("65"),
    lengths: [16, 19],
  },
  // Diners Club
  {
    matches: d =>
      prefixInRange(d, 3, 300, 305) || d.startsWith("36") || d.startsWith("38"),
    lengths: range(14, 19),
  },
  // JCB
  { matches: d => prefixInRange(d, 4, 3528, 3589), lengths: range(16, 19) },
  // UnionPay
  { matches: d => d.startsWith("62"), lengths: range(16, 19) },
];

const luhn = (digits: string): boolean => {
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = digits.charCodeAt(i) - 48;
    if (double) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    double = !double;
  }
  return sum % 10 === 0;
};

export function solve(card: string): boolean {
  const digits = card.replace(/[ -]/g, "");
  if (!/^\d+$/.test(digits)) return false;

  const issuerOk = RULES.some(
    rule => rule.lengths.includes(digits.length) && rule.matches(digits)
  );

  return issuerOk && luhn(digits);
}

export function solve(isin: string): boolean {
  if (typeof isin !== "string") return false;

  // 2 uppercase letters, 9 uppercase alphanumerics, 1 digit check digit
  if (!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) return false;

  // Convert letters to numbers (A=10 ... Z=35), keeping digits as-is
  let digits = "";
  for (let i = 0; i < isin.length; i++) {
    const code = isin.charCodeAt(i);
    if (code >= 65 && code <= 90) {
      digits += String(code - 55); // 'A' (65) -> 10, 'Z' (90) -> 35
    } else {
      digits += isin[i];
    }
  }

  // Luhn algorithm over the full digit string, including the check digit
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48;
    if (double) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    double = !double;
  }

  return sum % 10 === 0;
}

