interface CompiledRule {
  length: number;
  pattern: RegExp;
}

const CHAR_CLASS: Readonly<Record<string, string>> = {
  n: "[0-9]",
  a: "[A-Z]",
  c: "[A-Z0-9]",
};

function compileBban(bban: string): RegExp {
  let body = "";
  bban.replace(/(\d+)([nac])/g, (_match: string, count: string, type: string) => {
    body += CHAR_CLASS[type] + "{" + count + "}";
    return _match;
  });
  return new RegExp("^[A-Z]{2}[0-9]{2}" + body + "$");
}

const RULES: Map<string, CompiledRule> = new Map();
for (const [country, length, bban] of IBAN_REGISTRY) {
  RULES.set(country, { length, pattern: compileBban(bban) });
}

// Mod-97 over the rearranged IBAN, processed digit-by-digit to avoid overflow.
function mod97(value: string): number {
  let remainder = 0;
  for (let i = 0; i < value.length; i++) {
    const code = value.charCodeAt(i);
    if (code >= 48 && code <= 57) {
      // digit
      remainder = (remainder * 10 + (code - 48)) % 97;
    } else {
      // letter A=10 ... Z=35, two digits
      const v = code - 55;
      remainder = (remainder * 100 + v) % 97;
    }
  }
  return remainder;
}

export function solve(iban: string): boolean {
  if (typeof iban !== "string") {
    return false;
  }

  // Ignore spaces and hyphens; letters may be any case.
  const normalized = iban.replace(/[ -]/g, "").toUpperCase();

  if (normalized.length < 4) {
    return false;
  }

  const country = normalized.slice(0, 2);
  const rule = RULES.get(country);
  if (rule === undefined) {
    return false;
  }

  if (normalized.length !== rule.length) {
    return false;
  }

  if (!rule.pattern.test(normalized)) {
    return false;
  }

  const rearranged = normalized.slice(4) + normalized.slice(0, 4);
  return mod97(rearranged) === 1;
}

export function solve(mac: string): boolean {
  const patterns: RegExp[] = [
    /^[0-9a-f]{2}(?::[0-9a-f]{2}){5}$/i,  // EUI-48, colon-separated
    /^[0-9a-f]{2}(?::[0-9a-f]{2}){7}$/i,  // EUI-64, colon-separated
    /^[0-9a-f]{2}(?:-[0-9a-f]{2}){5}$/i,  // EUI-48, hyphen-separated
    /^[0-9a-f]{2}(?:-[0-9a-f]{2}){7}$/i,  // EUI-64, hyphen-separated
    /^[0-9a-f]{4}(?:\.[0-9a-f]{4}){2,3}$/i // dotted form: 3 or 4 groups of 4
  ];
  return patterns.some((p) => p.test(mac));
}

export function solve(code: string): boolean {
  // Only ASCII digits are allowed
  if (!/^[0-9]+$/.test(code)) return false;

  const len = code.length;
  if (len !== 8 && len !== 13 && len !== 14) return false;

  // Weights alternate 3,1,3,1... starting from the rightmost data digit
  // (the digit just left of the check digit).
  let sum = 0;
  for (let i = 0; i < len - 1; i++) {
    const digit = code.charCodeAt(i) - 48; // '0' is char code 48
    const positionFromRight = len - 1 - i; // 1 for the rightmost data digit
    const weight = positionFromRight % 2 === 1 ? 3 : 1;
    sum += digit * weight;
  }

  const checkDigit = (10 - (sum % 10)) % 10;
  return checkDigit === code.charCodeAt(len - 1) - 48;
}

const HEX_GROUP = /^[0-9A-Fa-f]{1,4}$/;
const IPV4_OCTET = /^(0|[1-9][0-9]{0,2})$/;
const ZONE_ID = /^[0-9A-Za-z]+$/;

function isIPv4(s: string): boolean {
  const parts = s.split('.');
  if (parts.length !== 4) return false;
  return parts.every((p) => IPV4_OCTET.test(p) && Number(p) <= 255);
}

// Returns the number of 16-bit groups the tokens represent, or -1 if invalid.
// An embedded IPv4 address counts as two groups and is only allowed as the
// final token when allowIPv4Last is true.
function countGroups(tokens: string[], allowIPv4Last: boolean): number {
  let n = 0;
  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];
    if (HEX_GROUP.test(t)) {
      n += 1;
    } else if (allowIPv4Last && i === tokens.length - 1 && isIPv4(t)) {
      n += 2;
    } else {
      return -1;
    }
  }
  return n;
}

function isIPv6Address(addr: string): boolean {
  const dbl = addr.indexOf('::');
  // At most one "::" (this also rejects ":::").
  if (dbl !== -1 && addr.indexOf('::', dbl + 1) !== -1) return false;

  const compressed = dbl !== -1;
  const headStr = compressed ? addr.slice(0, dbl) : addr;
  const tailStr = compressed ? addr.slice(dbl + 2) : '';
  const head = headStr === '' ? [] : headStr.split(':');
  const tail = tailStr === '' ? [] : tailStr.split(':');

  // An IPv4 tail is only legal at the very end of the address.
  const h = countGroups(head, !compressed);
  const t = compressed ? countGroups(tail, true) : 0;
  if (h < 0 || t < 0) return false;

  const total = h + t;
  // "::" must stand for at least one zero group.
  return compressed ? total <= 7 : total === 8;
}

// Link-local unicast: fe80::/10
function isLinkLocal(addr: string): boolean {
  const first = addr.split(':')[0];
  if (!HEX_GROUP.test(first)) return false;
  return (parseInt(first, 16) & 0xffc0) === 0xfe80;
}

function isIPv6(text: string): boolean {
  let addr = text;
  let hasZone = false;

  const pct = text.indexOf('%');
  if (pct !== -1) {
    addr = text.slice(0, pct);
    const zone = text.slice(pct + 1);
    if (!ZONE_ID.test(zone)) return false;
    hasZone = true;
  }

  if (!isIPv6Address(addr)) return false;
  if (hasZone && !isLinkLocal(addr)) return false;
  return true;
}

export function solve(text: string, version?: 4 | 6): boolean {
  const wantV4 = version === undefined || version === 4;
  const wantV6 = version === undefined || version === 6;

  if (wantV4 && isIPv4(text)) return true;
  if (wantV6 && isIPv6(text)) return true;
  return false;
}

export function solve(text: string): boolean {
  const COORD = "[+-]?\\d+(?:\\.\\d+)?";
  const PAIR = new RegExp(`^(${COORD}),[ ]*(${COORD})$`);
  const UNSIGNED = /^[+-]?(\d+(?:\.\d+)?)$/;

  // Checks that |value| <= limit, where limit is a whole-number string.
  const withinLimit = (s: string, limit: string): boolean => {
    const m = UNSIGNED.exec(s);
    if (!m) return false;
    const [intPart, frac = ""] = m[1].split(".");
    const ip = intPart.replace(/^0+(?=\d)/, "");
    if (ip.length !== limit.length) return ip.length < limit.length;
    if (ip !== limit) return ip < limit;
    return /^0*$/.test(frac);
  };

  let inner = text;
  if (text.startsWith("(") && text.endsWith(")")) {
    inner = text.slice(1, -1);
  }

  const m = PAIR.exec(inner);
  if (!m) return false;

  return withinLimit(m[1], "90") && withinLimit(m[2], "180");
}

export function solve(issn: string): boolean {
  // Accepted forms: "NNNN-NNNC" or "NNNNNNNC", where C is a digit or X/x.
  if (!/^(?:\d{4}-\d{3}|\d{7})[\dXx]$/.test(issn)) {
    return false;
  }

  const s = issn.replace("-", "");

  // Zero-based index i over the first seven digits, weight (8 - i):
  // 8, 7, 6, 5, 4, 3, 2. Adding the check value (X = 10) must give
  // a total divisible by 11.
  let sum = 0;
  for (let i = 0; i < 7; i++) {
    sum += (8 - i) * Number(s[i]);
  }

  const last = s[7];
  const check = last === "X" || last === "x" ? 10 : Number(last);

  return (sum + check) % 11 === 0;
}

export function solve(a: string, b: string): number {
  const m = a.length;
  const n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;

  let prev = new Int32Array(n + 1);
  let curr = new Int32Array(n + 1);
  for (let j = 0; j <= n; j++) prev[j] = j;

  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    const ca = a.charCodeAt(i - 1);
    for (let j = 1; j <= n; j++) {
      const cost = ca === b.charCodeAt(j - 1) ? 0 : 1;
      let v = prev[j - 1] + cost;
      const del = prev[j] + 1;
      if (del < v) v = del;
      const ins = curr[j - 1] + 1;
      if (ins < v) v = ins;
      curr[j] = v;
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[n];
}

type Ver = { major: number; minor: number; patch: number; pre: string[] };
type Bound = { ver: Ver; inclusive: boolean };
type PartialVer = {
  major: number | null;
  minor: number | null;
  patch: number | null;
  pre: string[];
};

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*)?$/;

const PARTIAL_RE =
  /^(\d+|[xX*])(?:\.(\d+|[xX*]))?(?:\.(\d+|[xX*]))?(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?$/;

function parseVersion(s: string): Ver | null {
  const m = SEMVER_RE.exec(s);
  if (!m) return null;
  return {
    major: Number(m[1]),
    minor: Number(m[2]),
    patch: Number(m[3]),
    pre: m[4] ? m[4].split('.') : [],
  };
}

function num(p: string | undefined): number | null {
  if (p === undefined || !/^\d+$/.test(p)) return null;
  return Number(p);
}

function parsePartial(s: string): PartialVer | null {
  const m = PARTIAL_RE.exec(s);
  if (!m) return null;
  let major = num(m[1]);
  let minor = num(m[2]);
  let patch = num(m[3]);
  if (major === null) {
    minor = null;
    patch = null;
  }
  if (minor === null) patch = null;
  const pre = patch !== null && m[4] ? m[4].split('.') : [];
  return { major, minor, patch, pre };
}

function mk(major: number, minor: number, patch: number, pre: string[] = []): Ver {
  return { major, minor, patch, pre };
}

function excl(major: number, minor: number, patch: number): Bound {
  return { ver: mk(major, minor, patch), inclusive: false };
}

function incl(major: number, minor: number, patch: number, pre: string[]): Bound {
  return { ver: mk(major, minor, patch, pre), inclusive: true };
}

function cmpId(a: string, b: string): number {
  const an = /^\d+$/.test(a);
  const bn = /^\d+$/.test(b);
  if (an && bn) {
    if (a.length !== b.length) return a.length < b.length ? -1 : 1;
    return a < b ? -1 : a > b ? 1 : 0;
  }
  if (an) return -1;
  if (bn) return 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

function cmp(a: Ver, b: Ver): number {
  const pa = [a.major, a.minor, a.patch];
  const pb = [b.major, b.minor, b.patch];
  for (let i = 0; i < 3; i++) {
    if (pa[i] !== pb[i]) return pa[i] < pb[i] ? -1 : 1;
  }
  if (a.pre.length === 0 && b.pre.length === 0) return 0;
  if (a.pre.length === 0) return 1;
  if (b.pre.length === 0) return -1;
  const n = Math.min(a.pre.length, b.pre.length);
  for (let i = 0; i < n; i++) {
    const c = cmpId(a.pre[i], b.pre[i]);
    if (c !== 0) return c;
  }
  return a.pre.length < b.pre.length ? -1 : a.pre.length > b.pre.length ? 1 : 0;
}

// Returns the upper bound implied by a single comparator, or null if none.
function upperBound(op: string, p: PartialVer): Bound | null {
  const { major, minor, patch } = p;
  switch (op) {
    case '>':
    case '>=':
      return null;
    case '<': {
      if (major === null) return { ver: mk(0, 0, 0, ['0']), inclusive: false };
      if (minor === null) return excl(major, 0, 0);
      if (patch === null) return excl(major, minor, 0);
      return { ver: mk(major, minor, patch, p.pre), inclusive: false };
    }
    case '<=': {
      if (major === null) return null;
      if (minor === null) return excl(major + 1, 0, 0);
      if (patch === null) return excl(major, minor + 1, 0);
      return incl(major, minor, patch, p.pre);
    }
    case '':
    case '=': {
      if (major === null) return null;
      if (minor === null) return excl(major + 1, 0, 0);
      if (patch === null) return excl(major, minor + 1, 0);
      return incl(major, minor, patch, p.pre);
    }
    case '~':
    case '~>': {
      if (major === null) return null;
      if (minor === null) return excl(major + 1, 0, 0);
      return excl(major, minor + 1, 0);
    }
    case '^': {
      if (major === null) return null;
      if (minor === null) return excl(major + 1, 0, 0);
      if (patch === null) return major > 0 ? excl(major + 1, 0, 0) : excl(0, minor + 1, 0);
      if (major > 0) return excl(major + 1, 0, 0);
      if (minor > 0) return excl(0, minor + 1, 0);
      return excl(0, 0, patch + 1);
