  const out: Comparator[] = [];

  if (lo.major !== undefined) {
    const M = lo.major;
    if (lo.minor === undefined) {
      out.push(cmp('>=', M, 0, 0));
    } else if (lo.patch === undefined) {
      out.push(cmp('>=', M, lo.minor, 0));
    } else {
      out.push(cmp('>=', M, lo.minor, lo.patch, lo.pre));
    }
  }

  if (hi.major !== undefined) {
    const M = hi.major;
    if (hi.minor === undefined) {
      out.push(cmp('<', M + 1, 0, 0, ZERO_PRE));
    } else if (hi.patch === undefined) {
      out.push(cmp('<', M, hi.minor + 1, 0, ZERO_PRE));
    } else {
      out.push(cmp('<=', M, hi.minor, hi.patch, hi.pre));
    }
  }

  return out;
}

function parseSet(text: string): Comparator[] | null {
  const trimmed = text.trim();
  const raw = trimmed === '' ? [] : trimmed.split(/\s+/);

  // Join operators separated from their version by whitespace, e.g. ">= 1.2.3".
  const tokens: string[] = [];
  for (let i = 0; i < raw.length; i++) {
    if (OP_ONLY_RE.test(raw[i]) && i + 1 < raw.length) {
      tokens.push(raw[i] + raw[i + 1]);
      i++;
    } else {
      tokens.push(raw[i]);
    }
  }

  const out: Comparator[] = [];
  let i = 0;
  while (i < tokens.length) {
    let cs: Comparator[] | null;
    if (i + 2 < tokens.length && tokens[i + 1] === '-') {
      cs = hyphenComparators(tokens[i], tokens[i + 2]);
      i += 3;
    } else {
      cs = comparatorsFor(tokens[i]);
      i += 1;
    }
    if (cs === null) return null;
    for (const c of cs) out.push(c);
  }
  return out;
}

function parseRange(range: string): Comparator[][] | null {
  const sets: Comparator[][] = [];
  for (const part of range.split('||')) {
    const set = parseSet(part);
    if (set === null) return null;
    sets.push(set);
  }
  return sets;
}

export function solve(installed: string[], range: string): string | null {
  const sets = parseRange(range);
  if (sets === null) return null;

  let best: string | null = null;
  let bestVersion: Version | null = null;

  for (const raw of installed) {
    const v = parseVersion(raw);
    if (v === null) continue;
    if (bestVersion !== null && compareVersions(v, bestVersion) <= 0) continue;
    if (!sets.some((set) => setMatches(set, v))) continue;
    best = raw;
    bestVersion = v;
  }

  return best;
}

export function solve(emails: string[]): string[] {
  const gmailDomains = new Set<string>(["gmail.com", "googlemail.com"]);
  const plusOnlyDomains = new Set<string>(["outlook.com", "hotmail.com", "live.com"]);

  // Everything from the first "+" onward is a suffix.
  const stripPlusSuffix = (local: string): string => {
    const plus = local.indexOf("+");
    return plus === -1 ? local : local.slice(0, plus);
  };

  const canonicalize = (email: string): string => {
    const lower = email.toLowerCase();

    // Split at the last "@" so a quoted local part may contain "@".
    const at = lower.lastIndexOf("@");
    if (at === -1) {
      return lower;
    }

    const local = lower.slice(0, at);
    const domain = lower.slice(at + 1);

    if (gmailDomains.has(domain)) {
      return `${stripPlusSuffix(local).replace(/\./g, "")}@gmail.com`;
    }
    if (plusOnlyDomains.has(domain)) {
      return `${stripPlusSuffix(local)}@${domain}`;
    }
    return lower;
  };

  // A Set preserves insertion order, so the first occurrence of each form is kept.
  const seen = new Set<string>();
  const result: string[] = [];
  for (const email of emails) {
    const canonical = canonicalize(email);
    if (!seen.has(canonical)) {
      seen.add(canonical);
      result.push(canonical);
    }
  }
  return result;
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error(
      `Invalid base64 input: length ${text.length} is not a multiple of 4`
    );
  }

  const ALPHABET =
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

  const decodeChar = (ch: string): number => {
    const value = ALPHABET.indexOf(ch);
    if (value < 0) {
      throw new Error(`Invalid base64 character: ${JSON.stringify(ch)}`);
    }
    return value;
  };

  const bytes: number[] = [];

  for (let i = 0; i < text.length; i += 4) {
    const isLastGroup = i + 4 === text.length;
    const c2 = text.charAt(i + 2);
    const c3 = text.charAt(i + 3);
    const pad2 = c2 === "=";
    const pad3 = c3 === "=";

    if ((pad2 || pad3) && !isLastGroup) {
      throw new Error("Invalid base64 input: '=' padding before end of input");
    }
    if (pad2 && !pad3) {
      throw new Error("Invalid base64 input: malformed '=' padding");
    }

