    const n1 = decodeChar(text.charAt(i + 1));
    const n2 = pad2 ? 0 : decodeChar(c2);
    const n3 = pad3 ? 0 : decodeChar(c3);

    const triple = (n0 << 18) | (n1 << 12) | (n2 << 6) | n3;

    bytes.push((triple >> 16) & 0xff);
    if (!pad2) {
      bytes.push((triple >> 8) & 0xff);
    }
    if (!pad3) {
      bytes.push(triple & 0xff);
    }
  }

  return bytes;
}

export function solve(epochMs: number): string {
  // Math.floor (not the Date constructor's truncation toward zero) so that
  // negative fractional milliseconds land on the correct, earlier second.
  const date = new Date(Math.floor(epochMs));

  // Throws a RangeError for NaN, ±Infinity, or out-of-range values.
  // Yields "YYYY-MM-DDTHH:mm:ss.sssZ" (or the expanded "±YYYYYY-..." form).
  const iso = date.toISOString();

  // Drop the ".sss" fraction (always exactly three digits) and keep "Z".
  return iso.replace(/\.\d{3}Z$/, "Z");
}

