    if (last !== undefined && items.length > 0) {
      items[0] = last;
      let i = 0;
      let child = 1;
      while (child < items.length) {
        const right = child + 1;
        if (right < items.length && items[right] < items[child]) child = right;
        if (items[i] <= items[child]) break;
        swap(items, i, child);
        i = child;
        child = 2 * i + 1;
      }
    }
    return top;
  }
}

function swap(items: number[], i: number, j: number): void {
  const tmp = items[i];
  items[i] = items[j];
  items[j] = tmp;
}

/**
 * Orders `nodes` so that for every edge [a, b], `a` comes before `b`.
 *
 * At each step the earliest node (by position in `nodes`) whose prerequisites
 * are all placed is emitted next, so an input that already satisfies every
 * edge is returned unchanged.
 *
 * @throws {Error} if `nodes` contains duplicate names, if an edge mentions a
 * node that is not in `nodes`, or if the edges contain a cycle (a self-loop
 * such as [a, a] is a cycle).
 */
export function solve(nodes: string[], edges: [string, string][]): string[] {
  const n = nodes.length;

  // Node name -> index in `nodes`.
  const index = new Map<string, number>();
  for (let i = 0; i < n; i++) {
    const name = nodes[i];
    if (index.has(name)) {
      throw new Error(`Duplicate node "${name}" in nodes`);
    }
    index.set(name, i);
  }

  const successors: number[][] = nodes.map((): number[] => []);
  const inDegree: number[] = new Array<number>(n).fill(0);

  for (const [from, to] of edges) {
    const a = index.get(from);
    const b = index.get(to);
    if (a === undefined || b === undefined) {
      const missing = a === undefined ? from : to;
      throw new Error(`Edge [${from}, ${to}] mentions node "${missing}", which is not in nodes`);
    }
    successors[a].push(b);
    inDegree[b] += 1;
  }

  // Kahn's algorithm, always taking the ready node with the smallest index.
  const ready = new MinHeap();
  for (let i = 0; i < n; i++) {
    if (inDegree[i] === 0) ready.push(i);
  }

  const order: string[] = [];
  while (ready.size > 0) {
    const current = ready.pop();
    order.push(nodes[current]);
    for (const next of successors[current]) {
      inDegree[next] -= 1;
      if (inDegree[next] === 0) ready.push(next);
    }
  }

  // Nodes on a cycle, or downstream of one, never reach in-degree zero.
  if (order.length !== n) {
    const stuck = nodes.filter((_, i) => inDegree[i] > 0);
    throw new Error(`Edges contain a cycle; nodes that cannot be ordered: ${stuck.join(", ")}`);
  }
  return order;
}

export function solve(text: string): string {
  // 1. UTF-8 encode by hand (TextEncoder is not part of ECMAScript).
  //    Lone surrogates become U+FFFD, matching TextEncoder's behaviour.
  const msg: number[] = [];
  for (let i = 0; i < text.length; i++) {
    let cp = text.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff) {
      const next = i + 1 < text.length ? text.charCodeAt(i + 1) : 0;
      if (next >= 0xdc00 && next <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
        i++;
      } else {
        cp = 0xfffd;
      }
    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
      cp = 0xfffd;
    }

    if (cp < 0x80) {
      msg.push(cp);
    } else if (cp < 0x800) {
      msg.push(0xc0 | (cp >>> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      msg.push(0xe0 | (cp >>> 12), 0x80 | ((cp >>> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      msg.push(
        0xf0 | (cp >>> 18),
        0x80 | ((cp >>> 12) & 0x3f),
        0x80 | ((cp >>> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }

  // 2. Padding (FIPS 180-4 §5.1.1): 0x80, zeros to 56 (mod 64), 64-bit big-endian bit length.
  const byteLen = msg.length;
  msg.push(0x80);
  while (msg.length % 64 !== 56) msg.push(0);
  const bitLenHi = Math.floor(byteLen / 0x20000000) >>> 0; // bits 32..63
  const bitLenLo = (byteLen * 8) >>> 0;                    // bits 0..31
  msg.push(
    (bitLenHi >>> 24) & 0xff, (bitLenHi >>> 16) & 0xff, (bitLenHi >>> 8) & 0xff, bitLenHi & 0xff,
    (bitLenLo >>> 24) & 0xff, (bitLenLo >>> 16) & 0xff, (bitLenLo >>> 8) & 0xff, bitLenLo & 0xff,
  );

  // 3. Compression (FIPS 180-4 §6.1.2)
  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  const rotl = (x: number, n: number): number => ((x << n) | (x >>> (32 - n))) >>> 0;
  const w = new Uint32Array(80);

  for (let off = 0; off < msg.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const p = off + 4 * t;
      w[t] = (msg[p] << 24) | (msg[p + 1] << 16) | (msg[p + 2] << 8) | msg[p + 3];
    }
    for (let t = 16; t < 80; t++) {
      w[t] = rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let t = 0; t < 80; t++) {
      let f: number;
      let k: number;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (rotl(a, 5) + f + e + k + w[t]) >>> 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }

  // 4. Hex output: 8 lowercase digits per word, big-endian.
  const hex = (x: number): string => ("00000000" + (x >>> 0).toString(16)).slice(-8);
  return hex(h0) + hex(h1) + hex(h2) + hex(h3) + hex(h4);
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  if (typeof isbn !== 'string') return false;

  // Spaces and hyphens are ignored.
  const s = isbn.replace(/[ -]/g, '');

  const checkTen = version === undefined || version === 10;
  const checkThirteen = version === undefined || version === 13;

  return (checkTen && isValidIsbn10(s)) || (checkThirteen && isValidIsbn13(s));
}

// ISBN-10: nine digits followed by a digit or an upper-case 'X' (= 10),
// where sum of (10 - i) * d_i for i = 0..9 must be 0 mod 11.
function isValidIsbn10(s: string): boolean {
  if (!/^[0-9]{9}[0-9X]$/.test(s)) return false;

  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const ch = s.charAt(i);
    const digit = ch === 'X' ? 10 : ch.charCodeAt(0) - 48; // '0' is char code 48
    sum += (10 - i) * digit;
  }
  return sum % 11 === 0;
}

// ISBN-13 (EAN-13): thirteen digits, weights 1,3,1,3,... where the sum must be 0 mod 10.
function isValidIsbn13(s: string): boolean {
  if (!/^[0-9]{13}$/.test(s)) return false;

  let sum = 0;
  for (let i = 0; i < 13; i++) {
    const digit = s.charCodeAt(i) - 48;
    sum += i % 2 === 0 ? digit : digit * 3;
  }
  return sum % 10 === 0;
}

export function solve(isin: string): boolean {
  // Format: 2 uppercase letters, 9 uppercase alphanumerics, 1 decimal check digit.
  if (typeof isin !== "string" || !/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) {
    return false;
  }

  // Convert letters to numbers (A=10 through Z=35); digits stay as they are.
  const digits = isin.replace(/[A-Z]/g, (ch) => String(ch.charCodeAt(0) - 55));

  // Luhn checksum over the digit string, with the check digit included.
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48; // '0' is code 48
    if (double) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    double = !double;
  }

  return sum % 10 === 0;
}

export function solve(mac: string): boolean {
  // Each pattern fixes one separator and one length, so mixed or missing
  // separators can never match.
  const patterns: RegExp[] = [
    /^[0-9A-Fa-f]{2}(?::[0-9A-Fa-f]{2}){5}$/,  // colon, 6 octets (EUI-48)
    /^[0-9A-Fa-f]{2}(?::[0-9A-Fa-f]{2}){7}$/,  // colon, 8 octets (EUI-64)
    /^[0-9A-Fa-f]{2}(?:-[0-9A-Fa-f]{2}){5}$/,  // hyphen, 6 octets (EUI-48)
    /^[0-9A-Fa-f]{2}(?:-[0-9A-Fa-f]{2}){7}$/,  // hyphen, 8 octets (EUI-64)
    /^[0-9A-Fa-f]{4}(?:\.[0-9A-Fa-f]{4}){2}$/, // dotted, 3 groups (EUI-48)
    /^[0-9A-Fa-f]{4}(?:\.[0-9A-Fa-f]{4}){3}$/, // dotted, 4 groups (EUI-64)
  ];

  return patterns.some((re) => re.test(mac));
}

export function solve(code: string): boolean {
  if (typeof code !== 'string') return false;
  const len = code.length;
  if (len !== 8 && len !== 13 && len !== 14) return false;
  if (!/^[0-9]+$/.test(code)) return false;

  // Weights alternate 3, 1, 3, ... starting at the rightmost data digit
  // (the digit immediately left of the check digit).
  let sum = 0;
  let weight = 3;
  for (let i = len - 2; i >= 0; i--) {
    sum += (code.charCodeAt(i) - 48) * weight;
    weight = weight === 3 ? 1 : 3;
  }

  const check = (10 - (sum % 10)) % 10;
  return check === code.charCodeAt(len - 1) - 48;
}

export function solve(issn: string): boolean {
  if (typeof issn !== "string") {
    return false;
  }

  // Accepted forms: "NNNN-NNNC" or "NNNNNNNC", where C is a digit or X/x.
  if (!/^\d{4}-?\d{3}[\dXx]$/.test(issn)) {
    return false;
  }

  const compact = issn.replace("-", "");

  // First seven digits weighted 8, 7, 6, 5, 4, 3, 2 (weight = 8 - index).
  let sum = 0;
  for (let i = 0; i < 7; i++) {
    sum += (8 - i) * Number(compact.charAt(i));
  }

  // Check character: X (either case) counts as 10.
  const check = compact.charAt(7).toUpperCase();
  sum += check === "X" ? 10 : Number(check);

  return sum % 11 === 0;
}

export function solve(a: string, b: string): number {
  // Let `s` be the longer string and `t` the shorter one, so each DP row has
  // length |t| + 1 and memory stays O(min(|a|, |b|)). Distance is symmetric.
  let s = a;
  let t = b;
  if (s.length < t.length) {
    s = b;
    t = a;
  }

  const n = s.length;
  const m = t.length;
  if (m === 0) return n;

  // Two rolling rows: prev = row i-1, curr = row i of the DP table.
  let prev: number[] = [];
  let curr: number[] = [];
  for (let j = 0; j <= m; j++) {
    prev.push(j);
    curr.push(0);
  }

  for (let i = 1; i <= n; i++) {
    const sc = s.charCodeAt(i - 1); // UTF-16 code unit
    curr[0] = i;
    for (let j = 1; j <= m; j++) {
      // Substitution, or free match, from the diagonal.
      let best = prev[j - 1] + (sc === t.charCodeAt(j - 1) ? 0 : 1);
      // Deletion from the cell above.
      const del = prev[j] + 1;
      if (del < best) best = del;
      // Insertion from the cell to the left.
      const ins = curr[j - 1] + 1;
      if (ins < best) best = ins;
      curr[j] = best;
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[m];
}

export function solve(installed: string[], range: string): string | null {
  // lib.maxSatisfying skips entries that are not valid semver versions:
  // Range.prototype.test returns false for unparseable strings.
  // Prerelease handling is also delegated to the range semantics.
  return lib.maxSatisfying(installed, range, undefined);
}

export function solve(doc: unknown, pointer: string): unknown {
  // The empty pointer refers to the whole document.
  if (pointer === "") {
    return doc;
  }

  if (!pointer.startsWith("/")) {
    throw new Error(`Invalid JSON Pointer ${JSON.stringify(pointer)}: must be empty or start with "/"`);
  }

  // Drop the leading "/" and split into reference tokens. A lone "/" yields
  // one empty token, which names the member whose key is "".
  const tokens = pointer.slice(1).split("/");

  let current: unknown = doc;

  for (const raw of tokens) {
    // RFC 6901: unescape "~1" first, then "~0" (order matters).
    const token = raw.replace(/~1/g, "/").replace(/~0/g, "~");

    if (Array.isArray(current)) {
      // Valid array index: "0" or a decimal integer without leading zeros.
      // Anything else (including "-") does not reference an existing element.
      if (!/^(0|[1-9][0-9]*)$/.test(token)) {
        return undefined;
      }
      const index = Number(token);
      if (index >= current.length) {
        return undefined;
      }
      current = current[index];
    } else if (typeof current === "object" && current !== null) {
      // Only own properties count; never read inherited ones such as "constructor".
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        return undefined;
      }
      current = (current as Record<string, unknown>)[token];
    } else {
      // Primitives have no members or elements.
      return undefined;
    }
  }

  return current;
}

export function solve(sub: string, sup: string): boolean {
  return lib.subset(sub, sup, {});
}

/** Inclusive range of leading digits; both bounds have the same number of digits. */
type PrefixRange = readonly [number, number];

interface Issuer {
  readonly prefixes: readonly PrefixRange[];
  readonly lengths: readonly number[];
}

// Single prefixes are written as [p, p].
const ISSUERS: readonly Issuer[] = [
  { prefixes: [[4, 4]], lengths: [13, 16, 19] }, // Visa
  { prefixes: [[51, 55], [2221, 2720]], lengths: [16] }, // Mastercard
  { prefixes: [[34, 34], [37, 37]], lengths: [15] }, // American Express
  { prefixes: [[6011, 6011], [622126, 622925], [644, 649], [65, 65]], lengths: [16, 19] }, // Discover
  { prefixes: [[300, 305], [36, 36], [38, 38]], lengths: [14, 15, 16, 17, 18, 19] }, // Diners Club
  { prefixes: [[3528, 3589]], lengths: [16, 17, 18, 19] }, // JCB
  { prefixes: [[62, 62]], lengths: [16, 17, 18, 19] }, // UnionPay
];

/** True if the first N digits of `digits` (N = width of `low`) lie within [low, high]. */
function prefixMatches(digits: string, [low, high]: PrefixRange): boolean {
  const width = String(low).length;
  if (digits.length < width) return false;
  const head = Number(digits.slice(0, width));
  return head >= low && head <= high;
}

function matchesKnownIssuer(digits: string): boolean {
  return ISSUERS.some(
    ({ prefixes, lengths }) =>
      lengths.includes(digits.length) &&
      prefixes.some((range) => prefixMatches(digits, range)),
  );
}

/** Luhn (mod 10) checksum for a string of ASCII digits. */
function passesLuhn(digits: string): boolean {
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    let d = digits.charCodeAt(digits.length - 1 - i) - 48; // 48 = '0'
    if (i % 2 === 1) {
      // every second digit from the right is doubled
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
  }
  return sum % 10 === 0;
}

/** True if `card` is a plausible payment card number: known issuer prefix and length, and Luhn-valid. */
export function solve(card: string): boolean {
  const digits = card.replace(/[ -]/g, "");
  return /^\d+$/.test(digits) && matchesKnownIssuer(digits) && passesLuhn(digits);
}

export function solve(obj: object, updates: [string | (string | number)[], unknown][]): object {
  const toKeys = (p: string | (string | number)[]): (string | number)[] =>
    typeof p === "string"
      ? (p.match(/[^.[\]]+/g) ?? []).map((t) => (/^\d+$/.test(t) ? Number(t) : t))
      : p;
  for (const [path, value] of updates) {
    const keys = toKeys(path);
    if (keys.length === 0) continue;
    let cur: any = obj;
    for (let i = 0; i < keys.length - 1; i++) {
      const k = keys[i];
      if (typeof cur[k] !== "object" || cur[k] === null)
        cur[k] = typeof keys[i + 1] === "number" ? [] : {};
      cur = cur[k];
    }
    cur[keys[keys.length - 1]] = value;
  }
  return obj;
}

export function solve(emails: string[]): string[] {
  const seen = new Set<string>();
  for (const raw of emails) {
    const email = raw.toLowerCase();
    const at = email.lastIndexOf("@");
    let canon = email;
    if (at >= 0) {
      let local = email.slice(0, at);
      let domain = email.slice(at + 1);
      const plus = local.indexOf("+");
      if (domain === "gmail.com" || domain === "googlemail.com") {
        if (plus >= 0) local = local.slice(0, plus);
        local = local.replace(/\./g, "");
        domain = "gmail.com";
      } else if (["outlook.com", "hotmail.com", "live.com"].includes(domain)) {
        if (plus >= 0) local = local.slice(0, plus);
      }
      canon = `${local}@${domain}`;
    }
    seen.add(canon);
  }
  return [...seen];
}

// Grammar (ASCII only):
//   input  = "(" coords ")" | coords     (parentheses only as one matched pair)
//   coords = number "," " "* number      (no space before the comma)
//   number = ["+" | "-"] digits ["." digits]
const PAIR = /^([+-]?[0-9]+(?:\.[0-9]+)?),[ ]*([+-]?[0-9]+(?:\.[0-9]+)?)$/;

export function solve(text: string): boolean {
  const inner =
    text.startsWith("(") && text.endsWith(")") ? text.slice(1, -1) : text;

  const m = PAIR.exec(inner);
  if (m === null) return false;

  const [, lat = "", lon = ""] = m;
  return withinLimit(lat, 90) && withinLimit(lon, 180);
}

// Exact check of |value| <= limit done on the digit strings, so floating-point
// rounding cannot accept values such as "90.00000000000000001".
function withinLimit(token: string, limit: number): boolean {
  const unsigned = token.replace(/^[+-]/, "");
  const dot = unsigned.indexOf(".");
  const intDigits = dot === -1 ? unsigned : unsigned.slice(0, dot);
  const fracDigits = dot === -1 ? "" : unsigned.slice(dot + 1);

  const intPart = intDigits.replace(/^0+/, ""); // drop leading zeros
  const bound = String(limit);

  if (intPart.length !== bound.length) return intPart.length < bound.length;
  if (intPart !== bound) return intPart < bound; // same length: string order = numeric order
  return /^0*$/.test(fracDigits); // equal to the limit only if the fraction is zero
}

export function solve(word: string, dictionary: string[]): string {
  const dist = (a: string, b: string): number => {
    let row = Array.from({ length: b.length + 1 }, (_, j) => j);
    for (let i = 1; i <= a.length; i++) {
      const next = [i];
      for (let j = 1; j <= b.length; j++)
        next[j] = Math.min(row[j] + 1, next[j - 1] + 1, row[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
      row = next;
    }
    return row[b.length];
  };
  let best = "", bestD = Infinity;
  for (const entry of dictionary) {
    const d = dist(word, entry);
    if (d < bestD) { bestD = d; best = entry; }
  }
  return best;
}

export function solve(urls: string[]): string[] {
  const re = /^https?:\/\/(?:[^\s@\/?#]+@)?(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}(?::\d{1,5})?(?:[\/?#]\S*)?$/i;
  return urls.filter((u) => re.test(u));
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  const indeg = new Map<string, number>(nodes.map(n => [n, 0]));
  const adj = new Map<string, string[]>(nodes.map(n => [n, []]));
  for (const [a, b] of edges) {
    if (!indeg.has(a) || !indeg.has(b)) throw new Error(`Unknown node in edge [${a}, ${b}]`);
    adj.get(a)!.push(b);
    indeg.set(b, indeg.get(b)! + 1);
  }
  const queue = nodes.filter(n => indeg.get(n) === 0);
  for (let i = 0; i < queue.length; i++) {
    for (const m of adj.get(queue[i])!) {
      indeg.set(m, indeg.get(m)! - 1);
      if (indeg.get(m) === 0) queue.push(m);
    }
  }
  if (queue.length !== nodes.length) throw new Error("Cycle detected");
  return queue;
}

export function solve(epochMs: number): string {
  // toISOString always renders UTC with millisecond precision: YYYY-MM-DDTHH:mm:ss.sssZ.
  // Drop the ".sss" part to get whole seconds.
  return new Date(epochMs).toISOString().replace(/\.\d{3}Z$/, "Z");
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) throw new Error("Invalid base64 length");
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const out: number[] = [];
  for (let i = 0; i < text.length; i += 4) {
    const chunk = text.slice(i, i + 4);
    const pad = chunk.endsWith("==") ? 2 : chunk.endsWith("=") ? 1 : 0;
    if (pad > 0 && i + 4 !== text.length) throw new Error("Padding only allowed at end");
    let n = 0;
    for (let j = 0; j < 4; j++) {
      const c = chunk[j];
      if (c === "=" && j < 4 - pad) throw new Error(`Invalid padding at index ${i + j}`);
      const v = c === "=" ? 0 : alphabet.indexOf(c);
      if (v < 0) throw new Error(`Invalid base64 character: ${c}`);
      n = (n << 6) | v;
    }
    const bytes = [(n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff];
    out.push(...bytes.slice(0, 3 - pad));
  }
  return out;
}

export function solve<T>(value: T): T {
  return lib.cloneDeep(value) as T;
}

export function solve(text: string): string {
    // Encode the string as UTF-8 manually (no TextEncoder, which is not part of the ECMAScript standard library).
    const out: number[] = [];
    // for...of iterates by code point; a lone surrogate arrives as its own value in 0xD800..0xDFFF.
    for (const ch of text) {
        let cp = ch.codePointAt(0)!;
        if (cp >= 0xD800 && cp <= 0xDFFF) {
            cp = 0xFFFD; // replace lone surrogates, matching TextEncoder behavior
        }
        if (cp < 0x80) {
            out.push(cp);
        } else if (cp < 0x800) {
            out.push(0xC0 | (cp >> 6), 0x80 | (cp & 0x3F));
        } else if (cp < 0x10000) {
            out.push(
                0xE0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3F),
                0x80 | (cp & 0x3F)
            );
        } else {
            out.push(
                0xF0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3F),
                0x80 | ((cp >> 6) & 0x3F),
                0x80 | (cp & 0x3F)
            );
        }
    }

    const bytes = new Uint8Array(out);
    const digest = lib.md5(bytes);

    return Array.from(digest as ArrayLike<number>, (b: number) =>
        b.toString(16).padStart(2, "0")
    ).join("");
}

export function solve(a: string, b: string): boolean {
  return lib.intersects(a, b);
}

export function solve(range: string): string | null {
  if (typeof range !== 'string') {
    return null;
  }
  try {
    const result = lib.minVersion(range);
    return result ? result.version : null;
  } catch (_err) {
    // lib.minVersion throws on an invalid range expression
    return null;
  }
}

export function solve(text: string): string | null {
  // A version-like run is 1-3 dot-separated digit runs of 1-16 digits each,
  // bounded by non-digits so that over-long digit runs do not match.
  const m = /(?<!\d)(\d{1,16})(?:\.(\d{1,16}))?(?:\.(\d{1,16}))?(?!\d)/.exec(text);
  if (!m) return null;
  return `${m[1]}.${m[2] ?? "0"}.${m[3] ?? "0"}`;
}

export function solve(stamps: string[]): number[] {
  const times = stamps.map((s) => {
    const parsed = lib.parseISO(s);
    if (isNaN(parsed.getTime())) {
      throw new RangeError(`Invalid date: ${s}`);
    }

    // A time part is present when the string contains 'T' or a space.
    const hasTime = /[T ]/.test(s);
    // An offset is a trailing 'Z' or ±hh[:mm] that follows the time part.
    const hasOffset = hasTime && /(?:Z|[+-]\d{2}(?::?\d{2})?)$/.test(s);

    if (hasOffset) {
      // With an explicit offset, lib.parseISO returns the correct instant.
      return parsed.getTime();
    }

    // Without an offset, lib.parseISO returns a local-time-shifted Date,
    // which is wrong across DST gaps. Appending an explicit UTC designator
    // makes it compute the exact instant. Date-only strings get midnight UTC.
    const normalized = s + (hasTime ? "Z" : "T00:00Z");
    const utc = lib.parseISO(normalized);
    if (isNaN(utc.getTime())) {
      throw new RangeError(`Invalid date: ${s}`);
    }
    return utc.getTime();
  });

  return times.sort((a, b) => a - b);
}

export function solve(name: string, namespace: string): string {
    // Parse the namespace UUID (hyphens optional) into 16 bytes.
    const nsHex = namespace.replace(/-/g, "");
    if (!/^[0-9a-fA-F]{32}$/.test(nsHex)) {
        throw new RangeError("Invalid namespace UUID: " + namespace);
    }
    const nsBytes: number[] = [];
    for (let i = 0; i < 16; i++) {
        nsBytes.push(parseInt(nsHex.substr(i * 2, 2), 16));
    }

    // Manual UTF-8 encoding of the name (lone surrogates become U+FFFD).
    const nameBytes: number[] = [];
    for (let i = 0; i < name.length; i++) {
        let cp = name.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff) {
            const lo = i + 1 < name.length ? name.charCodeAt(i + 1) : 0;
            if (lo >= 0xdc00 && lo <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
                i++;
            } else {
                cp = 0xfffd;
            }
        } else if (cp >= 0xdc00 && cp <= 0xdfff) {
            cp = 0xfffd;
        }

        if (cp < 0x80) {
            nameBytes.push(cp);
        } else if (cp < 0x800) {
            nameBytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            nameBytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            nameBytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    // Message = namespace bytes || name bytes.
    const message = new Uint8Array(16 + nameBytes.length);
    message.set(nsBytes, 0);
    message.set(nameBytes, 16);

    // SHA-1 digest via the library; keep the first 16 bytes.
    const digest = lib.sha1(message);
    const b: number[] = [];
    for (let i = 0; i < 16; i++) {
        b.push(digest[i]);
    }

    // Set version (5) and RFC 4122 variant bits.
    b[6] = (b[6] & 0x0f) | 0x50;
    b[8] = (b[8] & 0x3f) | 0x80;

    // Format as lowercase 8-4-4-4-12.
    const hex = b.map((x) => x.toString(16).padStart(2, "0")).join("");
    return (
        hex.slice(0, 8) + "-" +
        hex.slice(8, 12) + "-" +
        hex.slice(12, 16) + "-" +
        hex.slice(16, 20) + "-" +
        hex.slice(20, 32)
    );
}

export function solve(iban: string): boolean {
  const normalized = iban.replace(/[\s-]/g, '').toUpperCase();
  return lib.isIBAN(normalized);
}

export function solve(version: string, kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease', id?: string): string | null {
  const m = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$/.exec(version);
  if (!m) return null;
  const M = +m[1], n = +m[2], p = +m[3];
  const pre = m[4] ? m[4].split('.') : [];
  const v = (a: number, b: number, c: number) => `${a}.${b}.${c}`;
  const fresh = id ? `${id}.0` : '0';
  switch (kind) {
    case 'major': return v(pre.length > 0 && n === 0 && p === 0 ? M : M + 1, 0, 0);
    case 'minor': return pre.length > 0 && p === 0 ? v(M, n, 0) : v(M, n + 1, 0);
    case 'patch': return pre.length > 0 ? v(M, n, p) : v(M, n, p + 1);
    case 'premajor': return `${v(M + 1, 0, 0)}-${fresh}`;
    case 'preminor': return `${v(M, n + 1, 0)}-${fresh}`;
    case 'prepatch': return `${v(M, n, p + 1)}-${fresh}`;
    case 'prerelease': {
      if (pre.length === 0) return `${v(M, n, p + 1)}-${fresh}`;
      if (id !== undefined && pre[0] !== id) return `${v(M, n, p)}-${fresh}`;
      const i = pre.length - 1;
      if (/^\d+$/.test(pre[i])) pre[i] = String(+pre[i] + 1); else pre.push('0');
      return `${v(M, n, p)}-${pre.join('.')}`;
    }
  }
}

export function solve(name: string, namespace: string): string {
    const uuidPattern = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
    if (typeof namespace !== "string" || !uuidPattern.test(namespace)) {
        throw new TypeError("Invalid UUID namespace");
    }
    const result: string = lib.v3(name, namespace.toLowerCase());
    return result.toLowerCase();
}

export function solve(version: string, range: string): boolean {
  return lib.gtr(version, range);
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  const s = isbn.replace(/[ -]/g, "");
  const ok10 = () => /^\d{9}[\dX]$/.test(s) &&
    [...s].reduce((sum, c, i) => sum + (10 - i) * (c === "X" ? 10 : +c), 0) % 11 === 0;
  const ok13 = () => /^\d{13}$/.test(s) &&
    [...s].reduce((sum, c, i) => sum + (i % 2 ? 3 : 1) * +c, 0) % 10 === 0;
  if (version === 10) return ok10();
  if (version === 13) return ok13();
  return ok10() || ok13();
}

export function solve(text: string): string {
    // Manually encode `text` as UTF-8 (TextEncoder is not part of ECMAScript).
    // Unpaired surrogates are replaced with U+FFFD, as TextEncoder does.
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff) {
            const next = i + 1 < text.length ? text.charCodeAt(i + 1) : -1;
            if (next >= 0xdc00 && next <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
                i++;
            } else {
                cp = 0xfffd;
            }
        } else if (cp >= 0xdc00 && cp <= 0xdfff) {
            cp = 0xfffd;
        }

        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            bytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            bytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    const digest = lib.sha1(Uint8Array.from(bytes));

    let hex = "";
    for (let i = 0; i < digest.length; i++) {
        hex += digest[i].toString(16).padStart(2, "0");
    }
    return hex;
}

export function solve(isin: string): boolean {
  if (!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) return false;
  const digits = [...isin]
    .map((c) => (/[A-Z]/.test(c) ? String(c.charCodeAt(0) - 55) : c))
    .join("");
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    let d = Number(digits[digits.length - 1 - i]);
    if (i % 2 === 1) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
  }
  return sum % 10 === 0;
}

export function solve(card: string): boolean {
  const d = card.replace(/[ -]/g, "");
  if (!/^\d+$/.test(d)) return false;
  const n = d.length;
  const p2 = +d.slice(0, 2), p3 = +d.slice(0, 3), p4 = +d.slice(0, 4), p6 = +d.slice(0, 6);
  const inRange = (x: number, lo: number, hi: number) => x >= lo && x <= hi;
  const issuerOk =
    (d[0] === "4" && [13, 16, 19].includes(n)) ||
    ((inRange(p2, 51, 55) || inRange(p4, 2221, 2720)) && n === 16) ||
    ((p2 === 34 || p2 === 37) && n === 15) ||
    ((p4 === 6011 || inRange(p6, 622126, 622925) || inRange(p3, 644, 649) || p2 === 65) && (n === 16 || n === 19)) ||
    ((inRange(p3, 300, 305) || p2 === 36 || p2 === 38) && inRange(n, 14, 19)) ||
    (inRange(p4, 3528, 3589) && inRange(n, 16, 19)) ||
    (p2 === 62 && inRange(n, 16, 19));
  if (!issuerOk) return false;
  let sum = 0;
  for (let i = 0; i < n; i++) {
    let v = +d[n - 1 - i];
    if (i % 2) v = v * 2 > 9 ? v * 2 - 9 : v * 2;
    sum += v;
  }
  return sum % 10 === 0;
}

export function solve(text: string): boolean {
  const num = "[+-]?(?:\\d+(?:\\.\\d+)?|\\.\\d+)";
  const re = new RegExp(`^(\\()?(${num}),[ ]*(${num})(\\))?$`);
  const m = re.exec(text);
  if (!m) return false;
  // Parentheses must be both present or both absent.
  if ((m[1] === undefined) !== (m[4] === undefined)) return false;
  const lat = Number(m[2]);
  const lon = Number(m[3]);
  return Math.abs(lat) <= 90 && Math.abs(lon) <= 180;
}

export function solve(mac: string): boolean {
  const patterns = [
    // EUI-48 with ':' or '-' (6 octets); the \1 backreference forces one separator style
    /^[0-9a-f]{2}([:-])(?:[0-9a-f]{2}\1){4}[0-9a-f]{2}$/i,
    // EUI-64 with ':' or '-' (8 octets)
    /^[0-9a-f]{2}([:-])(?:[0-9a-f]{2}\1){6}[0-9a-f]{2}$/i,
    // Dotted form, 3 groups of 4 hex digits
    /^(?:[0-9a-f]{4}\.){2}[0-9a-f]{4}$/i,
    // Dotted form, 4 groups of 4 hex digits
    /^(?:[0-9a-f]{4}\.){3}[0-9a-f]{4}$/i,
  ];
  return patterns.some((p) => p.test(mac));
}

export function solve(code: string): boolean {
  if (![8, 13, 14].includes(code.length) || !/^[0-9]+$/.test(code)) return false;
  const n = code.length;
  let sum = 0;
  // Data digits are all but the last. The rightmost data digit has weight 3, alternating with 1.
  for (let i = 0; i < n - 1; i++) {
    const d = code.charCodeAt(i) - 48;
    sum += d * ((n - 2 - i) % 2 === 0 ? 3 : 1);
  }
  const check = (10 - (sum % 10)) % 10;
  return check === code.charCodeAt(n - 1) - 48;
}

type CoreParts = { major: number; minor: number; patch: number; pre: boolean };

function parseParts(v: string): CoreParts {
  const noBuild = v.split("+")[0];
  const dash = noBuild.indexOf("-");
  const core = dash === -1 ? noBuild : noBuild.slice(0, dash);
  const [major, minor, patch] = core.split(".").map(Number);
  return { major, minor, patch, pre: dash !== -1 };
}

export function solve(a: string, b: string): string | null {
  const c: number = lib.compare(a, b);
  if (c === 0) return null;

  const lo = parseParts(c < 0 ? a : b);
  const hi = parseParts(c < 0 ? b : a);

  // Highest core part that differs between the two versions
  let part: string | null = null;
  if (hi.major !== lo.major) part = "major";
  else if (hi.minor !== lo.minor) part = "minor";
  else if (hi.patch !== lo.patch) part = "patch";

  // Lower is a prerelease, higher is a release
  if (lo.pre && !hi.pre) {
    if (part !== null) return part;
    // Cores are equal: 0.0.0-x -> 0.0.0 style transitions
    if (lo.minor === 0 && lo.patch === 0) return "major";
    return lo.patch !== 0 ? "patch" : "minor";
  }

  // Higher is a prerelease
  if (hi.pre) {
    return part !== null ? "pre" + part : "prerelease";
  }

  // Both releases (cores must differ since compare was non-zero)
  return part;
}

export function solve(issn: string): boolean {
  const m = /^(\d{4})-?(\d{3})([\dXx])$/.exec(issn);
  if (!m) return false;
  const digits = m[1] + m[2] + m[3];
  let sum = 0;
  for (let i = 0; i < 8; i++) {
    const c = digits[i];
    const v = c === 'X' || c === 'x' ? 10 : Number(c);
    sum += (8 - i) * v;
  }
  return sum % 11 === 0;
}

export function solve(a: string, b: string): number {
  if (a.length < b.length) [a, b] = [b, a];
  let prev: number[] = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur: number[] = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(
        prev[j] + 1,
        cur[j - 1] + 1,
        prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)
      );
    }
    prev = cur;
  }
  return prev[b.length];
}

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === "") return doc;
  if (!pointer.startsWith("/")) throw new Error(`Invalid JSON Pointer: ${pointer}`);
  let cur: any = doc;
  for (const raw of pointer.slice(1).split("/")) {
    const key = raw.replace(/~1/g, "/").replace(/~0/g, "~");
    if (cur === null || typeof cur !== "object") return undefined;
    if (Array.isArray(cur)) {
      if (!/^(0|[1-9]\d*)$/.test(key) || Number(key) >= cur.length) return undefined;
      cur = cur[Number(key)];
    } else {
      if (!Object.prototype.hasOwnProperty.call(cur, key)) return undefined;
      cur = cur[key];
    }
  }
  return cur;
}

export function solve(name: string): boolean {
  if (name.length > 253) return false;
  const labels = name.split('.');
  if (labels.length < 2) return false;
  const label = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/;
  const tld = labels[labels.length - 1];
  if (!labels.slice(0, -1).every(l => label.test(l))) return false;
  if (tld.length < 2) return false;
  if (/^xn--/i.test(tld)) return label.test(tld);
  return /^\p{L}+$/u.test(tld);
}

export function solve<T>(value: T): T {
  return lib.cloneDeep(value);
}

export function solve(sub: string, sup: string): boolean {
  return lib.subset(sub, sup);
}

export function solve(installed: string[], range: string): string | null {
  // lib.maxSatisfying skips invalid version strings (Range.test rejects them),
  // returns null for an invalid range, and applies the standard prerelease rules.
  return lib.maxSatisfying(installed, range)
}

export function solve(obj: object, updates: [string | (string | number)[], unknown][]): object {
  for (const [path, value] of updates) {
    lib.set(obj, path, value);
  }
  return obj;
}

export function solve(versions: string[]): string[] {
  // lib.sort orders by SemVer precedence, with its own build-metadata tiebreak.
  // Work on a copy so the input array is not mutated.
  const sorted: string[] = lib.sort([...versions]);

  // Versions with equal precedence differ only in build metadata. Stripping
  // everything from the first '+' leaves core + prerelease, which is equal
  // exactly when precedence is equal (valid semver has no leading zeros in
  // numeric identifiers, so string equality matches numeric equality).
  const precedenceKey = (v: string): string => v.split('+')[0];

  const out: string[] = [];
  let i = 0;
  while (i < sorted.length) {
    const key = precedenceKey(sorted[i]);
    let j = i + 1;
    while (j < sorted.length && precedenceKey(sorted[j]) === key) {
      j++;
    }

    // Equal-precedence run: order by full string, lexically by ASCII/UTF-16 code units.
    const group = sorted.slice(i, j);
    group.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    for (const v of group) {
      out.push(v);
    }
    i = j;
  }

  return out;
}

export function solve(name: string, namespace: string): string {
    return lib.v5(name, namespace);
}

export function solve(word: string, dictionary: string[]): string {
    return lib.closest(word, dictionary);
}

export function solve(name: string): boolean {
  if (typeof name !== "string") return false;

  // Whole name: at most 253 characters (code points, so astral characters count once).
  if (Array.from(name).length > 253) return false;

  const labels = name.split(".");

  // The last element is the TLD. A trailing dot leaves it empty, which is rejected below.
  const tld = labels.pop() ?? "";

  // At least two labels are required.
  if (labels.length === 0) return false;

  // Ordinary label: 1-63 ASCII letters, digits or hyphens, not starting or ending with a hyphen.
  // Digits-only labels are allowed.
  const ordinaryLabel = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/;
  if (!labels.every((label) => ordinaryLabel.test(label))) return false;

  // Punycode TLD: starts with "xn--" (matched case-insensitively, as DNS names are)
  // and must itself be a valid ordinary label.
  if (/^xn--/i.test(tld)) return ordinaryLabel.test(tld);

  // Otherwise the TLD is letters only (international letters allowed):
  // no digits, no hyphens, and 2-63 characters long.
  const tldLength = Array.from(tld).length;
  return tldLength >= 2 && tldLength <= 63 && /^\p{L}+$/u.test(tld);
}

const OCT = '(25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)';
const V4 = new RegExp(`^${OCT}(\\.${OCT}){3}$`);

function isV6(s: string): boolean {
  const pct = s.indexOf('%');
  let addr = pct < 0 ? s : s.slice(0, pct);
  if (pct >= 0 && !(/^[0-9a-z]+$/i.test(s.slice(pct + 1)) && /^fe[89ab][0-9a-f]:/i.test(addr))) return false;
  let ok = true;
  addr = addr.replace(/(^|:)([\d.]*\.[\d.]*)$/, (_, c: string, v: string) => {
    if (!V4.test(v)) ok = false;
    return c + '0:0';
  });
  const parts = addr.split('::');
  if (!ok || parts.length > 2) return false;
  const groups = parts.flatMap(p => (p === '' ? [] : p.split(':')));
  if (!groups.every(g => /^[0-9a-f]{1,4}$/i.test(g))) return false;
  return parts.length === 2 ? groups.length <= 7 : groups.length === 8;
}

export function solve(text: string, version?: 4 | 6): boolean {
  const v4 = V4.test(text);
  const v6 = isV6(text);
  return version === 4 ? v4 : version === 6 ? v6 : v4 || v6;
}

export function solve(text: string): string {
    // Encode the string as UTF-8 manually (no TextEncoder, which is a Web API).
    // Unpaired surrogates are replaced with U+FFFD, matching TextEncoder behavior.
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff) {
            const lo = i + 1 < text.length ? text.charCodeAt(i + 1) : 0;
            if (lo >= 0xdc00 && lo <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
                i++;
            } else {
                cp = 0xfffd;
            }
        } else if (cp >= 0xdc00 && cp <= 0xdfff) {
            cp = 0xfffd;
        }

        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            bytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            bytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    // Delegate the MD5 computation to the library.
    const digest = lib.md5(new Uint8Array(bytes));

    // Convert the 16-byte digest to 32 lowercase hex characters.
    let hex = "";
    for (let i = 0; i < 16; i++) {
        hex += Number(digest[i]).toString(16).padStart(2, "0");
    }
    return hex;
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 input: length must be a multiple of 4");
  }
  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(text)) {
    throw new Error("Invalid base64 input: illegal characters or padding");
  }
  return Array.from(lib.toByteArray(text));
}

export function solve(a: string, b: string): boolean {
  try {
    return lib.intersects(a, b);
  } catch {
    return false;
  }
}

const SCHEME_RE = /^https?:\/\//i;
const LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i;
const TLD_RE = /^[a-z]{2,63}$/i;

function extractHost(url: string): string | null {
  const rest = url.replace(SCHEME_RE, '');
  const end = rest.search(/[\/?#]/);
  let authority = end === -1 ? rest : rest.slice(0, end);

  const at = authority.lastIndexOf('@');
  if (at !== -1) {
    authority = authority.slice(at + 1);
  }

  // IPv6 literals are not domain names
  if (authority.startsWith('[')) {
    return null;
  }

  let host = authority;
  const colon = authority.lastIndexOf(':');
  if (colon !== -1) {
    const port = authority.slice(colon + 1);
    if (!/^\d{1,5}$/.test(port) || Number(port) > 65535) {
      return null;
    }
    host = authority.slice(0, colon);
  }

  return host;
}

function isFQDN(host: string): boolean {
  if (host.length === 0 || host.length > 253) {
    return false;
  }

  const labels = host.split('.');
  if (labels.length < 2) {
    return false; // rejects "localhost" and other single-label hosts
  }

  for (const label of labels) {
    if (!LABEL_RE.test(label)) {
      return false;
    }
  }

  // A purely alphabetic TLD rules out IPv4 addresses such as 1.2.3.4
  const tld = labels[labels.length - 1];
  return TLD_RE.test(tld);
}

export function solve(urls: string[]): string[] {
  return urls.filter((url) => {
    if (typeof url !== 'string') {
      return false;
    }
    if (!SCHEME_RE.test(url)) {
      return false;
    }
    if (!lib.isURL(url, {
      protocols: ['http', 'https'],
      require_protocol: true,
      require_valid_protocol: true,
      require_tld: true,
      allow_protocol_relative_urls: false,
    })) {
      return false;
    }

    const host = extractHost(url);
    return host !== null && isFQDN(host);
  });
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  // lib.toposort does not detect duplicate node names. With duplicates, the
  // node-to-index lookup becomes ambiguous and the output can repeat a node
  // and misplace its edges, so reject them up front.
  const seen = new Set<string>();
  for (const node of nodes) {
    if (seen.has(node)) {
      throw new Error(`Duplicate node: ${JSON.stringify(node)}`);
    }
    seen.add(node);
  }

  // lib.toposort throws on unknown nodes in edges and on cyclic dependencies.
  return lib.toposort(nodes, edges);
}

export function solve(range: string): string | null {
  let v;
  try {
    v = lib.minVersion(range);
  } catch {
    // An invalid range makes the Range constructor throw.
    return null;
  }

  if (!v) {
    return null;
  }

  const core = `${v.major}.${v.minor}.${v.patch}`;
  return v.prerelease.length > 0 ? `${core}-${v.prerelease.join('.')}` : core;
}

export function solve(version: string, range: string): boolean {
  return lib.gtr(version, range);
}

export function solve(stamps: string[]): number[] {
  const epochs = stamps.map((input) => {
    if (typeof input !== "string") {
      throw new RangeError(`Invalid date: ${String(input)}`);
    }

    let s = input;

    // Locate the time part (after 'T' or a space), if any.
    const delimIndex = s.search(/[T ]/);
    const timePart = delimIndex === -1 ? null : s.slice(delimIndex + 1);

    // Normalize a lowercase 'z' designator to 'Z'.
    if (timePart !== null && timePart.endsWith("z")) {
      s = s.slice(0, -1) + "Z";
    } else if (timePart === null && s.endsWith("z")) {
      s = s.slice(0, -1) + "Z";
    }

    // Detect an explicit offset. A date-only string is only considered to
    // carry an offset if it ends in 'Z' (the '-' in dates is not an offset).
    const hasOffset =
      timePart !== null
        ? /(?:Z|[+-]\d{2}(?::?\d{2})?)$/.test(timePart)
        : /Z$/.test(s);

    // Strings without an offset are UTC. Appending 'Z' forces lib.parseISO
    // onto its timezone branch, which yields a true UTC instant; its
    // no-offset branch would otherwise depend on the local time zone.
    if (!hasOffset) {
      s += "Z";
    }

    const date: Date = lib.parseISO(s);
    const ms = date.getTime();

    if (Number.isNaN(ms)) {
      throw new RangeError(`Invalid date: ${input}`);
    }

    return ms;
  });

  return epochs.sort((a, b) => a - b);
}

export function solve(epochMs: number): string {
  // Build a Date whose local-time accessors report UTC values, so the
  // library's local-time formatting yields UTC wall-clock fields. The
  // timezone offset is reported as 0, which makes the library emit "Z".
  const inUtc = (value: number): Date => {
    const d = new Date(value);
    d.getDate = () => d.getUTCDate();
    d.getMonth = () => d.getUTCMonth();
    d.getFullYear = () => d.getUTCFullYear();
    d.getHours = () => d.getUTCHours();
    d.getMinutes = () => d.getUTCMinutes();
    d.getSeconds = () => d.getUTCSeconds();
    d.getTimezoneOffset = () => 0;
    return d;
  };

  // Default format is "extended" and representation is "complete",
  // giving e.g. "2024-02-29T10:00:00Z". Milliseconds are dropped by the library.
  return lib.formatISO(epochMs, { in: inUtc });
}

declare const lib: {
  normalizeEmail(email: string, options?: Record<string, boolean>): string | false;
};

const GMAIL_DOMAINS: ReadonlySet<string> = new Set(["gmail.com", "googlemail.com"]);

// Every option is set explicitly so the library's default merge cannot
// introduce subaddress or dot handling for domains outside the spec.
function libOptions(): Record<string, boolean> {
  return {
    all_lowercase: true,
    gmail_remove_subaddress: true,
    gmail_remove_dots: true,
    gmail_convert_googlemaildotcom: true,
    gmail_lowercase: true,
    icloud_remove_subaddress: false,
    icloud_lowercase: true,
    outlookdotcom_remove_subaddress: true,
    outlookdotcom_lowercase: true,
    yahoo_remove_subaddress: false,
    yahoo_lowercase: true,
    yandex_lowercase: true,
    yandex_convert_yandexru: false,
  };
}

function canonicalize(email: string): string {
  const lowered = email.toLowerCase();
  const at = lowered.lastIndexOf("@");
  if (at < 0) {
    return lowered;
  }

  const domain = lowered.slice(at + 1);
  const normalized = lib.normalizeEmail(lowered, libOptions());

  // The library returns false when the local part is empty; keep the lowercased input.
  if (normalized === false) {
    return lowered;
  }

  if (!GMAIL_DOMAINS.has(domain)) {
    return normalized;
  }

  // The library leaves runs of consecutive dots intact, but the spec removes all dots.
  const normalizedAt = normalized.lastIndexOf("@");
  const local = normalized.slice(0, normalizedAt).replace(/\./g, "");
  if (local.length === 0) {
    return lowered;
  }
  return `${local}@gmail.com`;
}

export function solve(emails: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];
  for (const email of emails) {
    const canonical = canonicalize(email);
    if (!seen.has(canonical)) {
      seen.add(canonical);
      result.push(canonical);
    }
  }
  return result;
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  return lib.inc(version, kind, id);
}

const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;

export function solve(name: string, namespace: string): string {
  if (typeof namespace !== "string" || !UUID_RE.test(namespace)) {
    throw new TypeError("Namespace must be a valid UUID in canonical string form");
  }
  return lib.v3(name, namespace).toLowerCase();
}

export function solve(iban: string): boolean {
  // Ignore spaces and hyphens, and treat letters case-insensitively.
  const normalized = iban.replace(/[\s-]/g, '').toUpperCase();
  // lib.isIBAN checks country code, length, BBAN format, and the mod-97 checksum.
  return lib.isIBAN(normalized);
}

export function solve(text: string): string | null {
  const r = lib.coerce(text);
  if (r !== null) {
    return `${r.major}.${r.minor}.${r.patch}`;
  }

  // lib.coerce returns null for components it cannot represent as safe
  // integers (or with leading zeros). Recover the digit runs from the string.
  const m = /(^|[^\d])(\d{1,16})(?:\.(\d{1,16}))?(?:\.(\d{1,16}))?(?:$|[^\d])/.exec(text);
  if (m === null) {
    return null;
  }
  const major = BigInt(m[2]).toString();
  const minor = m[3] === undefined ? "0" : BigInt(m[3]).toString();
  const patch = m[4] === undefined ? "0" : BigInt(m[4]).toString();
  return `${major}.${minor}.${patch}`;
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

// Precedence ignores build metadata. For valid semver (no leading zeros in
// numeric identifiers), equal precedence is equivalent to equal text before '+'.
function precedenceKey(v: string): string {
  const plus = v.indexOf("+");
  return plus === -1 ? v : v.slice(0, plus);
}

export function solve(versions: string[]): string[] {
  const valid = versions.filter((v) => SEMVER_RE.test(v));

  // Heavy lifting: precedence ordering via the library.
  const sorted = lib.sort(valid.slice(), false);

  // Equal-precedence runs are contiguous after sorting. Within each run,
  // order by full string lexically, as the task requires for build metadata.
  const out: string[] = [];
  let i = 0;
  while (i < sorted.length) {
    const key = precedenceKey(sorted[i]);
    let j = i + 1;
    while (j < sorted.length && precedenceKey(sorted[j]) === key) {
      j++;
    }
    const group = sorted.slice(i, j);
    group.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    for (const g of group) {
      out.push(g);
    }
    i = j;
  }

  return out;
}

export function solve(isin: string): boolean {
  return lib.isISIN(isin);
}

export function solve(text: string): string {
    // Manually encode the string as UTF-8 (no TextEncoder, no Node/browser APIs).
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);

        // Combine UTF-16 surrogate pairs into a single code point.
        if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < text.length) {
            const next = text.charCodeAt(i + 1);
            if (next >= 0xdc00 && next <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
                i++;
            }
        }

        // Lone surrogates are replaced with U+FFFD, matching standard UTF-8 encoders.
        if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd;
        }

        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            bytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            bytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    const digest = lib.sha1(Uint8Array.from(bytes));

    let hex = "";
    for (let i = 0; i < digest.length; i++) {
        hex += digest[i].toString(16).padStart(2, "0");
    }
    return hex;
}

export function solve(a: string, b: string): string | null {
  return lib.diff(a, b) as string | null;
}

export function solve(text: string, version?: 4 | 6): boolean {
  const wantV4 = version === undefined || version === 4;
  const wantV6 = version === undefined || version === 6;

  // IPv4: lib.isIP already enforces four octets 0-255 with no leading zeros.
  if (wantV4 && lib.isIP(text, { version: 4 })) {
    return true;
  }

  if (!wantV6) {
    return false;
  }

  // IPv6 with optional zone index: "<link-local address>%<alphanumerics>".
  const pct = text.indexOf("%");
  if (pct === -1) {
    return lib.isIP(text, { version: 6 });
  }

  const addr = text.slice(0, pct);
  const zone = text.slice(pct + 1);

  if (!/^[A-Za-z0-9]+$/.test(zone)) {
    return false;
  }
  if (!lib.isIP(addr, { version: 6 })) {
    return false;
  }

  // Zone indices are only valid on link-local addresses (fe80::/10).
  const firstGroup = addr.split(":")[0];
  if (!/^[0-9a-fA-F]{1,4}$/.test(firstGroup)) {
    return false;
  }
  const value = parseInt(firstGroup, 16);
  return value >= 0xfe80 && value <= 0xfebf;
}

export function solve(mac: string): boolean {
  if (typeof mac !== 'string') {
    return false;
  }

  // Delegate format validation (octet/group counts, hex digits, dotted form) to the library.
  if (!lib.isMACAddress(mac)) {
    return false;
  }

  // The library may accept mixed separators, so enforce a single separator character:
  // every non-hex character in a valid address must be the same (':', '-', or '.').
  const separators = new Set(mac.replace(/[0-9a-fA-F]/g, ''));
  return separators.size === 1;
}

declare const lib: { isISSN(str: string, options?: object): boolean };

export function solve(issn: string): boolean {
  if (typeof issn !== "string") {
    return false;
  }
  return lib.isISSN(issn);
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  if (version == null) {
    return lib.isISBN(isbn, { version: 10 }) || lib.isISBN(isbn, { version: 13 });
  }
  return lib.isISBN(isbn, { version });
}

export function solve(a: string, b: string): number {
    return lib.distance(a, b);
}

export function solve(code: string): boolean {
  if (!/^\d+$/.test(code)) return false;

  switch (code.length) {
    case 8:
    case 13:
      return lib.isEAN(code);
    case 14:
      // lib.isEAN's regex rejects 14 digits. Dropping the leading digit yields a
      // 13-digit string whose GS1 weights (1,3,1,3,...) match the GTIN-14 weights
      // (3,1,3,1,...) of the original, so the check digit is validated correctly.
      return lib.isEAN(code.slice(1));
    default:
      return false;
  }
}

export function solve(text: string): boolean {
  if (typeof text !== 'string') return false;

  // Reject any whitespace other than the plain space character.
  if (/\s/.test(text.replace(/ /g, ''))) return false;

  // Optional single pair of parentheses wrapping the whole pair.
  const open = text.startsWith('(');
  const close = text.endsWith(')');
  if (open !== close) return false;

  let body = text;
  if (open && close) {
    if (text.length < 2) return false;
    body = text.slice(1, -1);
  }

  // Exactly one comma separates latitude and longitude.
  const parts = body.split(',');
  if (parts.length !== 2) return false;

  const lat = parts[0];
  // Any number of spaces may follow the comma; the library allows only one,
  // so normalize by removing the extra spaces before delegating.
  const lng = parts[1].replace(/^ +/, '');

  const normalized = (open && close ? '(' : '') + lat + ',' + lng + (open && close ? ')' : '');

  return lib.isLatLong(normalized);
}

// Note: lib.isCreditCard is not called. Its prefix tables differ from the
// specification (it rejects 19-digit Visa and Discover, and accepts Maestro),
// so this implementation applies the specified issuer rules directly and
// performs the Luhn check itself.

export function solve(card: string): boolean {
  // Spaces and hyphens are ignored; anything else must be a digit.
  const digits = card.replace(/[ -]/g, '');
  if (!/^\d+$/.test(digits)) {
    return false;
  }

  // Checks whether the leading `width` digits fall within [lo, hi].
  const prefixInRange = (lo: number, hi: number, width: number): boolean => {
    if (digits.length < width) {
      return false;
    }
    const value = Number(digits.slice(0, width));
    return value >= lo && value <= hi;
  };

  interface Rule {
    prefixes: Array<[lo: number, hi: number, width: number]>;
    lengths: number[];
  }

  const rules: Rule[] = [
    // Visa: 4…, 13/16/19 digits
    { prefixes: [[4, 4, 1]], lengths: [13, 16, 19] },
    // Mastercard: 51–55 or 2221–2720, 16 digits
    { prefixes: [[51, 55, 2], [2221, 2720, 4]], lengths: [16] },
    // American Express: 34 or 37, 15 digits
    { prefixes: [[34, 34, 2], [37, 37, 2]], lengths: [15] },
    // Discover: 6011, 622126–622925, 644–649, 65; 16 or 19 digits
    {
      prefixes: [[6011, 6011, 4], [622126, 622925, 6], [644, 649, 3], [65, 65, 2]],
      lengths: [16, 19],
    },
    // Diners Club: 300–305, 36, 38; 14–19 digits
    {
      prefixes: [[300, 305, 3], [36, 36, 2], [38, 38, 2]],
      lengths: [14, 15, 16, 17, 18, 19],
    },
    // JCB: 3528–3589; 16–19 digits
    { prefixes: [[3528, 3589, 4]], lengths: [16, 17, 18, 19] },
    // UnionPay: 62; 16–19 digits
    { prefixes: [[62, 62, 2]], lengths: [16, 17, 18, 19] },
  ];

  const issuerMatches = rules.some(
    (rule) =>
      rule.lengths.includes(digits.length) &&
      rule.prefixes.some(([lo, hi, width]) => prefixInRange(lo, hi, width)),
  );
  if (!issuerMatches) {
    return false;
  }

  // Luhn check.
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48;
    if (double) {
      d *= 2;
      if (d > 9) {
        d -= 9;
      }
    }
    sum += d;
    double = !double;
  }
  return sum % 10 === 0;
}

export function solve(emails: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];

  for (const raw of emails) {
    const lower = raw.toLowerCase();
    const at = lower.lastIndexOf("@");
    let canonical: string;

    if (at === -1) {
      canonical = lower;
    } else {
      let local = lower.slice(0, at);
      let domain = lower.slice(at + 1);

      if (domain === "gmail.com" || domain === "googlemail.com") {
        const plus = local.indexOf("+");
        if (plus !== -1) {
          local = local.slice(0, plus);
        }
        local = local.replace(/\./g, "");
        domain = "gmail.com";
      } else if (
        domain === "outlook.com" ||
        domain === "hotmail.com" ||
        domain === "live.com"
      ) {
        const plus = local.indexOf("+");
        if (plus !== -1) {
          local = local.slice(0, plus);
        }
      }

      canonical = `${local}@${domain}`;
    }

    if (!seen.has(canonical)) {
      seen.add(canonical);
      result.push(canonical);
    }
  }

  return result;
}

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === "") return doc;
  if (!pointer.startsWith("/")) {
    throw new Error("Invalid JSON Pointer: must be empty or start with '/'");
  }

  // Validate each step with own-property and array-index checks so that
  // lookups such as "/length" on arrays or "/constructor" on objects do not
  // reach inherited properties. Decoding order per RFC 6901: ~1 first, then ~0.
  const tokens = pointer
    .slice(1)
    .split("/")
    .map((t) => t.replace(/~1/g, "/").replace(/~0/g, "~"));

  let cur: unknown = doc;
  for (const token of tokens) {
    if (typeof cur !== "object" || cur === null) return undefined;
    if (Array.isArray(cur)) {
      if (!/^(0|[1-9]\d*)$/.test(token) || Number(token) >= cur.length) {
        return undefined;
      }
      cur = cur[Number(token)];
    } else {
      if (!Object.prototype.hasOwnProperty.call(cur, token)) return undefined;
      cur = (cur as Record<string, unknown>)[token];
    }
  }

  // Path is known to exist and the document is a non-null object here,
  // so delegate the actual resolution to the library.
  return lib.get(doc, pointer);
}

export function solve(name: string): boolean {
  if (typeof name !== 'string') return false;

  // Whole name at most 253 characters
  if (name.length > 253) return false;

  // No trailing dot
  if (name.endsWith('.')) return false;

  // Heavy lifting: structure, underscores, lengths, hyphens, TLD basics
  if (!lib.isFQDN(name)) return false;

  const labels = name.split('.');

  // At least two labels
  if (labels.length < 2) return false;

  // Each label: 1-63 chars, letters/digits/hyphens only, no leading/trailing hyphen
  for (const label of labels) {
    if (label.length < 1 || label.length > 63) return false;
    if (!/^[\p{L}\p{Nd}-]+$/u.test(label)) return false;
    if (label.startsWith('-') || label.endsWith('-')) return false;
  }

  // TLD: either all letters (at least 2) or a punycode label starting with xn--
  const tld = labels[labels.length - 1];
  const isPunycode = /^xn--[a-z0-9-]*$/i.test(tld);
  const isAlphaTld = /^\p{L}{2,}$/u.test(tld);
  if (!isPunycode && !isAlphaTld) return false;

  return true;
}

const URL_PATTERN =
  /^https?:\/\/((?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63})(?::(\d{1,5}))?(?:[/?#]\S*)?$/i;

export function solve(urls: string[]): string[] {
  return urls.filter((url) => {
    const match = URL_PATTERN.exec(url);
    if (!match) return false;
    const port = match[2];
    if (port !== undefined && Number(port) > 65535) return false;
    return true;
  });
}

export function solve<T>(value: T): T {
  const memo = new Map<object, unknown>();

  function copyOwnProperties(source: object, target: object): void {
    for (const key of Reflect.ownKeys(source)) {
      const desc = Object.getOwnPropertyDescriptor(source, key);
      if (!desc || !desc.enumerable) continue;
      if ("value" in desc) {
        Object.defineProperty(target, key, {
          value: clone(desc.value),
          writable: desc.writable,
          enumerable: true,
          configurable: desc.configurable,
        });
      } else {
        // Accessor properties: copy the descriptor as-is.
        Object.defineProperty(target, key, desc);
      }
    }
  }

  function clone(input: unknown): unknown {
    // Primitives and functions are returned unchanged.
    if (input === null || typeof input !== "object") {
      return input;
    }

    // Circular or repeated reference: return the already-created copy.
    if (memo.has(input)) {
      return memo.get(input);
    }

    if (Array.isArray(input)) {
      const out: unknown[] = new Array(input.length);
      memo.set(input, out);
      copyOwnProperties(input, out);
      return out;
    }

    if (input instanceof Date) {
      const out = new Date(input.getTime());
      memo.set(input, out);
      return out;
    }

    if (input instanceof RegExp) {
      const out = new RegExp(input.source, input.flags);
      out.lastIndex = input.lastIndex;
      memo.set(input, out);
      return out;
    }

    if (input instanceof Map) {
      const out = new Map<unknown, unknown>();
      memo.set(input, out);
      input.forEach((v, k) => {
        out.set(clone(k), clone(v));
      });
      return out;
    }

    if (input instanceof Set) {
      const out = new Set<unknown>();
      memo.set(input, out);
      input.forEach((v) => {
        out.add(clone(v));
      });
      return out;
    }

    if (input instanceof ArrayBuffer) {
      const out = input.slice(0);
      memo.set(input, out);
      return out;
    }

    if (ArrayBuffer.isView(input)) {
      const buffer = clone(input.buffer) as ArrayBuffer;
      let out: object;
      if (input instanceof DataView) {
        out = new DataView(buffer, input.byteOffset, input.byteLength);
      } else {
        const Ctor = (input as unknown as { constructor: new (
          buffer: ArrayBufferLike,
          byteOffset: number,
          length: number
        ) => object }).constructor;
        out = new Ctor(
          buffer,
          (input as unknown as { byteOffset: number }).byteOffset,
          (input as unknown as { length: number }).length
        );
      }
      memo.set(input, out);
      return out;
    }

    // Plain objects and other ordinary objects: keep the prototype,
    // copy own enumerable string and symbol keyed properties.
    const out = Object.create(Object.getPrototypeOf(input)) as object;
    memo.set(input, out);
    copyOwnProperties(input, out);
    return out;
  }

  return clone(value) as T;
}

type Key = string | number;

function isIndex(k: Key): boolean {
  if (typeof k === "number") return Number.isInteger(k) && k >= 0;
  return /^(0|[1-9]\d*)$/.test(k);
}

function parsePath(path: string): Key[] {
  const keys: Key[] = [];
  const re = /\[(?:"([^"]*)"|'([^']*)'|([^\]]*))\]|[^.[\]]+/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(path)) !== null) {
    if (m[0].startsWith("[")) {
      keys.push(m[1] ?? m[2] ?? m[3] ?? "");
    } else {
      keys.push(m[0]);
    }
  }
  return keys;
}

export function solve(obj: object, updates: [string | (string | number)[], unknown][]): object {
  for (const [path, value] of updates) {
    const keys: Key[] = typeof path === "string" ? parsePath(path) : [...path];
    if (keys.length === 0) continue;

    let cur: any = obj;
    for (let i = 0; i < keys.length - 1; i++) {
      const k = keys[i];
      if (cur[k] === null || typeof cur[k] !== "object") {
        cur[k] = isIndex(keys[i + 1]) ? [] : {};
      }
      cur = cur[k];
    }
    cur[keys[keys.length - 1]] = value;
  }
  return obj;
}

export function solve(word: string, dictionary: string[]): string {
  if (dictionary.length === 0) {
    return "";
  }

  let best = dictionary[0];
  let bestDistance = levenshtein(word, best);

  for (let i = 1; i < dictionary.length; i++) {
    const candidate = dictionary[i];
    const distance = levenshtein(word, candidate);
    if (distance < bestDistance) {
      bestDistance = distance;
      best = candidate;
    }
  }

  return best;
}

function levenshtein(a: string, b: string): number {
  const s = Array.from(a);
  const t = Array.from(b);

  if (s.length === 0) return t.length;
  if (t.length === 0) return s.length;

  let prev: number[] = [];
  for (let j = 0; j <= t.length; j++) {
    prev.push(j);
  }

  for (let i = 1; i <= s.length; i++) {
    const curr: number[] = [i];
    for (let j = 1; j <= t.length; j++) {
      const cost = s[i - 1] === t[j - 1] ? 0 : 1;
      curr[j] = Math.min(
        prev[j] + 1,        // deletion
        curr[j - 1] + 1,    // insertion
        prev[j - 1] + cost  // substitution (or match)
      );
    }
    prev = curr;
  }

  return prev[t.length];
}

const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function sextet(ch: string | undefined): number {
  if (ch === undefined || ch.length !== 1) {
    throw new Error("Invalid base64 character");
  }
  const idx = ALPHABET.indexOf(ch);
  if (idx < 0) {
    throw new Error(`Invalid base64 character: ${ch}`);
  }
  return idx;
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 length: must be a multiple of 4");
  }

  const out: number[] = [];

  for (let i = 0; i < text.length; i += 4) {
    const isLastGroup = i + 4 === text.length;
    const c0 = text[i];
    const c1 = text[i + 1];
    const c2 = text[i + 2];
    const c3 = text[i + 3];

    const pad2 = c2 === "=";
    const pad3 = c3 === "=";

    if ((pad2 || pad3) && !isLastGroup) {
      throw new Error("Padding '=' only allowed at end of input");
    }
    if (pad2 && !pad3) {
      throw new Error("Invalid base64 padding");
    }

    const v0 = sextet(c0);
    const v1 = sextet(c1);
    const v2 = pad2 ? 0 : sextet(c2);
    const v3 = pad3 ? 0 : sextet(c3);

    const n = (v0 << 18) | (v1 << 12) | (v2 << 6) | v3;

    out.push((n >> 16) & 0xff);
    if (!pad2) out.push((n >> 8) & 0xff);
    if (!pad3) out.push(n & 0xff);
  }

  return out;
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  const known = new Set<string>(nodes);
  const unique: string[] = [];
  const indegree = new Map<string, number>();
  const adjacency = new Map<string, string[]>();

  for (const node of nodes) {
    if (!indegree.has(node)) {
      indegree.set(node, 0);
      adjacency.set(node, []);
      unique.push(node);
    }
  }

  for (const [from, to] of edges) {
    if (!known.has(from)) {
      throw new Error(`Unknown node in edge: ${from}`);
    }
    if (!known.has(to)) {
      throw new Error(`Unknown node in edge: ${to}`);
    }
    adjacency.get(from)!.push(to);
    indegree.set(to, indegree.get(to)! + 1);
  }

  const queue: string[] = unique.filter((node) => indegree.get(node) === 0);
  const result: string[] = [];

  for (let i = 0; i < queue.length; i++) {
    const node = queue[i];
    result.push(node);
    for (const next of adjacency.get(node)!) {
      const remaining = indegree.get(next)! - 1;
      indegree.set(next, remaining);
      if (remaining === 0) {
        queue.push(next);
      }
    }
  }

  if (result.length !== unique.length) {
    throw new Error("Cycle detected in edges");
  }

  return result;
}

export function solve(epochMs: number): string {
  if (!Number.isFinite(epochMs)) {
    throw new RangeError("epochMs must be a finite number");
  }
  // Floor to whole seconds first so negative and fractional inputs truncate toward the earlier instant.
  const wholeSecondMs = Math.floor(epochMs / 1000) * 1000;
  // toISOString always emits milliseconds and a trailing "Z" (UTC); drop the ".000" part.
  return new Date(wholeSecondMs).toISOString().replace(/\.\d{3}Z$/, "Z");
}

export function solve(text: string): string {
  // Step 1: UTF-8 encode the input manually (no TextEncoder / Buffer).
  const bytes: number[] = [];
  for (let i = 0; i < text.length; i++) {
    let c = text.charCodeAt(i);
    // Combine surrogate pairs into a single code point.
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < text.length) {
      const d = text.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) {
        c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00);
        i++;
      }
    }
    // Lone surrogates are replaced with U+FFFD.
    if (c >= 0xd800 && c <= 0xdfff) {
      c = 0xfffd;
    }
    if (c < 0x80) {
      bytes.push(c);
    } else if (c < 0x800) {
      bytes.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
    } else if (c < 0x10000) {
      bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
    } else {
      bytes.push(
        0xf0 | (c >> 18),
        0x80 | ((c >> 12) & 0x3f),
        0x80 | ((c >> 6) & 0x3f),
        0x80 | (c & 0x3f)
      );
    }
  }

  // Step 2: Padding (RFC 1321 section 3.1 and 3.2).
  const origLen = bytes.length;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) {
    bytes.push(0);
  }
  // Message length in bits, 64-bit little-endian.
  const bitLenLo = (origLen * 8) >>> 0;
  const bitLenHi = Math.floor(origLen / 0x20000000) >>> 0;
  for (let j = 0; j < 4; j++) bytes.push((bitLenLo >>> (8 * j)) & 0xff);
  for (let j = 0; j < 4; j++) bytes.push((bitLenHi >>> (8 * j)) & 0xff);

  // Step 3: Constants.
  const K: number[] = [
    0xd76aa478, 0xe8c7b756, 0x242070db, 0xc1bdceee,
    0xf57c0faf, 0x4787c62a, 0xa8304613, 0xfd469501,
    0x698098d8, 0x8b44f7af, 0xffff5bb1, 0x895cd7be,
    0x6b901122, 0xfd987193, 0xa679438e, 0x49b40821,
    0xf61e2562, 0xc040b340, 0x265e5a51, 0xe9b6c7aa,
    0xd62f105d, 0x02441453, 0xd8a1e681, 0xe7d3fbc8,
    0x21e1cde6, 0xc33707d6, 0xf4d50d87, 0x455a14ed,
    0xa9e3e905, 0xfcefa3f8, 0x676f02d9, 0x8d2a4c8a,
    0xfffa3942, 0x8771f681, 0x6d9d6122, 0xfde5380c,
    0xa4beea44, 0x4bdecfa9, 0xf6bb4b60, 0xbebfbc70,
    0x289b7ec6, 0xeaa127fa, 0xd4ef3085, 0x04881d05,
    0xd9d4d039, 0xe6db99e5, 0x1fa27cf8, 0xc4ac5665,
    0xf4292244, 0x432aff97, 0xab9423a7, 0xfc93a039,
    0x655b59c3, 0x8f0ccc92, 0xffeff47d, 0x85845dd1,
    0x6fa87e4f, 0xfe2ce6e0, 0xa3014314, 0x4e0811a1,
    0xf7537e82, 0xbd3af235, 0x2ad7d2bb, 0xeb86d391,
  ];

  const S: number[] = [
    7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
    5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
    4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
    6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
  ];

  // Step 4: Initial state.
  let a0 = 0x67452301;
  let b0 = 0xefcdab89;
  let c0 = 0x98badcfe;
  let d0 = 0x10325476;

  const M: number[] = new Array(16);

  // Step 5: Process each 512-bit block.
  for (let off = 0; off < bytes.length; off += 64) {
    for (let w = 0; w < 16; w++) {
      const p = off + w * 4;
      M[w] =
        bytes[p] |
        (bytes[p + 1] << 8) |
        (bytes[p + 2] << 16) |
        (bytes[p + 3] << 24);
    }

    let A = a0;
    let B = b0;
    let C = c0;
    let D = d0;

    for (let i = 0; i < 64; i++) {
      let F: number;
      let g: number;
      if (i < 16) {
        F = (B & C) | (~B & D);
        g = i;
      } else if (i < 32) {
        F = (B & D) | (C & ~D);
        g = (5 * i + 1) % 16;
      } else if (i < 48) {
        F = B ^ C ^ D;
        g = (3 * i + 5) % 16;
      } else {
        F = C ^ (B | ~D);
        g = (7 * i) % 16;
      }

      F = (F + A + K[i] + M[g]) | 0;
      A = D;
      D = C;
      C = B;
      const s = S[i];
      B = (B + ((F << s) | (F >>> (32 - s)))) | 0;
    }

    a0 = (a0 + A) | 0;
    b0 = (b0 + B) | 0;
    c0 = (c0 + C) | 0;
    d0 = (d0 + D) | 0;
  }

  // Step 6: Output digest as little-endian bytes in lowercase hex.
  const hex = "0123456789abcdef";
  let out = "";
  for (const word of [a0, b0, c0, d0]) {
    for (let j = 0; j < 4; j++) {
      const byte = (word >>> (8 * j)) & 0xff;
      out += hex[byte >>> 4] + hex[byte & 0x0f];
    }
  }
  return out;
}

export function solve(name: string, namespace: string): string {
  // Parse the namespace UUID into 16 bytes.
  const nsHex = namespace.replace(/-/g, "");
  if (!/^[0-9a-fA-F]{32}$/.test(nsHex)) {
    throw new Error("invalid namespace UUID");
  }
  const nsBytes: number[] = [];
  for (let i = 0; i < 32; i += 2) {
    nsBytes.push(parseInt(nsHex.slice(i, i + 2), 16));
  }

  // Manual UTF-8 encoding. Lone surrogates become U+FFFD, matching TextEncoder.
  const utf8Encode = (s: string): number[] => {
    const out: number[] = [];
    for (let i = 0; i < s.length; i++) {
      let cp = s.charCodeAt(i);
      if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < s.length) {
        const next = s.charCodeAt(i + 1);
        if (next >= 0xdc00 && next <= 0xdfff) {
          cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
          i++;
        } else {
          cp = 0xfffd;
        }
      } else if (cp >= 0xd800 && cp <= 0xdfff) {
        cp = 0xfffd;
      }
      if (cp < 0x80) {
        out.push(cp);
      } else if (cp < 0x800) {
        out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
      } else if (cp < 0x10000) {
        out.push(
          0xe0 | (cp >> 12),
          0x80 | ((cp >> 6) & 0x3f),
          0x80 | (cp & 0x3f)
        );
      } else {
        out.push(
          0xf0 | (cp >> 18),
          0x80 | ((cp >> 12) & 0x3f),
          0x80 | ((cp >> 6) & 0x3f),
          0x80 | (cp & 0x3f)
        );
      }
    }
    return out;
  };

  // SHA-1 implemented from the specification (FIPS 180-4).
  const sha1 = (data: number[]): number[] => {
    const h = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0];

    const msg = data.slice();
    const bitLen = data.length * 8;
    const bitLenLo = bitLen % 0x100000000;
    const bitLenHi = Math.floor(bitLen / 0x100000000);

    msg.push(0x80);
    while (msg.length % 64 !== 56) msg.push(0);
    msg.push(
      (bitLenHi >>> 24) & 0xff,
      (bitLenHi >>> 16) & 0xff,
      (bitLenHi >>> 8) & 0xff,
      bitLenHi & 0xff,
      (bitLenLo >>> 24) & 0xff,
      (bitLenLo >>> 16) & 0xff,
      (bitLenLo >>> 8) & 0xff,
      bitLenLo & 0xff
    );

    const w: number[] = new Array(80);
    for (let off = 0; off < msg.length; off += 64) {
      for (let t = 0; t < 16; t++) {
        const j = off + t * 4;
        w[t] =
          ((msg[j] << 24) | (msg[j + 1] << 16) | (msg[j + 2] << 8) | msg[j + 3]) >>> 0;
      }
      for (let t = 16; t < 80; t++) {
        const x = w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16];
        w[t] = ((x << 1) | (x >>> 31)) >>> 0;
      }

      let a = h[0];
      let b = h[1];
      let c = h[2];
      let d = h[3];
      let e = h[4];

      for (let t = 0; t < 80; t++) {
        let f: number;
        let k: number;
        if (t < 20) {
          f = (b & c) | (~b & d);
          k = 0x5a827999;
        } else if (t < 40) {
          f = b ^ c ^ d;
          k = 0x6ed9eba1;
        } else if (t < 60) {
          f = (b & c) | (b & d) | (c & d);
          k = 0x8f1bbcdc;
        } else {
          f = b ^ c ^ d;
          k = 0xca62c1d6;
        }
        const temp =
          (((a << 5) | (a >>> 27)) + (f >>> 0) + e + k + w[t]) >>> 0;
        e = d;
        d = c;
        c = ((b << 30) | (b >>> 2)) >>> 0;
        b = a;
        a = temp;
      }

      h[0] = (h[0] + a) >>> 0;
      h[1] = (h[1] + b) >>> 0;
      h[2] = (h[2] + c) >>> 0;
      h[3] = (h[3] + d) >>> 0;
      h[4] = (h[4] + e) >>> 0;
    }

    const digest: number[] = [];
    for (const x of h) {
      digest.push((x >>> 24) & 0xff, (x >>> 16) & 0xff, (x >>> 8) & 0xff, x & 0xff);
    }
    return digest;
  };

  // UUIDv5: SHA-1(namespace bytes || name bytes), truncated to 16 bytes.
  const digest = sha1(nsBytes.concat(utf8Encode(name)));
  const bytes = digest.slice(0, 16);

  // Set version (5) and RFC 4122 variant bits.
  bytes[6] = (bytes[6] & 0x0f) | 0x50;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;

  const hex = bytes.map((x) => x.toString(16).padStart(2, "0")).join("");
  return (
    hex.slice(0, 8) +
    "-" +
    hex.slice(8, 12) +
    "-" +
    hex.slice(12, 16) +
    "-" +
    hex.slice(16, 20) +
    "-" +
    hex.slice(20, 32)
  );
}

const DAY_MS = 86400000;
const HOUR_MS = 3600000;
const MINUTE_MS = 60000;

// date: YYYY-MM-DD | YYYY-Www-D | YYYY-DDD ; time: Thh[:mm[:ss[.f+]]] ; offset: Z | ±hh:mm (only with time)
const ISO_RE =
  /^(\d{4})(?:-(\d{2})-(\d{2})|-W(\d{2})-(\d)|-(\d{3}))(?:T(\d{2})(?::(\d{2})(?::(\d{2})(?:[.,](\d+))?)?)?(Z|[+-]\d{2}:\d{2})?)?$/;

function fail(input: unknown): never {
  throw new RangeError(`Invalid ISO 8601 date: ${JSON.stringify(input)}`);
}

function isLeapYear(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, month: number): number {
  if (month === 2) return isLeapYear(y) ? 29 : 28;
  return [4, 6, 9, 11].includes(month) ? 30 : 31;
}

// Builds epoch ms for a UTC date/time without the Date.UTC two-digit-year quirk.
function utcMs(y: number, monthIndex: number, day: number): number {
  const dt = new Date(0);
  dt.setUTCFullYear(y, monthIndex, day);
  dt.setUTCHours(0, 0, 0, 0);
  return dt.getTime();
}

function parseOne(input: string): number {
  if (typeof input !== "string") fail(input);

  const m = ISO_RE.exec(input);
  if (!m) fail(input);

  const g: (string | undefined)[] = [...m];
  const ys = g[1] as string;
  const mo = g[2];
  const d = g[3];
  const wk = g[4];
  const wd = g[5];
  const od = g[6];
  const hh = g[7];
  const mi = g[8];
  const ss = g[9];
  const frac = g[10];
  const off = g[11];

  const y = Number(ys);
  let base: number;

  if (mo !== undefined && d !== undefined) {
    // Calendar date
    const month = Number(mo);
    const day = Number(d);
    if (month < 1 || month > 12) fail(input);
    if (day < 1 || day > daysInMonth(y, month)) fail(input);
    base = utcMs(y, month - 1, day);
  } else if (wk !== undefined && wd !== undefined) {
    // ISO week date
    const week = Number(wk);
    const dow = Number(wd);
    if (week < 1 || week > 53) fail(input);
    if (dow < 1 || dow > 7) fail(input);

    // Week 1 is the week containing January 4th.
    const jan4 = utcMs(y, 0, 4);
    const jsDow = new Date(jan4).getUTCDay(); // 0 = Sunday
    const isoDow = jsDow === 0 ? 7 : jsDow; // 1 = Monday .. 7 = Sunday
    const week1Monday = jan4 - (isoDow - 1) * DAY_MS;

    const weekStart = week1Monday + (week - 1) * 7 * DAY_MS;
    // The week must belong to ISO week-year y (its Thursday must be in y).
    const thursday = weekStart + 3 * DAY_MS;
    if (new Date(thursday).getUTCFullYear() !== y) fail(input);

    base = weekStart + (dow - 1) * DAY_MS;
  } else {
    // Ordinal date
    const n = Number(od);
    const daysInYear = isLeapYear(y) ? 366 : 365;
    if (n < 1 || n > daysInYear) fail(input);
    base = utcMs(y, 0, 1) + (n - 1) * DAY_MS;
  }

  let t = base;

  if (hh !== undefined) {
    const h = Number(hh);
    const minute = mi !== undefined ? Number(mi) : 0;
    const second = ss !== undefined ? Number(ss) : 0;
    const fracDigits = frac ?? "";
    const msPart = fracDigits !== "" ? Number((fracDigits + "00").slice(0, 3)) : 0;

    if (minute > 59 || second > 59) fail(input);

    if (h === 24) {
      // ISO 8601 allows 24:00:00 to denote the end of the day.
      if (minute !== 0 || second !== 0 || !/^0*$/.test(fracDigits)) fail(input);
      t += DAY_MS;
    } else if (h > 23) {
      fail(input);
    } else {
      t += h * HOUR_MS;
    }

    t += minute * MINUTE_MS + second * 1000 + msPart;

    // Offset: absent or 'Z' means UTC.
    if (off !== undefined && off !== "Z") {
      const sign = off[0] === "-" ? -1 : 1;
      const oh = Number(off.slice(1, 3));
      const om = Number(off.slice(4, 6));
      if (oh > 23 || om > 59) fail(input);
      const offsetMs = sign * (oh * HOUR_MS + om * MINUTE_MS);
      t -= offsetMs;
    }
  }

  return t;
}

export function solve(stamps: string[]): number[] {
  return stamps.map(parseOne).sort((a, b) => a - b);
}

export function solve(text: string): string | null {
  // Leftmost run of 1-3 dot-separated digit groups (each 1-16 digits).
  // (?<!\d) prevents starting mid-number; (?!\d) prevents stopping mid-number,
  // so runs longer than 16 digits do not match. Anything after the third
  // number is ignored, and suffixes like "beta" or "+build" are not consumed.
  const m = /(?<!\d)(\d{1,16})(?:\.(\d{1,16}))?(?:\.(\d{1,16}))?(?!\d)/.exec(text);
  if (!m) return null;
  const major = m[1];
  const minor = m[2] ?? "0";
  const patch = m[3] ?? "0";
  return `${major}.${minor}.${patch}`;
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

interface ParsedVersion {
  raw: string;
  core: [string, string, string];
  pre: string | undefined;
}

function parseVersion(v: string): ParsedVersion {
  const main = v.split("+")[0];
  const dash = main.indexOf("-");
  const corePart = dash < 0 ? main : main.slice(0, dash);
  const pre = dash < 0 ? undefined : main.slice(dash + 1);
  const parts = corePart.split(".");
  return { raw: v, core: [parts[0], parts[1], parts[2]], pre };
}

// Numeric identifiers in valid semver have no leading zeros,
// so comparing by length and then lexically is exact.
function compareNumericStrings(a: string, b: string): number {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

function compareAsciiStrings(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

function comparePrerelease(pa: string | undefined, pb: string | undefined): number {
  if (pa === undefined && pb === undefined) return 0;
  if (pa === undefined) return 1; // release has higher precedence than prerelease
  if (pb === undefined) return -1;

  const A = pa.split(".");
  const B = pb.split(".");
  const n = Math.min(A.length, B.length);
  for (let i = 0; i < n; i++) {
    const x = A[i];
    const y = B[i];
    const xNum = /^\d+$/.test(x);
    const yNum = /^\d+$/.test(y);
    let c: number;
    if (xNum && yNum) c = compareNumericStrings(x, y);
    else if (xNum) c = -1; // numeric lower than alphanumeric
    else if (yNum) c = 1;
    else c = compareAsciiStrings(x, y);
    if (c !== 0) return c;
  }
  if (A.length === B.length) return 0;
  return A.length < B.length ? -1 : 1;
}

export function solve(versions: string[]): string[] {
  const parsed = versions
    .filter((v) => SEMVER_RE.test(v))
    .map(parseVersion);

  parsed.sort((a, b) => {
    for (let i = 0; i < 3; i++) {
      const c = compareNumericStrings(a.core[i], b.core[i]);
      if (c !== 0) return c;
    }
    const p = comparePrerelease(a.pre, b.pre);
    if (p !== 0) return p;
    return compareAsciiStrings(a.raw, b.raw);
  });

  return parsed.map((p) => p.raw);
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*)?$/;

const PRE_ID_RE = /^(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)$/;

const NUMERIC_RE = /^\d+$/;

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  const m = SEMVER_RE.exec(version);
  if (!m) return null;

  if (id !== undefined && !PRE_ID_RE.test(id)) return null;

  let major = Number(m[1]);
  let minor = Number(m[2]);
  let patch = Number(m[3]);
  let pre: string[] = m[4] !== undefined ? m[4].split('.') : [];
  const hasPre = pre.length > 0;

  // Fresh prerelease for pre* kinds: "<id>.0" or "0".
  const freshPre = (): string[] => (id !== undefined ? [id, '0'] : ['0']);

  // Increment an existing prerelease (used by `prerelease` on a prerelease).
  const bumpPre = (): string[] => {
    if (id !== undefined && !(pre.length > 0 && pre[0] === id)) {
      return [id, '0'];
    }
    const out = [...pre];
    for (let i = out.length - 1; i >= 0; i--) {
      if (NUMERIC_RE.test(out[i])) {
        out[i] = String(Number(out[i]) + 1);
        return out;
      }
    }
    out.push('0');
    return out;
  };

  switch (kind) {
    case 'major':
      // A prerelease whose lower parts are all zero is released in place.
      if (minor !== 0 || patch !== 0 || !hasPre) major++;
      minor = 0;
      patch = 0;
      pre = [];
      break;

    case 'minor':
      if (patch !== 0 || !hasPre) minor++;
      patch = 0;
      pre = [];
      break;

    case 'patch':
      // A prerelease is released in place by patch.
      if (!hasPre) patch++;
      pre = [];
      break;

    case 'premajor':
      major++;
      minor = 0;
      patch = 0;
      pre = freshPre();
      break;

    case 'preminor':
      minor++;
      patch = 0;
      pre = freshPre();
      break;

    case 'prepatch':
      patch++;
      pre = freshPre();
      break;

    case 'prerelease':
      if (!hasPre) {
        patch++;
        pre = freshPre();
      } else {
        pre = bumpPre();
      }
      break;

    default:
      return null;
  }

  const core = `${major}.${minor}.${patch}`;
  return pre.length > 0 ? `${core}-${pre.join('.')}` : core;
}

export function solve(text: string): string {
  // UTF-8 encode the input manually (no TextEncoder, no imports).
  // Lone surrogates are replaced with U+FFFD, as TextEncoder does.
  const bytes: number[] = [];
  for (let i = 0; i < text.length; i++) {
    let c = text.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff) {
      const d = i + 1 < text.length ? text.charCodeAt(i + 1) : 0;
      if (d >= 0xdc00 && d <= 0xdfff) {
        c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00);
        i++;
      } else {
        c = 0xfffd;
      }
    } else if (c >= 0xdc00 && c <= 0xdfff) {
      c = 0xfffd;
    }

    if (c < 0x80) {
      bytes.push(c);
    } else if (c < 0x800) {
      bytes.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
    } else if (c < 0x10000) {
      bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
    } else {
      bytes.push(
        0xf0 | (c >> 18),
        0x80 | ((c >> 12) & 0x3f),
        0x80 | ((c >> 6) & 0x3f),
        0x80 | (c & 0x3f)
      );
    }
  }

  // Padding (FIPS 180-4 section 5.1.1)
  const msgLen = bytes.length;
  const bitLenLo = (msgLen * 8) % 0x100000000;
  const bitLenHi = Math.floor((msgLen * 8) / 0x100000000);

  bytes.push(0x80);
  while (bytes.length % 64 !== 56) {
    bytes.push(0x00);
  }
  // 64-bit big-endian bit length
  bytes.push(
    (bitLenHi >>> 24) & 0xff, (bitLenHi >>> 16) & 0xff,
    (bitLenHi >>> 8) & 0xff, bitLenHi & 0xff,
    (bitLenLo >>> 24) & 0xff, (bitLenLo >>> 16) & 0xff,
    (bitLenLo >>> 8) & 0xff, bitLenLo & 0xff
  );

  const rotl = (x: number, n: number): number => ((x << n) | (x >>> (32 - n))) | 0;

  let h0 = 0x67452301 | 0;
  let h1 = 0xefcdab89 | 0;
  let h2 = 0x98badcfe | 0;
  let h3 = 0x10325476 | 0;
  let h4 = 0xc3d2e1f0 | 0;

  const w = new Array<number>(80);

  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const p = off + t * 4;
      w[t] = ((bytes[p] << 24) | (bytes[p + 1] << 16) | (bytes[p + 2] << 8) | bytes[p + 3]) | 0;
    }
    for (let t = 16; t < 80; t++) {
      w[t] = rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let t = 0; t < 80; t++) {
      let f: number;
      let k: number;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (rotl(a, 5) + f + e + k + w[t]) | 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) | 0;
    h1 = (h1 + b) | 0;
    h2 = (h2 + c) | 0;
    h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0;
  }

  const hex = (x: number): string => ('00000000' + (x >>> 0).toString(16)).slice(-8);
  return hex(h0) + hex(h1) + hex(h2) + hex(h3) + hex(h4);
}

type Parsed = { core: [string, string, string]; pre: string[] };

function parse(v: string): Parsed {
  const noBuild = v.split("+")[0];
  const dash = noBuild.indexOf("-");
  const corePart = dash === -1 ? noBuild : noBuild.slice(0, dash);
  const prePart = dash === -1 ? "" : noBuild.slice(dash + 1);
  const [major = "0", minor = "0", patch = "0"] = corePart.split(".");
  return {
    core: [major, minor, patch],
    pre: prePart === "" ? [] : prePart.split("."),
  };
}

// Compare non-negative integer strings without precision loss.
function cmpNum(x: string, y: string): number {
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  return x === y ? 0 : x < y ? -1 : 1;
}

function cmpId(x: string, y: string): number {
  const xn = /^\d+$/.test(x);
  const yn = /^\d+$/.test(y);
  if (xn && yn) return cmpNum(x, y);
  if (xn) return -1; // numeric identifiers have lower precedence
  if (yn) return 1;
  return x === y ? 0 : x < y ? -1 : 1;
}

function cmpPre(x: string[], y: string[]): number {
  if (x.length === 0 && y.length === 0) return 0;
  if (x.length === 0) return 1; // release > prerelease
  if (y.length === 0) return -1;
  const n = Math.min(x.length, y.length);
  for (let i = 0; i < n; i++) {
    const c = cmpId(x[i], y[i]);
    if (c !== 0) return c;
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1;
}

function cmpParsed(p: Parsed, q: Parsed): number {
  for (let i = 0; i < 3; i++) {
    const c = cmpNum(p.core[i], q.core[i]);
    if (c !== 0) return c;
  }
  return cmpPre(p.pre, q.pre);
}

export function solve(a: string, b: string): string | null {
  const pa = parse(a);
  const pb = parse(b);
  const c = cmpParsed(pa, pb);
  if (c === 0) return null;

  const lower = c < 0 ? pa : pb;
  const higher = c < 0 ? pb : pa;
  const lowerPre = lower.pre.length > 0;
  const higherPre = higher.pre.length > 0;

  // Highest differing core part (major > minor > patch), or undefined if cores are equal.
  const kinds = ["major", "minor", "patch"] as const;
  const idx = [0, 1, 2].find((k) => cmpNum(lower.core[k], higher.core[k]) !== 0);
  const part = idx === undefined ? undefined : kinds[idx];

  if (!higherPre) {
    // Higher is a release.
    if (!lowerPre) {
      // Both releases: plain highest differing part.
      return part ?? null; // part is always defined here since versions differ
    }
    // Lower is a prerelease, higher is a release.
    if (part === undefined) {
      // Cores equal: the release of a prerelease is classified by the lower's core.
      if (lower.core[1] === "0" && lower.core[2] === "0") return "major";
      if (lower.core[2] === "0") return "minor";
      return "patch";
    }
    // Only major changed with lower minor/patch at 0 yields "major", which is
    // exactly the highest differing part, so the highest differing part applies.
    return part;
  }

  // Higher is a prerelease.
  if (part === undefined) return "prerelease";
  return "pre" + part;
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  const s = isbn.replace(/[ -]/g, "");

  const isValid10 = (): boolean => {
    // Nine digits followed by a digit or an upper-case 'X' (only allowed as the final character).
    if (!/^[0-9]{9}[0-9X]$/.test(s)) return false;
    let sum = 0;
    for (let i = 0; i < 10; i++) {
      const c = s[i];
      const d = c === "X" ? 10 : c.charCodeAt(0) - 48;
      sum += (10 - i) * d;
    }
    return sum % 11 === 0;
  };

  const isValid13 = (): boolean => {
    if (!/^[0-9]{13}$/.test(s)) return false;
    let sum = 0;
    for (let i = 0; i < 13; i++) {
      const d = s.charCodeAt(i) - 48;
      sum += i % 2 === 0 ? d : 3 * d;
    }
    return sum % 10 === 0;
  };

  if (version === 10) return isValid10();
  if (version === 13) return isValid13();
  return isValid10() || isValid13();
}

export function solve(name: string, namespace: string): string {
  const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
  if (typeof namespace !== "string" || !UUID_RE.test(namespace)) {
    throw new TypeError("namespace is not a valid UUID");
  }

  // Parse namespace UUID into 16 bytes.
  const hex = namespace.replace(/-/g, "");
  const nsBytes: number[] = [];
  for (let i = 0; i < 32; i += 2) {
    nsBytes.push(parseInt(hex.slice(i, i + 2), 16));
  }

  // UTF-8 encode the name (lone surrogates become U+FFFD, as TextEncoder does).
  const nameBytes: number[] = [];
  for (const ch of name) {
    let cp = ch.codePointAt(0) as number;
    if (cp >= 0xd800 && cp <= 0xdfff) cp = 0xfffd;
    if (cp < 0x80) {
      nameBytes.push(cp);
    } else if (cp < 0x800) {
      nameBytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      nameBytes.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      nameBytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  const message = new Uint8Array(nsBytes.length + nameBytes.length);
  message.set(nsBytes, 0);
  message.set(nameBytes, nsBytes.length);

  const digest = md5(message);

  // Set version (3) and variant (RFC 4122).
  const b = Array.from(digest);
  b[6] = (b[6] & 0x0f) | 0x30;
  b[8] = (b[8] & 0x3f) | 0x80;

  const h = b.map((x) => (x < 16 ? "0" : "") + x.toString(16)).join("");
  return (
    h.slice(0, 8) + "-" +
    h.slice(8, 12) + "-" +
    h.slice(12, 16) + "-" +
    h.slice(16, 20) + "-" +
    h.slice(20, 32)
  );
}

function md5(msg: Uint8Array): Uint8Array {
  const S = [
    7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
    5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
    4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
    6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
  ];

  const K: number[] = [];
  for (let i = 0; i < 64; i++) {
    K.push(Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296) >>> 0);
  }

  // Padding: 0x80, zeros, then 64-bit little-endian bit length.
  const len = msg.length;
  const total = (Math.floor((len + 8) / 64) + 1) * 64;
  const buf = new Uint8Array(total);
  buf.set(msg, 0);
  buf[len] = 0x80;
  const bitLen = len * 8;
  const lo = bitLen % 4294967296;
  const hi = Math.floor(bitLen / 4294967296);
  for (let i = 0; i < 4; i++) {
    buf[total - 8 + i] = (lo >>> (8 * i)) & 0xff;
    buf[total - 4 + i] = (hi >>> (8 * i)) & 0xff;
  }

  let a0 = 0x67452301;
  let b0 = 0xefcdab89;
  let c0 = 0x98badcfe;
  let d0 = 0x10325476;

  const M: number[] = new Array<number>(16);

  for (let off = 0; off < total; off += 64) {
    for (let j = 0; j < 16; j++) {
      const p = off + 4 * j;
      M[j] = (buf[p] | (buf[p + 1] << 8) | (buf[p + 2] << 16) | (buf[p + 3] << 24)) >>> 0;
    }

    let A = a0;
    let B = b0;
    let C = c0;
    let D = d0;

    for (let i = 0; i < 64; i++) {
      let F: number;
      let g: number;
      if (i < 16) {
        F = (B & C) | (~B & D);
        g = i;
      } else if (i < 32) {
        F = (D & B) | (~D & C);
        g = (5 * i + 1) & 15;
      } else if (i < 48) {
        F = B ^ C ^ D;
        g = (3 * i + 5) & 15;
      } else {
        F = C ^ (B | ~D);
        g = (7 * i) & 15;
      }
      F = (F + A + K[i] + M[g]) >>> 0;
      A = D;
      D = C;
      C = B;
      B = (B + (((F << S[i]) | (F >>> (32 - S[i]))) >>> 0)) >>> 0;
    }

    a0 = (a0 + A) >>> 0;
    b0 = (b0 + B) >>> 0;
    c0 = (c0 + C) >>> 0;
    d0 = (d0 + D) >>> 0;
  }

  const out = new Uint8Array(16);
  const words = [a0, b0, c0, d0];
  for (let w = 0; w < 4; w++) {
    for (let i = 0; i < 4; i++) {
      out[w * 4 + i] = (words[w] >>> (8 * i)) & 0xff;
    }
  }
  return out;
}

type Rule = {
  matches: (d: string) => boolean;
  lengths: readonly number[];
};

const range = (min: number, max: number): number[] =>
  Array.from({ length: max - min + 1 }, (_, i) => min + i);

// True if the leading `n` digits of `d` form a number within [lo, hi].
const prefixInRange = (d: string, n: number, lo: number, hi: number): boolean => {
  if (d.length < n) return false;
  const p = Number(d.slice(0, n));
  return p >= lo && p <= hi;
};

const RULES: readonly Rule[] = [
  // Visa
  { matches: (d) => d.startsWith("4"), lengths: [13, 16, 19] },
  // Mastercard
  {
    matches: (d) => prefixInRange(d, 2, 51, 55) || prefixInRange(d, 4, 2221, 2720),
    lengths: [16],
  },
  // American Express
  { matches: (d) => d.startsWith("34") || d.startsWith("37"), lengths: [15] },
  // Discover
  {
    matches: (d) =>
      d.startsWith("6011") ||
      prefixInRange(d, 6, 622126, 622925) ||
      prefixInRange(d, 3, 644, 649) ||
      d.startsWith("65"),
    lengths: [16, 19],
  },
  // Diners Club
  {
    matches: (d) =>
      prefixInRange(d, 3, 300, 305) || d.startsWith("36") || d.startsWith("38"),
    lengths: range(14, 19),
  },
  // JCB
  { matches: (d) => prefixInRange(d, 4, 3528, 3589), lengths: range(16, 19) },
  // UnionPay
  { matches: (d) => d.startsWith("62"), lengths: range(16, 19) },
];

const luhnValid = (digits: string): boolean => {
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = digits.charCodeAt(i) - 48;
    if (double) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    double = !double;
  }
  return sum % 10 === 0;
};

export function solve(card: string): boolean {
  const digits = card.replace(/[\s-]/g, "");
  if (!/^\d+$/.test(digits)) return false;

  const issuerMatch = RULES.some(
    (rule) => rule.matches(digits) && rule.lengths.includes(digits.length)
  );
  if (!issuerMatch) return false;

  return luhnValid(digits);
}

export function solve(isin: string): boolean {
  if (typeof isin !== "string") return false;

  // Two uppercase letters, nine uppercase alphanumerics, one digit check character.
  if (!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) return false;

  // Convert letters to numbers (A=10 ... Z=35), keeping digits as they are.
  let digits = "";
  for (let i = 0; i < isin.length; i++) {
    const c = isin.charCodeAt(i);
    if (c >= 65 && c <= 90) {
      // 'A' is 65, so 'A' -> 10 requires subtracting 55.
      digits += String(c - 55);
    } else {
      digits += isin[i];
    }
  }

  // Luhn check over the full digit string (including the check digit).
  let sum = 0;
  let doubleIt = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48;
    if (doubleIt) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    doubleIt = !doubleIt;
  }

  return sum % 10 === 0;
}

const HEX_GROUP = /^[0-9A-Fa-f]{1,4}$/;
const DECIMAL_OCTET = /^(0|[1-9][0-9]{0,2})$/;
const ZONE_ID = /^[A-Za-z0-9]+$/;

function isIPv4(s: string): boolean {
  const parts = s.split(".");
  if (parts.length !== 4) return false;
  return parts.every((p) => DECIMAL_OCTET.test(p) && Number(p) <= 255);
}

function isIPv6(text: string): boolean {
  let addr = text;
  let zone: string | null = null;

  // Split off an optional zone index.
  const pct = text.indexOf("%");
  if (pct !== -1) {
    addr = text.slice(0, pct);
    zone = text.slice(pct + 1);
    if (!ZONE_ID.test(zone)) return false;
  }

  // Replace an optional trailing dotted IPv4 with two hex groups.
  if (addr.includes(".")) {
    const lastColon = addr.lastIndexOf(":");
    const v4Tail = addr.slice(lastColon + 1);
    if (!isIPv4(v4Tail)) return false;
    addr = addr.slice(0, lastColon + 1) + "0:0";
  }

  // At most one "::" is allowed.
  if (addr.indexOf("::") !== addr.lastIndexOf("::")) return false;

  if (addr.includes("::")) {
    const parts = addr.split("::");
    const head = parts[0] ?? "";
    const tail = parts[1] ?? "";
    const groups = [
      ...(head === "" ? [] : head.split(":")),
      ...(tail === "" ? [] : tail.split(":")),
    ];
    if (!groups.every((g) => HEX_GROUP.test(g))) return false;
    // "::" must stand for at least one zero group.
    if (groups.length > 7) return false;
  } else {
    const groups = addr.split(":");
    if (groups.length !== 8) return false;
    if (!groups.every((g) => HEX_GROUP.test(g))) return false;
  }

  // A zone index is only valid on link-local addresses (fe80::/10).
  if (zone !== null) {
    const first = addr.startsWith("::") ? 0 : parseInt(addr.split(":")[0], 16);
    if ((first & 0xffc0) !== 0xfe80) return false;
  }

  return true;
}

export function solve(text: string, version?: 4 | 6): boolean {
  if (version === undefined || version === 4) {
    if (isIPv4(text)) return true;
  }
  if (version === undefined || version === 6) {
    if (isIPv6(text)) return true;
  }
  return false;
}

