const bbanRegexCache = new Map<string, RegExp>();

function bbanRegex(structure: string): RegExp {
  let re = bbanRegexCache.get(structure);
  if (re === undefined) {
    let src = "^";
    const part = /(\d+)!([nac])/g;
    let m: RegExpExecArray | null;
    while ((m = part.exec(structure)) !== null) {
      const count = Number(m[1]);
      const cls = m[2] === "n" ? "0-9" : m[2] === "a" ? "A-Z" : "A-Z0-9";
      src += `[${cls}]{${count}}`;
    }
    src += "$";
    re = new RegExp(src);
    bbanRegexCache.set(structure, re);
  }
  return re;
}

// Computes (number mod 97) for a string of digits and uppercase letters (A=10..Z=35),
// processing one character at a time so no big-integer arithmetic is needed.
function mod97(s: string): number {
  let r = 0;
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code >= 48 && code <= 57) {
      // digit
      r = (r * 10 + (code - 48)) % 97;
    } else {
      // letter: value 10..35 occupies two decimal digits
      const v = code - 55; // 'A' (65) -> 10
      r = (r * 100 + v) % 97;
    }
  }
  return r;
}

export function solve(iban: string): boolean {
  if (typeof iban !== "string") return false;

  // Only ASCII letters, digits, spaces and hyphens are permitted in the raw input.
  if (!/^[A-Za-z0-9 -]*$/.test(iban)) return false;

  // Ignore spaces and hyphens; letters may be any case.
  const s = iban.replace(/[ -]/g, "").toUpperCase();

  // Structure: 2 letters (country), 2 digits (check), then alphanumeric BBAN.
  if (!/^[A-Z]{2}[0-9]{2}[A-Z0-9]+$/.test(s)) return false;

  const entry = REGISTRY.get(s.slice(0, 2));
  if (entry === undefined) return false;

  const [expectedLength, structure] = entry;
  if (s.length !== expectedLength) return false;

  const bban = s.slice(4);
  if (!bbanRegex(structure).test(bban)) return false;

  // Move the first four characters to the end and check mod 97 === 1.
  const rearranged = s.slice(4) + s.slice(0, 4);
  return mod97(rearranged) === 1;
}

export function solve(issn: string): boolean {
  if (typeof issn !== "string") return false;
  if (!/^\d{4}-?\d{3}[\dXx]$/.test(issn)) return false;

  const s = issn.replace("-", "");
  let sum = 0;
  for (let i = 0; i < 7; i++) {
    sum += (8 - i) * (s.charCodeAt(i) - 48);
  }

  const last = s[7];
  const check = last === "X" || last === "x" ? 10 : last.charCodeAt(0) - 48;
  sum += check;

  return sum % 11 === 0;
}

export function solve(text: string): boolean {
  const COORD = /^([+-]?)(\d+)(?:\.(\d+))?$/;

  const within = (s: string, max: number): boolean => {
    const m = COORD.exec(s);
    if (!m) return false;
    const magnitude = Number(m[2] + (m[3] !== undefined ? "." + m[3] : ""));
    return Number.isFinite(magnitude) && magnitude <= max;
  };

  let inner = text;
  if (inner.length >= 2 && inner[0] === "(" && inner[inner.length - 1] === ")") {
    inner = inner.slice(1, -1);
  }

  const parts = inner.split(",");
  if (parts.length !== 2) return false;

  const latPart = parts[0];
  const lonPart = parts[1].replace(/^ +/, "");

  return within(latPart, 90) && within(lonPart, 180);
}

export function solve(a: string, b: string): number {
  // Keep b as the shorter string to minimize memory (distance is symmetric).
  if (a.length < b.length) {
    const tmp = a;
    a = b;
    b = tmp;
  }

  const n = b.length;
  let prev = new Int32Array(n + 1);
  let cur = new Int32Array(n + 1);

  for (let j = 0; j <= n; j++) {
    prev[j] = j;
  }

  for (let i = 1; i <= a.length; i++) {
    cur[0] = i;
    const ca = a.charCodeAt(i - 1);
    for (let j = 1; j <= n; j++) {
      const cost = ca === b.charCodeAt(j - 1) ? 0 : 1;
      const deletion = prev[j] + 1;
      const insertion = cur[j - 1] + 1;
      const substitution = prev[j - 1] + cost;
      let best = deletion < insertion ? deletion : insertion;
      if (substitution < best) best = substitution;
      cur[j] = best;
    }
    const swap = prev;
    prev = cur;
    cur = swap;
  }

  return prev[n];
}

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === "") {
    return doc;
  }
  if (!pointer.startsWith("/")) {
    throw new Error(`Invalid JSON Pointer: must be empty or start with "/": ${JSON.stringify(pointer)}`);
  }

  const tokens = pointer.slice(1).split("/");
  let current: unknown = doc;

  for (const raw of tokens) {
    // RFC 6901: decode ~1 to "/" first, then ~0 to "~".
    const token = raw.replace(/~1/g, "/").replace(/~0/g, "~");

    if (Array.isArray(current)) {
      // Array index: "0" or a non-zero-leading digit sequence. "-" never resolves.
      if (!/^(0|[1-9][0-9]*)$/.test(token)) {
        return undefined;
      }
      const index = Number(token);
      if (index >= current.length) {
        return undefined;
      }
      current = current[index];
    } else if (typeof current === "object" && current !== null) {
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        return undefined;
      }
      current = (current as Record<string, unknown>)[token];
    } else {
      // Primitive or null: cannot descend further.
      return undefined;
    }
  }

  return current;
}

export function solve(name: string): boolean {
  if (typeof name !== 'string') return false;
  if (name.length === 0 || name.length > 253) return false;

  const labels = name.split('.');
  if (labels.length < 2) return false;

  // Ordinary label: 1-63 ASCII letters/digits/hyphens, no leading or trailing hyphen.
  const labelRe = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/;

  for (let i = 0; i < labels.length - 1; i++) {
    if (!labelRe.test(labels[i])) return false;
  }

  const tld = labels[labels.length - 1];
  if (tld.length < 2 || tld.length > 63) return false;

  // TLD option 1: all letters (international letters allowed), at least two characters.
  const isLetterTld = /^\p{L}{2,}$/u.test(tld);

  // TLD option 2: punycode label starting with "xn--", obeying the ordinary label rules.
  const isPunycodeTld = /^xn--/i.test(tld) && labelRe.test(tld);

  return isLetterTld || isPunycodeTld;
}

