 *
 * `cutoff` is a pruning hint. If the true distance is known to be >= `cutoff`,
 * the function may return early with some value >= `cutoff`; otherwise it
 * returns the exact distance.
 */
function levenshtein(a: string[], b: string[], cutoff: number): number {
  const [longer, shorter] = a.length >= b.length ? [a, b] : [b, a];
  const n = shorter.length;
  if (n === 0) return longer.length;

  // prev[j] = distance between the processed prefix of `longer` and shorter[0..j)
  let prev: number[] = Array.from({ length: n + 1 }, (_, j) => j);
  let curr: number[] = new Array<number>(n + 1);

  for (let i = 1; i <= longer.length; i++) {
    curr[0] = i;
    let rowMin = i;

    for (let j = 1; j <= n; j++) {
      const cost = longer[i - 1] === shorter[j - 1] ? 0 : 1;
      const value = Math.min(
        prev[j] + 1,        // deletion
        curr[j - 1] + 1,    // insertion
        prev[j - 1] + cost, // substitution or match
      );
      curr[j] = value;
      if (value < rowMin) rowMin = value;
    }

    // Any alignment must pass through this row, and costs never decrease along it,
    // so the final distance is at least rowMin.
    if (rowMin >= cutoff) return rowMin;

    [prev, curr] = [curr, prev];
  }

  return prev[n];
}

