    const fromId = index.get(from);
    const toId = index.get(to);
    if (fromId === undefined) {
      throw new Error(`Edge mentions unknown node "${from}" that is not in nodes`);
    }
    if (toId === undefined) {
      throw new Error(`Edge mentions unknown node "${to}" that is not in nodes`);
    }
    successors[fromId].push(toId);
    indegree[toId]++;
