    if (last !== undefined && ready.length > 0) {
      ready[0] = last;
      let i = 0;
      while (true) {
        const left = 2 * i + 1;
        const right = left + 1;
        let smallest = i;
        if (left < ready.length && ready[left] < ready[smallest]) smallest = left;
        if (right < ready.length && ready[right] < ready[smallest]) smallest = right;
        if (smallest === i) break;
