// Official SemVer 2.0.0 grammar. Groups: 1 = major, 2 = minor, 3 = patch, 4 = prerelease.
const SEMVER_PATTERN =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*)?$/;

const DIGITS = /^[0-9]+$/;

function parse(raw: string): ParsedVersion | null {
  const m = SEMVER_PATTERN.exec(raw);
  if (m === null) return null;
  return {
    raw,
    major: m[1] ?? "0",
    minor: m[2] ?? "0",
    patch: m[3] ?? "0",
    pre: m[4] ?? null,
  };
}

function cmpStr(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

// Canonical non-negative integers (no leading zeros): compare by length, then digits.
// Avoids precision loss for arbitrarily large numeric components.
function cmpNumeric(a: string, b: string): number {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  return cmpStr(a, b);
}

function cmpPreIdentifier(a: string, b: string): number {
  const aNum = DIGITS.test(a);
  const bNum = DIGITS.test(b);
  if (aNum && bNum) return cmpNumeric(a, b);
  if (aNum !== bNum) return aNum ? -1 : 1; // numeric identifiers rank below alphanumeric
  return cmpStr(a, b); // ASCII order
}

function cmpPrerelease(a: string, b: string): number {
  const ai = a.split(".");
  const bi = b.split(".");
  const n = Math.min(ai.length, bi.length);
  for (let i = 0; i < n; i++) {
    const c = cmpPreIdentifier(ai[i] ?? "", bi[i] ?? "");
    if (c !== 0) return c;
  }
  // All shared identifiers equal: the longer list has higher precedence.
  return ai.length < bi.length ? -1 : ai.length > bi.length ? 1 : 0;
}

// Build metadata is ignored here.
function cmpPrecedence(a: ParsedVersion, b: ParsedVersion): number {
  const core =
    cmpNumeric(a.major, b.major) ||
    cmpNumeric(a.minor, b.minor) ||
    cmpNumeric(a.patch, b.patch);
  if (core !== 0) return core;
  if (a.pre === null) return b.pre === null ? 0 : 1; // release > prerelease
  if (b.pre === null) return -1;
  return cmpPrerelease(a.pre, b.pre);
}

export function solve(versions: string[]): string[] {
  const parsed: ParsedVersion[] = [];
  for (const v of versions) {
    const p = parse(v);
    if (p !== null) parsed.push(p);
  }
  // Equal precedence: order by full version string, lexically.
  parsed.sort((a, b) => cmpPrecedence(a, b) || cmpStr(a.raw, b.raw));
  return parsed.map((p) => p.raw);
}

export function solve(isin: string): boolean {
