function isValidIsbn10(s: string): boolean {
  // Nine digits followed by a digit or an upper-case 'X' (which means 10).
  if (!/^\d{9}[\dX]$/.test(s)) return false;

  // Sum of (10 - i) * d[i] over 0-based positions i must be divisible by 11.
  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const d = s[i] === 'X' ? 10 : Number(s[i]);
    sum += (10 - i) * d;
  }
  return sum % 11 === 0;
}

function isValidIsbn13(s: string): boolean {
  if (!/^\d{13}$/.test(s)) return false;

  // EAN-13: weights 1,3,1,3,... over all 13 digits must be divisible by 10.
  let sum = 0;
  for (let i = 0; i < 13; i++) {
    sum += (i % 2 === 0 ? 1 : 3) * Number(s[i]);
  }
  return sum % 10 === 0;
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  if (typeof isbn !== 'string') return false;

  // Spaces (any whitespace) and hyphens are ignored.
  const s = isbn.replace(/[\s-]/g, '');

  if (version === undefined) return isValidIsbn10(s) || isValidIsbn13(s);
  if (version === 10) return isValidIsbn10(s);
  if (version === 13) return isValidIsbn13(s);
  return false;
}

