export function solve(code: string): boolean {
  if (!/^[0-9]+$/.test(code)) return false;

  const n = code.length;
  if (n !== 8 && n !== 13 && n !== 14) return false;

  const digit = (i: number): number => Number(code[i]);

  // Weights 3 and 1 alternate, starting at the rightmost data digit
  // (the one immediately left of the check digit).
  let sum = 0;
  let weight = 3;
  for (let i = n - 2; i >= 0; i--) {
    sum += digit(i) * weight;
    weight = weight === 3 ? 1 : 3;
  }

  const check = (10 - (sum % 10)) % 10;
  return check === digit(n - 1);
}

type Issuer = {
  /** Inclusive [low, high] prefix ranges; both bounds in a range have the same number of digits. */
  prefixes: ReadonlyArray<[string, string]>;
  /** Permitted total number of digits. */
  lengths: ReadonlyArray<number>;
};

const ISSUERS: ReadonlyArray<Issuer> = [
  // Visa: starts with 4; 13, 16 or 19 digits
  { prefixes: [["4", "4"]], lengths: [13, 16, 19] },

  // Mastercard: 51-55 or 2221-2720; 16 digits
  { prefixes: [["51", "55"], ["2221", "2720"]], lengths: [16] },

  // American Express: 34 or 37; 15 digits
  { prefixes: [["34", "34"], ["37", "37"]], lengths: [15] },

  // Discover: 6011, 622126-622925, 644-649, 65; 16 or 19 digits
  {
    prefixes: [["6011", "6011"], ["622126", "622925"], ["644", "649"], ["65", "65"]],
    lengths: [16, 19],
  },

  // Diners Club: 300-305, 36, 38; 14-19 digits
  { prefixes: [["300", "305"], ["36", "36"], ["38", "38"]], lengths: [14, 15, 16, 17, 18, 19] },

  // JCB: 3528-3589; 16-19 digits
  { prefixes: [["3528", "3589"]], lengths: [16, 17, 18, 19] },

  // UnionPay: 62; 16-19 digits
  { prefixes: [["62", "62"]], lengths: [16, 17, 18, 19] },
];

/** True if the leading digits of `digits` fall within the inclusive range [lo, hi]. */
function inPrefixRange(digits: string, [lo, hi]: [string, string]): boolean {
  const head = digits.slice(0, lo.length);
  // Equal-width digit strings order the same way lexicographically as numerically.
  return head.length === lo.length && head >= lo && head <= hi;
}

/** True if `digits` matches some issuer's prefix and length rules. */
function hasKnownIssuerFormat(digits: string): boolean {
  return ISSUERS.some(
    ({ prefixes, lengths }) =>
      lengths.indexOf(digits.length) !== -1 &&
      prefixes.some((range) => inPrefixRange(digits, range))
  );
}

/** Luhn (mod 10) checksum over a string of decimal digits. */
function passesLuhn(digits: string): boolean {
  let sum = 0;
  let shouldDouble = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = Number(digits.charAt(i));
    if (shouldDouble) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    shouldDouble = !shouldDouble;
  }
  return sum % 10 === 0;
}

export function solve(card: string): boolean {
  // Spaces and hyphens are ignored; every remaining character must be a digit.
  const digits = card.replace(/[ -]/g, "");
  return /^[0-9]+$/.test(digits) && hasKnownIssuerFormat(digits) && passesLuhn(digits);
}

export function solve(issn: string): boolean {
  if (typeof issn !== "string") return false;

  // Exactly "NNNN-NNNC" or "NNNNNNNC"; the check character is a digit or X/x.
  if (!/^\d{4}-?\d{3}[\dXx]$/.test(issn)) return false;

  // Remove the optional hyphen: seven digits followed by the check character.
  const s = issn.replace("-", "");

  // Weights (8 - i) for i = 0..6, i.e. 8, 7, 6, 5, 4, 3, 2 (ISO 3297).
  let sum = 0;
  for (let i = 0; i < 7; i++) {
    sum += (8 - i) * (s.charCodeAt(i) - 48); // '0' has char code 48
  }

  // The check character has weight 1; 'X' or 'x' stands for 10.
  const last = s.charAt(7);
  const check = last === "X" || last === "x" ? 10 : last.charCodeAt(0) - 48;

  return (sum + check) % 11 === 0;
}

const SEMVER_PATTERN =
  /^\s*v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?\s*$/;

export function solve(installed: string[], range: string): string | null {
  const valid = installed.filter(
    (v): v is string => typeof v === "string" && SEMVER_PATTERN.test(v)
  );
  return lib.maxSatisfying(valid, range);
}

export function solve(sub: string, sup: string): boolean {
  return lib.subset(sub, sup);
}

export function solve(a: string, b: string): number {
  // Make `t` the shorter string so the working rows stay as small as possible.
  let s = a;
  let t = b;
  if (s.length < t.length) {
    s = b;
    t = a;
  }

  const n = s.length;
  const m = t.length;
  if (m === 0) return n;

  // prev[j]: edit distance between the first i-1 code units of s and the first j of t.
  // curr[j]: the same for the first i code units of s.
  let prev: number[] = new Array<number>(m + 1);
  let curr: number[] = new Array<number>(m + 1);
  for (let j = 0; j <= m; j++) prev[j] = j;

  for (let i = 1; i <= n; i++) {
    const sc = s.charCodeAt(i - 1);
    curr[0] = i;
    for (let j = 1; j <= m; j++) {
      const cost = sc === t.charCodeAt(j - 1) ? 0 : 1;
      let best = prev[j - 1] + cost; // match or substitute
      const del = prev[j] + 1;       // delete s[i-1]
      const ins = curr[j - 1] + 1;   // insert t[j-1]
      if (del < best) best = del;
      if (ins < best) best = ins;
      curr[j] = best;
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[m];
}

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === "") {
    return doc;
  }
  if (pointer.charAt(0) !== "/") {
    throw new Error(`Invalid JSON Pointer "${pointer}": must be empty or start with "/"`);
  }

  // Split on literal "/" first; escaped slashes ("~1") are only decoded afterwards.
  const tokens = pointer.slice(1).split("/");

  let current: unknown = doc;

  for (const raw of tokens) {
    // Unescape in the mandated order: "~1" -> "/" first, then "~0" -> "~".
    const token = raw.replace(/~1/g, "/").replace(/~0/g, "~");

    if (Array.isArray(current)) {
      // Only "0" or a decimal without leading zeros is a valid index.
      // "-" and anything else does not reference an existing element.
      if (!/^(0|[1-9][0-9]*)$/.test(token)) {
        return undefined;
      }
      const index = Number(token);
      if (index >= current.length) {
        return undefined;
      }
      current = current[index];
    } else if (typeof current === "object" && current !== null) {
      // Only own properties count, so inherited names like "constructor" do not resolve.
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        return undefined;
      }
      current = (current as Record<string, unknown>)[token];
    } else {
      // Primitives and null have no members to step into.
      return undefined;
    }
  }

  return current;
}

export function solve(obj: object, updates: [string | (string | number)[], unknown][]): object {
  const isIdx = (k: string | number) => typeof k === "number" || /^\d+$/.test(String(k));
  for (const [path, value] of updates) {
    const keys: (string | number)[] = typeof path === "string"
      ? path.replace(/\[(\d+)\]/g, ".$1").split(".").filter((s) => s !== "")
      : path;
    if (keys.length === 0) continue;
    let cur: any = obj;
    for (let i = 0; i < keys.length - 1; i++) {
      const k = keys[i];
      if (typeof cur[k] !== "object" || cur[k] === null)
        cur[k] = isIdx(keys[i + 1]) ? [] : {};
      cur = cur[k];
    }
    cur[keys[keys.length - 1]] = value;
  }
  return obj;
}

export function solve(emails: string[]): string[] {
  const canon = (raw: string): string => {
    const s = raw.toLowerCase();
    const at = s.lastIndexOf('@');
    if (at < 0) return s;
    let local = s.slice(0, at);
    let domain = s.slice(at + 1);
    if (domain === 'gmail.com' || domain === 'googlemail.com') {
      local = local.split('+')[0].replace(/\./g, '');
      domain = 'gmail.com';
    } else if (['outlook.com', 'hotmail.com', 'live.com'].includes(domain)) {
      local = local.split('+')[0];
    }
    return `${local}@${domain}`;
  };
  return Array.from(new Set(emails.map(canon)));
}

export function solve(urls: string[]): string[] {
  const re = /^https?:\/\/((?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63})(?::(\d{1,5}))?(?:[\/?#]\S*)?$/i;
  return urls.filter(u => {
    const m = re.exec(u);
    return m !== null && (m[2] === undefined || Number(m[2]) <= 65535);
  });
}

export function solve<T>(value: T): T {
  return lib.cloneDeep(value) as T;
}

export function solve(word: string, dictionary: string[]): string {
  const dist = (a: string, b: string): number => {
    let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
    for (let i = 1; i <= a.length; i++) {
      const cur = [i];
      for (let j = 1; j <= b.length; j++)
        cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = cur;
    }
    return prev[b.length];
  };
  let best = dictionary[0], bestD = Infinity;
  for (const w of dictionary) {
    const d = dist(word, w);
    if (d < bestD) { bestD = d; best = w; }
  }
  return best;
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  const known = new Set(nodes);
  const indeg = new Map(nodes.map((n): [string, number] => [n, 0]));
  const adj = new Map(nodes.map((n): [string, string[]] => [n, []]));
  for (const [a, b] of edges) {
    if (!known.has(a) || !known.has(b)) throw new Error(`Unknown node in edge [${a}, ${b}]`);
    adj.get(a)!.push(b);
    indeg.set(b, indeg.get(b)! + 1);
  }
  const queue = nodes.filter(n => indeg.get(n) === 0);
  for (let i = 0; i < queue.length; i++) {
    for (const m of adj.get(queue[i])!) {
      indeg.set(m, indeg.get(m)! - 1);
      if (indeg.get(m) === 0) queue.push(m);
    }
  }
  if (queue.length !== nodes.length) throw new Error("Cycle detected");
  return queue;
}

export function solve(epochMs: number): string {
  return new Date(epochMs).toISOString().replace(/\.\d{3}Z$/, "Z");
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) throw new Error("Invalid base64 length");
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const out: number[] = [];
  for (let i = 0; i < text.length; i += 4) {
    const chunk = text.slice(i, i + 4);
    const pad = chunk.endsWith("==") ? 2 : chunk.endsWith("=") ? 1 : 0;
    let n = 0;
    for (let j = 0; j < 4; j++) {
      const c = chunk[j];
      const v = c === "=" ? 0 : alphabet.indexOf(c);
      if (v < 0) throw new Error("Invalid base64 character");
      n = (n << 6) | v;
    }
    const bytes = [(n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff];
    out.push(...bytes.slice(0, 3 - pad));
  }
  return out;
}

export function solve(text: string): string {
    // Encode the string as UTF-8 manually (no TextEncoder, which is not part of ECMAScript).
    // Surrogate pairs are combined into code points; lone surrogates become U+FFFD,
    // matching the behavior of standard UTF-8 encoders.
    const out: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < text.length) {
            const next = text.charCodeAt(i + 1);
            if (next >= 0xdc00 && next <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
                i++;
            } else {
                cp = 0xfffd;
            }
        } else if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd;
        }

        if (cp < 0x80) {
            out.push(cp);
        } else if (cp < 0x800) {
            out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            out.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            out.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    const bytes = new Uint8Array(out);

    // Delegate the MD5 computation to the library function.
    const digest = lib.md5(bytes) as ArrayLike<number>;

    // Convert the digest bytes to a 32-character lowercase hex string.
    let hex = "";
    for (let i = 0; i < digest.length; i++) {
        hex += (digest[i] & 0xff).toString(16).padStart(2, "0");
    }
    return hex;
}

export function solve(range: string): string | null {
  if (typeof range !== 'string') {
    return null;
  }

  try {
    const result = lib.minVersion(range);
    return result ? result.version : null;
  } catch (_err) {
    // lib.minVersion throws on invalid range expressions
    return null;
  }
}

export function solve(name: string, namespace: string): string {
    // Parse the namespace UUID (hyphens optional, case-insensitive) into 16 bytes.
    const hex = namespace.replace(/-/g, "");
    if (!/^[0-9a-fA-F]{32}$/.test(hex)) {
        throw new Error("Invalid namespace UUID: " + namespace);
    }
    const nsBytes = new Uint8Array(16);
    for (let i = 0; i < 16; i++) {
        nsBytes[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
    }

    // Encode the name as UTF-8 manually (lone surrogates become U+FFFD).
    const nameBytes: number[] = [];
    for (const ch of name) {
        let cp = ch.codePointAt(0) as number;
        if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd;
        }
        if (cp < 0x80) {
            nameBytes.push(cp);
        } else if (cp < 0x800) {
            nameBytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            nameBytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            nameBytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    // Hash namespace bytes followed by name bytes.
    const data = new Uint8Array(16 + nameBytes.length);
    data.set(nsBytes, 0);
    data.set(nameBytes, 16);
    const hash = lib.sha1(data);

    // Take the first 16 bytes and set version (5) and RFC 4122 variant bits.
    const b = hash.slice(0, 16);
    b[6] = (b[6] & 0x0f) | 0x50;
    b[8] = (b[8] & 0x3f) | 0x80;

    // Format as lowercase 8-4-4-4-12.
    let out = "";
    for (let i = 0; i < 16; i++) {
        out += b[i].toString(16).padStart(2, "0");
        if (i === 3 || i === 5 || i === 7 || i === 9) {
            out += "-";
        }
    }
    return out;
}

export function solve(text: string): string | null {
  // Lookbehind/lookahead ensure each digit run is complete (no partial matches inside longer digit runs).
  const m = /(?<!\d)(\d{1,16})(?:\.(\d{1,16}))?(?:\.(\d{1,16}))?(?!\d)/.exec(text);
  if (!m) return null;
  return `${m[1]}.${m[2] ?? "0"}.${m[3] ?? "0"}`;
}

export function solve(a: string, b: string): boolean {
  try {
    return lib.intersects(a, b);
  } catch {
    // An unparseable range matches no version, so the answer is false.
    return false;
  }
}

export function solve(version: string, range: string): boolean {
  return lib.gtr(version, range);
}

export function solve(text: string): boolean {
  // Optional sign, one or more integer digits, optional fraction of one or more digits.
  const NUMBER = /^[+-]?(\d+)(?:\.(\d+))?$/;

  // True when the value matches NUMBER and its magnitude is at most `limit`.
  const inRange = (value: string, limit: number): boolean => {
    const match = NUMBER.exec(value);
    if (match === null) return false;

    const [, whole, fraction = ""] = match;
    // Number() is monotonic and exact for these small limits, so this comparison is exact.
    const magnitude = Number(whole);
    // Reaching the limit exactly requires a zero fraction ("90.0" is valid, "90.1" is not).
    return magnitude < limit || (magnitude === limit && /^0*$/.test(fraction));
  };

  // Optionally wrapped in exactly one pair of parentheses.
  const body =
    text.startsWith("(") && text.endsWith(")") ? text.slice(1, -1) : text;

  // Exactly one comma, with no space allowed before it.
  const parts = body.split(",");
  if (parts.length !== 2) return false;
  const [latitude, longitude] = parts;

  // Only spaces may follow the comma.
  return inRange(latitude, 90) && inRange(longitude.replace(/^ */, ""), 180);
}

const cmpStr = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
