  const s = v.split('+')[0], d = s.indexOf('-');
  return { core: (d < 0 ? s : s.slice(0, d)).split('.'), pre: d < 0 ? [] : s.slice(d + 1).split('.') };
};
export function solve(versions: string[]): string[] {
  return [...versions].sort((x, y) => {
    const a = parse(x), b = parse(y);
    for (let i = 0; i < 3; i++) { const c = cmpId(a.core[i], b.core[i]); if (c) return c; }
    if (!a.pre.length || !b.pre.length) return b.pre.length - a.pre.length || cmpStr(x, y);
    for (let i = 0; i < Math.min(a.pre.length, b.pre.length); i++) { const c = cmpId(a.pre[i], b.pre[i]); if (c) return c; }
    return a.pre.length - b.pre.length || cmpStr(x, y);
  });
}

export function solve(text: string): string {
    // Encode the string as UTF-8 manually (lone surrogates become U+FFFD, as TextEncoder does).
    const out: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff) {
            const lo = i + 1 < text.length ? text.charCodeAt(i + 1) : -1;
            if (lo >= 0xdc00 && lo <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
                i++;
            } else {
                cp = 0xfffd;
            }
        } else if (cp >= 0xdc00 && cp <= 0xdfff) {
            cp = 0xfffd;
        }

        if (cp < 0x80) {
            out.push(cp);
        } else if (cp < 0x800) {
            out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            out.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            out.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    const digest = lib.sha1(Uint8Array.from(out));
    return Array.from(digest, (b) => b.toString(16).padStart(2, "0")).join("");
