const CHAR_CLASS: Readonly<Record<string, string>> = {
  n: "[0-9]",
  a: "[A-Z]",
  c: "[A-Z0-9]",
};

function bbanPattern(spec: string): RegExp {
  const body = spec.replace(
    /(\d+)([nac])/g,
    (_match, count: string, type: string) => `${CHAR_CLASS[type]}{${count}}`
  );
  return new RegExp(`^${body}$`);
}

function mod97(s: string): number {
  let remainder = 0;
  for (const ch of s) {
    const code = ch.charCodeAt(0);
    if (code >= 48 && code <= 57) {
      // digit
      remainder = (remainder * 10 + (code - 48)) % 97;
    } else {
      // letter A-Z -> 10..35, processed as two decimal digits
      const value = code - 55;
      remainder = (remainder * 100 + value) % 97;
    }
  }
  return remainder;
}

export function solve(iban: string): boolean {
  const normalized = iban.replace(/[ -]/g, "").toUpperCase();

  if (!/^[A-Z]{2}[0-9]{2}[A-Z0-9]+$/.test(normalized)) {
    return false;
  }

  const country = normalized.slice(0, 2);
  if (!Object.prototype.hasOwnProperty.call(IBAN_REGISTRY, country)) {
    return false;
  }

  const format = IBAN_REGISTRY[country];
  if (normalized.length !== format.length) {
    return false;
  }

  const bban = normalized.slice(4);
  if (!bbanPattern(format.bban).test(bban)) {
    return false;
  }

  const rearranged = bban + normalized.slice(0, 4);
  return mod97(rearranged) === 1;
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;
  if (!/^[0-9]+$/.test(code)) return false;

  const n = code.length;
  if (n !== 8 && n !== 13 && n !== 14) return false;

  // Weights alternate 3,1,3,1,... starting from the rightmost data digit
  // (the digit just left of the check digit).
  let sum = 0;
  for (let i = 0; i < n - 1; i++) {
    const digit = code.charCodeAt(i) - 48;
    const posFromRight = n - 2 - i;
    sum += posFromRight % 2 === 0 ? digit * 3 : digit;
  }

  const check = (10 - (sum % 10)) % 10;
  const actual = code.charCodeAt(n - 1) - 48;
  return check === actual;
}

export function solve(text: string, version?: 4 | 6): boolean {
  const wantV4 = version === undefined || version === 4;
  const wantV6 = version === undefined || version === 6;

  if (wantV4 && isIPv4(text)) return true;
  if (wantV6 && isIPv6(text)) return true;
  return false;
}

function isIPv4(s: string): boolean {
  const parts = s.split(".");
  if (parts.length !== 4) return false;
  for (const p of parts) {
    if (!/^(0|[1-9][0-9]{0,2})$/.test(p)) return false;
    if (Number(p) > 255) return false;
  }
  return true;
}

const HEX_GROUP = /^[0-9A-Fa-f]{1,4}$/;

function isIPv6(text: string): boolean {
  let addr = text;
  const pct = text.indexOf("%");

  if (pct !== -1) {
    addr = text.slice(0, pct);
    const zone = text.slice(pct + 1);
    if (!/^[0-9A-Za-z]+$/.test(zone)) return false;
    // Zone index is only permitted after a link-local address (fe80::/10).
    const firstGroup = addr.split(":")[0];
    if (!/^[fF][eE][89abAB][0-9a-fA-F]$/.test(firstGroup)) return false;
  }

  if (!parseIPv6Address(addr)) return false;
  return true;
}

function parseIPv6Address(addr: string): boolean {
  // An embedded dotted IPv4 tail is only allowed as the final token.
  // Replace it with two zero groups so the rest can be validated as pure hex.
  const lastColon = addr.lastIndexOf(":");
  const lastToken = addr.slice(lastColon + 1);
  if (lastToken.includes(".")) {
    if (!isIPv4(lastToken)) return false;
    addr = addr.slice(0, lastColon + 1) + "0:0";
  }

  // Dotted notation anywhere else is invalid.
  if (addr.includes(".")) return false;

  const dbl = addr.indexOf("::");
  if (dbl !== -1) {
    // At most one "::" (this also rejects ":::").
    if (addr.indexOf("::", dbl + 1) !== -1) return false;

    const left = addr.slice(0, dbl);
    const right = addr.slice(dbl + 2);
    const leftGroups = left === "" ? [] : left.split(":");
    const rightGroups = right === "" ? [] : right.split(":");

    for (const g of leftGroups) {
      if (!HEX_GROUP.test(g)) return false;
    }
    for (const g of rightGroups) {
      if (!HEX_GROUP.test(g)) return false;
    }

    // "::" must stand for at least one zero group.
    return leftGroups.length + rightGroups.length <= 7;
  }

  const groups = addr.split(":");
  if (groups.length !== 8) return false;
  for (const g of groups) {
    if (!HEX_GROUP.test(g)) return false;
  }
  return true;
}

export function solve(text: string): boolean {
  let s = text;
  if (s.startsWith("(") && s.endsWith(")")) {
    s = s.slice(1, -1);
  }

  const m = /^([+\-\u2212]?\d+(?:\.\d+)?),[ ]*([+\-\u2212]?\d+(?:\.\d+)?)$/.exec(s);
  if (!m) return false;

  const lat = parseSigned(m[1]);
  const lon = parseSigned(m[2]);

  return lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180;
}

function parseSigned(t: string): number {
  const neg = t[0] === "-" || t[0] === "\u2212";
  const body = /^[+\-\u2212]/.test(t) ? t.slice(1) : t;
  const v = Number(body);
  return neg ? -v : v;
}

export function solve(issn: string): boolean {
  // Format: NNNN-NNNC or NNNNNNNC, where C is a digit or X/x.
  const match = /^(\d{4})-?(\d{3})([\dXx])$/.exec(issn);
  if (match === null) {
    return false;
  }

  const chars = match[1] + match[2] + match[3]; // 8 characters, no hyphen

  // Weights are 8, 7, ..., 2 for the first seven digits and 1 for the check
  // character. Using 0-based index i with weight (8 - i) gives exactly this.
  let sum = 0;
  for (let i = 0; i < 8; i++) {
    const c = chars[i];
    const value = c === "X" || c === "x" ? 10 : Number(c);
    sum += (8 - i) * value;
  }

  return sum % 11 === 0;
}

export function solve(a: string, b: string): number {
  const n = a.length;
  const m = b.length;
  if (n === 0) return m;
  if (m === 0) return n;

  let prev = new Int32Array(m + 1);
  let curr = new Int32Array(m + 1);
  for (let j = 0; j <= m; j++) prev[j] = j;

  for (let i = 1; i <= n; i++) {
    curr[0] = i;
    const ca = a.charCodeAt(i - 1);
    for (let j = 1; j <= m; j++) {
      const cost = ca === b.charCodeAt(j - 1) ? 0 : 1;
      let v = prev[j - 1] + cost;
      const del = prev[j] + 1;
      if (del < v) v = del;
      const ins = curr[j - 1] + 1;
      if (ins < v) v = ins;
      curr[j] = v;
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[m];
}

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === "") {
    return doc;
  }
  if (!pointer.startsWith("/")) {
    throw new Error(`Invalid JSON Pointer: must be empty or start with "/": ${JSON.stringify(pointer)}`);
  }

  const tokens = pointer.slice(1).split("/");
  let current: unknown = doc;

  for (const raw of tokens) {
    // RFC 6901: decode ~1 to "/" first, then ~0 to "~".
    const key = raw.replace(/~1/g, "/").replace(/~0/g, "~");

    if (Array.isArray(current)) {
      // Array index: "0" or a non-zero-leading digit sequence. "-" and others are not existing elements.
      if (!/^(0|[1-9][0-9]*)$/.test(key)) {
        return undefined;
      }
      const index = Number(key);
      if (index >= current.length) {
        return undefined;
      }
      current = current[index];
    } else if (typeof current === "object" && current !== null) {
      if (!Object.prototype.hasOwnProperty.call(current, key)) {
        return undefined;
      }
      current = (current as Record<string, unknown>)[key];
    } else {
      // Primitive or null: cannot descend further.
      return undefined;
    }
  }

  return current;
}

export function solve(name: string): boolean {
  if (typeof name !== 'string') return false;

  // Whole name at most 253 characters
  if ([...name].length > 253) return false;

  const labels = name.split('.');

  // At least two labels; an empty label (leading, trailing or doubled dot) is invalid
  if (labels.length < 2) return false;

  // Non-TLD labels: 1-63 ASCII letters/digits/hyphens, not starting or ending with a hyphen
  const LABEL = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/;
  for (let i = 0; i < labels.length - 1; i++) {
    if (!LABEL.test(labels[i])) return false;
  }

  // TLD: at least 2 and at most 63 characters
  const tld = labels[labels.length - 1];
  const tldLength = [...tld].length;
  if (tldLength < 2 || tldLength > 63) return false;

  // Punycode TLD: xn-- prefix, same character and hyphen rules as other labels
  if (/^xn--/i.test(tld)) {
    return /^xn--[A-Za-z0-9-]*[A-Za-z0-9]$/i.test(tld);
  }

  // Otherwise the TLD must consist only of letters (international letters allowed)
  return /^\p{L}+$/u.test(tld);
}

interface Ver {
  n: [number, number, number];
  pre: string[];
}

interface Bound {
  v: Ver;
  incl: boolean;
}

interface Part {
  M?: number;
  m: number;
  p: number;
  hasMinor: boolean;
  hasPatch: boolean;
  pre: string[];
}

function V(a: number, b: number, c: number, pre: string[] = []): Ver {
  return { n: [a, b, c], pre };
}

function ex(a: number, b: number, c: number): Bound {
  return { v: V(a, b, c, ['0']), incl: false };
}

function isWild(s: string | undefined): boolean {
  return s === undefined || s === '' || s === 'x' || s === 'X' || s === '*';
}

function parsePart(s: string): Part {
