const PLUS_SUFFIX_DOMAINS = new Set<string>(["outlook.com", "hotmail.com", "live.com"]);

function stripPlusSuffix(local: string): string {
  const plus = local.indexOf("+");
  return plus === -1 ? local : local.slice(0, plus);
}

function canonicalize(address: string): string {
  const email = address.toLowerCase();

  // Split on the last "@", since a domain can never contain "@".
  const at = email.lastIndexOf("@");
  if (at === -1) {
    return email;
  }

  let local = email.slice(0, at);
  let domain = email.slice(at + 1);

  if (GMAIL_DOMAINS.has(domain)) {
    local = stripPlusSuffix(local).replace(/\./g, "");
    domain = "gmail.com";
  } else if (PLUS_SUFFIX_DOMAINS.has(domain)) {
    local = stripPlusSuffix(local);
  }

  return `${local}@${domain}`;
}

export function solve(emails: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];

  for (const email of emails) {
    const canonical = canonicalize(email);
    if (!seen.has(canonical)) {
      seen.add(canonical);
      result.push(canonical);
    }
  }

  return result;
}

export function solve(epochMs: number): string {
  if (!Number.isFinite(epochMs)) {
    throw new RangeError("epochMs must be a finite number");
  }

  // Floor before converting: Date truncates fractional milliseconds toward zero,
  // which would place pre-1970 fractional instants in the following second.
  const ms = Math.floor(epochMs);

  // toISOString() is always UTC and yields "YYYY-MM-DDTHH:mm:ss.sssZ"
  // (years outside 0000-9999 use the ECMAScript expanded form "±YYYYYY").
  // Strip the milliseconds and keep the trailing "Z".
  return new Date(ms).toISOString().replace(/\.\d{3}Z$/, "Z");
}

