      e = d;
      d = c;
      c = ((b << 30) | (b >>> 2)) >>> 0;
      b = a;
      a = temp;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }

  // 4. Serialize as 40 lowercase hex digits (big-endian words).
  const hs = [h0, h1, h2, h3, h4];
  let out = "";
  for (let i = 0; i < hs.length; i++) {
    const hex = (hs[i] >>> 0).toString(16);
    out += "00000000".slice(hex.length) + hex;
  }
  return out;
}

/** Validates an ISBN-10 whose spaces and hyphens have already been removed. */
function isValidIsbn10(code: string): boolean {
  if (!/^[0-9]{9}[0-9X]$/.test(code)) return false;

  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const ch = code.charAt(i);
    const value = ch === 'X' ? 10 : ch.charCodeAt(0) - 48; // '0' is char code 48
    sum += (10 - i) * value; // weights 10, 9, ..., 1
  }
  return sum % 11 === 0;
}

/** Validates an ISBN-13 whose spaces and hyphens have already been removed. */
function isValidIsbn13(code: string): boolean {
  if (!/^[0-9]{13}$/.test(code)) return false;

  let sum = 0;
  for (let i = 0; i < 13; i++) {
    const digit = code.charCodeAt(i) - 48;
    sum += i % 2 === 0 ? digit : 3 * digit; // weights 1, 3, 1, 3, ...
  }
  return sum % 10 === 0;
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  if (typeof isbn !== 'string') return false;

  const code = isbn.replace(/[ -]/g, ''); // spaces and hyphens are ignored

  const checkTen = version === undefined || version === 10;
  const checkThirteen = version === undefined || version === 13;

  return (checkTen && isValidIsbn10(code)) || (checkThirteen && isValidIsbn13(code));
}

export function solve(isin: string): boolean {
  // Format: 2 upper-case letters, 9 upper-case alphanumerics, 1 check digit.
  if (!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) {
    return false;
  }

  // Convert letters to numbers (A=10 ... Z=35), keeping digits as they are.
  let digits = "";
  for (let i = 0; i < isin.length; i++) {
    const ch = isin.charAt(i);
    digits += ch >= "A" && ch <= "Z" ? String(ch.charCodeAt(0) - 55) : ch;
  }

  // Luhn algorithm over the whole digit string, scanning from the rightmost
  // digit (the check digit). Every second digit is doubled, and for doubled
  // values above 9 the digit sum is taken. Valid when the total is divisible by 10.
  let sum = 0;
  let doubleIt = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48; // "0" is char code 48
    if (doubleIt) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    doubleIt = !doubleIt;
  }

  return sum % 10 === 0;
}

export function solve(code: string): boolean {
  // Only ASCII digits are allowed
  if (!/^[0-9]+$/.test(code)) return false;

  const n = code.length;
  if (n !== 8 && n !== 13 && n !== 14) return false;

  const digitAt = (i: number): number => code.charCodeAt(i) - 48; // '0' is char code 48

  // Weights alternate 3, 1, 3, ... starting at the rightmost data digit
  // (the digit immediately before the check digit, index n - 2).
  let sum = 0;
  for (let i = 0; i < n - 1; i++) {
    const weight = i % 2 === 0 ? 3 : 1;
    sum += digitAt(n - 2 - i) * weight;
  }

  const check = (10 - (sum % 10)) % 10;
  return check === digitAt(n - 1);
}

export function solve(mac: string): boolean {
  // EUI-48 (6 octets) or EUI-64 (8 octets) with ':' or '-' separators.
  // The backreference \1 forces every separator to be the same character.
  const octets6 = /^[0-9A-Fa-f]{2}([:-])(?:[0-9A-Fa-f]{2}\1){4}[0-9A-Fa-f]{2}$/;
  const octets8 = /^[0-9A-Fa-f]{2}([:-])(?:[0-9A-Fa-f]{2}\1){6}[0-9A-Fa-f]{2}$/;

  // Dotted form (e.g. 0123.4567.89ab): 3 groups (EUI-48) or 4 groups (EUI-64) of 4 hex digits.
  const dotted = /^[0-9A-Fa-f]{4}(?:\.[0-9A-Fa-f]{4}){2,3}$/;

  return octets6.test(mac) || octets8.test(mac) || dotted.test(mac);
}

export function solve(issn: string): boolean {
  // Accept "NNNN-NNNC" or "NNNNNNNC"; the check character may be a digit or X/x.
  if (!/^\d{4}-?\d{3}[\dXx]$/.test(issn)) {
    return false;
  }

  const digits = issn.replace("-", ""); // 8 characters: 7 digits + check character

  // Weighted sum of the first seven digits, with weights 8 down to 2.
  let sum = 0;
  for (let i = 0; i < 7; i++) {
    sum += (8 - i) * Number(digits[i]);
  }

  // The check character has weight 1; 'X' or 'x' counts as 10.
  const check = digits[7];
  sum += check === "X" || check === "x" ? 10 : Number(check);

  return sum % 11 === 0;
}

export function solve(a: string, b: string): number {
  // Levenshtein distance over UTF-16 code units (charCodeAt).
  // The shorter string indexes the row, so only two rows of min(|a|, |b|) + 1 cells are allocated.
  let s = a; // longer (or equal length) string: outer loop
  let t = b; // shorter string: inner loop
  if (s.length < t.length) {
    s = b;
    t = a;
  }

  const n = s.length;
  const m = t.length;
  if (m === 0) return n;

  const tc = new Uint16Array(m);
  for (let j = 0; j < m; j++) tc[j] = t.charCodeAt(j);

  // prev[j] = distance between the first i code units of s and the first j code units of t
  let prev = new Int32Array(m + 1);
  let curr = new Int32Array(m + 1);
  for (let j = 0; j <= m; j++) prev[j] = j;

  for (let i = 1; i <= n; i++) {
    const sc = s.charCodeAt(i - 1);
    curr[0] = i;
    for (let j = 1; j <= m; j++) {
      const cost = sc === tc[j - 1] ? 0 : 1;
      let best = prev[j - 1] + cost; // match or substitution
      const del = prev[j] + 1; // deletion
      if (del < best) best = del;
      const ins = curr[j - 1] + 1; // insertion
      if (ins < best) best = ins;
      curr[j] = best;
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[m];
}

export function solve(installed: string[], range: string): string | null {
  // Non-string entries cannot be versions, so drop them before delegating.
  // Strings that are not valid semver are rejected by the matcher itself,
  // since Range.test returns false for them, so they never become the result.
  const candidates = installed.filter((v) => typeof v === 'string')

  const result = lib.maxSatisfying(candidates, range)
  return result === undefined ? null : result
}

export function solve(sub: string, sup: string): boolean {
  return lib.subset(sub, sup, {})
}

/**
 * An issuer is described by inclusive leading-digit ranges and the permitted total digit counts.
 * Both bounds of a range have the same number of digits, so string and numeric order agree.
 */
interface Issuer {
  readonly prefixes: ReadonlyArray<readonly [string, string]>;
  readonly lengths: ReadonlyArray<number>;
}

const ISSUERS: ReadonlyArray<Issuer> = [
  // Visa
  { prefixes: [['4', '4']], lengths: [13, 16, 19] },
  // Mastercard
  { prefixes: [['51', '55'], ['2221', '2720']], lengths: [16] },
  // American Express
  { prefixes: [['34', '34'], ['37', '37']], lengths: [15] },
  // Discover
  {
    prefixes: [['6011', '6011'], ['622126', '622925'], ['644', '649'], ['65', '65']],
    lengths: [16, 19],
  },
  // Diners Club
  {
    prefixes: [['300', '305'], ['36', '36'], ['38', '38']],
    lengths: [14, 15, 16, 17, 18, 19],
  },
  // JCB
  { prefixes: [['3528', '3589']], lengths: [16, 17, 18, 19] },
  // UnionPay
  { prefixes: [['62', '62']], lengths: [16, 17, 18, 19] },
];

function matchesIssuer(digits: string): boolean {
  return ISSUERS.some((issuer) => {
    if (issuer.lengths.indexOf(digits.length) === -1) {
      return false;
    }
    return issuer.prefixes.some(([low, high]) => {
      const head = digits.slice(0, low.length);
      return head.length === low.length && head >= low && head <= high;
    });
  });
}

function passesLuhn(digits: string): boolean {
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    // i = 0 is the rightmost digit; double every second digit from the right (i odd).
    let d = Number(digits.charAt(digits.length - 1 - i));
    if (i % 2 === 1) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
  }
  return sum % 10 === 0;
}

/**
 * Returns true if `card` is a plausible payment card number: spaces and hyphens are ignored,
 * the remaining characters must all be digits, the digits must match a known issuer's prefix
 * and length, and the number must pass the Luhn check.
 */
export function solve(card: string): boolean {
  const digits = card.replace(/[ -]/g, '');
  if (!/^\d+$/.test(digits)) {
    return false;
  }
  return matchesIssuer(digits) && passesLuhn(digits);
}

export function solve(obj: object, updates: [string | (string | number)[], unknown][]): object {
  const toKeys = (p: string | (string | number)[]): (string | number)[] =>
    typeof p === "string" ? p.match(/[^.[\]]+/g) ?? [] : p;
  const isIndex = (k: string | number): boolean =>
    typeof k === "number" ? Number.isInteger(k) && k >= 0 : /^\d+$/.test(k);

  for (const [path, value] of updates) {
    const keys = toKeys(path);
    if (keys.length === 0) continue;
    let cur: any = obj;
    for (let i = 0; i < keys.length - 1; i++) {
      const k = keys[i];
      if (typeof cur[k] !== "object" || cur[k] === null) {
        cur[k] = isIndex(keys[i + 1]) ? [] : {};
      }
      cur = cur[k];
    }
    cur[keys[keys.length - 1]] = value;
  }
  return obj;
}

export function solve(emails: string[]): string[] {
  const seen = new Set<string>();
  for (const raw of emails) {
    const e = raw.toLowerCase();
    const at = e.lastIndexOf("@");
    let canon = e;
    if (at > 0) {
      let local = e.slice(0, at);
      let domain = e.slice(at + 1);
      const gmail = domain === "gmail.com" || domain === "googlemail.com";
      if (gmail || ["outlook.com", "hotmail.com", "live.com"].includes(domain)) {
        local = local.split("+")[0];
      }
      if (gmail) {
        local = local.replace(/\./g, "");
        domain = "gmail.com";
      }
      canon = `${local}@${domain}`;
    }
    seen.add(canon);
  }
  return Array.from(seen);
}

const pattern = /^https?:\/\/(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}(?::\d{1,5})?(?:[\/?#]\S*)?$/i;

export function solve(urls: string[]): string[] {
  return urls.filter((u) => pattern.test(u));
}

export function solve<T>(value: T): T {
  return lib.cloneDeep(value) as T;
}

export function solve(word: string, dictionary: string[]): string {
  const dist = (a: string, b: string): number => {
    let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
    for (let i = 1; i <= a.length; i++) {
      const cur: number[] = [i];
      for (let j = 1; j <= b.length; j++) {
        cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
      }
      prev = cur;
    }
    return prev[b.length];
  };
  let best = dictionary[0];
  let bestD = Infinity;
  for (const w of dictionary) {
    const d = dist(word, w);
    if (d < bestD) {
      bestD = d;
      best = w;
    }
  }
  return best;
}

export function solve(doc: unknown, pointer: string): unknown {
  if (typeof pointer !== "string") {
    throw new Error("JSON Pointer must be a string");
  }
  if (pointer === "") {
    return doc; // the empty pointer refers to the whole document
  }
  if (pointer.charAt(0) !== "/") {
    throw new Error(
      `Invalid JSON Pointer ${JSON.stringify(pointer)}: must be empty or start with "/"`
    );
  }

  // Tokens are separated by "/". A literal "/" inside a token is always
  // escaped as "~1", so a plain split is safe.
  const tokens = pointer.slice(1).split("/");

  let current: unknown = doc;
  for (const encoded of tokens) {
    // Unescape in RFC 6901 order: "~1" -> "/" first, then "~0" -> "~"
    // (so "~01" decodes to "~1"). Other "~" sequences are left as-is.
    const token = encoded.replace(/~1/g, "/").replace(/~0/g, "~");

    if (Array.isArray(current)) {
      // "0" or a digit string without leading zeros names an index;
      // anything else (e.g. "-") names no existing element.
      if (!/^(0|[1-9][0-9]*)$/.test(token)) {
        return undefined;
      }
      const index = Number(token);
      if (index >= current.length) {
        return undefined;
      }
      current = current[index];
    } else if (typeof current === "object" && current !== null) {
      // Only own properties are members; inherited ones (e.g. "constructor")
      // must not be reachable through a pointer.
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        return undefined;
      }
      current = (current as Record<string, unknown>)[token];
    } else {
      // Strings, numbers, booleans, null and undefined have no members.
      return undefined;
    }
  }
  return current;
}

export function solve(epochMs: number): string {
  return new Date(epochMs).toISOString().replace(/\.\d{3}Z$/, "Z");
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  const known = new Set(nodes);
  const indeg = new Map<string, number>([...known].map(n => [n, 0]));
  const adj = new Map<string, string[]>([...known].map(n => [n, []]));
  for (const [a, b] of edges) {
    if (!known.has(a) || !known.has(b)) throw new Error(`Unknown node in edge [${a}, ${b}]`);
    adj.get(a)!.push(b);
    indeg.set(b, indeg.get(b)! + 1);
  }
  const queue = [...known].filter(n => indeg.get(n) === 0);
  for (let i = 0; i < queue.length; i++) {
    for (const m of adj.get(queue[i])!) {
      indeg.set(m, indeg.get(m)! - 1);
      if (indeg.get(m) === 0) queue.push(m);
    }
  }
  if (queue.length !== known.size) throw new Error("Cycle detected");
  return queue;
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) throw new Error("Invalid base64 length");
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const out: number[] = [];
  for (let i = 0; i < text.length; i += 4) {
    const pad = text[i + 3] === "=" ? (text[i + 2] === "=" ? 2 : 1) : 0;
    let n = 0;
    for (let j = 0; j < 4; j++) {
      const c = text[i + j];
      const v = c === "=" ? 0 : alphabet.indexOf(c);
      if (v < 0 || (c === "=" && j < 4 - pad)) throw new Error("Invalid base64 character");
      n = (n << 6) | v;
    }
    out.push((n >> 16) & 0xff);
    if (pad < 2) out.push((n >> 8) & 0xff);
    if (pad < 1) out.push(n & 0xff);
  }
  return out;
}

export function solve(range: string): string | null {
  try {
    const result = lib.minVersion(range);
    if (!result) {
      return null;
    }
    // format() recomputes the version string from major/minor/patch/prerelease,
    // so it is correct even for versions that were mutated by the library.
    return result.format();
  } catch {
    // An invalid range makes the library's Range constructor throw.
    return null;
  }
}

export function solve(a: string, b: string): boolean {
  return lib.intersects(a, b);
}

export function solve(text: string): string {
  // Manual UTF-8 encoding (no TextEncoder, which is not ECMAScript).
  // Lone surrogates are replaced with U+FFFD, matching TextEncoder behavior.
  const bytes: number[] = [];
  for (let i = 0; i < text.length; i++) {
    let cp = text.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < text.length) {
      const lo = text.charCodeAt(i + 1);
      if (lo >= 0xdc00 && lo <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
        i++;
      } else {
        cp = 0xfffd;
      }
    } else if (cp >= 0xd800 && cp <= 0xdfff) {
      cp = 0xfffd;
    }

    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  const digest = lib.md5(Uint8Array.from(bytes));

  let hex = "";
  for (let i = 0; i < 16; i++) {
    hex += (digest[i] & 0xff).toString(16).padStart(2, "0");
  }
  return hex;
}

export function solve(text: string): string | null {
  const m = /(?<!\d)(\d{1,16})(?:\.(\d{1,16})(?:\.(\d{1,16}))?)?(?!\d)/.exec(text);
  if (!m) return null;
  const norm = (s: string | undefined) => (s === undefined ? "0" : s.replace(/^0+(?=\d)/, ""));
  return `${norm(m[1])}.${norm(m[2])}.${norm(m[3])}`;
}

export function solve(stamps: string[]): number[] {
  // An explicit offset is "Z" or ±hh, ±hh:mm, or ±hhmm at the end of the time part.
  const OFFSET_TAIL = /(?:Z|[+-]\d{2}(?::?\d{2})?)$/;
  // Date/time separator accepted by ISO 8601 (and by the library's splitter).
  const DELIMITER = /[T ]/;

  // Rewrites an input so the library always sees an explicit offset,
  // which avoids its local-time branch (strings without an offset are UTC).
  const toExplicitUtc = (raw: string): string => {
    if (typeof raw !== "string") {
      throw new RangeError(`Invalid date: ${String(raw)}`);
    }

    const match = DELIMITER.exec(raw);

    if (match === null) {
      // Date-only: anchor at midnight UTC.
      return raw + "T00:00:00Z";
    }

    const timePart = raw.slice(match.index + 1);

    // An hour is required after the delimiter.
    if (!/^\d{2}/.test(timePart)) {
      throw new RangeError(`Invalid date: ${raw}`);
    }

    // No offset given: interpret as UTC.
    return OFFSET_TAIL.test(timePart) ? raw : raw + "Z";
  };

  const epochs = stamps.map((raw): number => {
    const iso = toExplicitUtc(raw);
    const ms = lib.parseISO(iso).getTime();

    if (Number.isNaN(ms)) {
      throw new RangeError(`Invalid date: ${String(raw)}`);
    }

    return ms;
  });

  return epochs.sort((a, b) => a - b);
}

export function solve(name: string, namespace: string): string {
    // Parse the namespace UUID (hyphens optional) into 16 bytes.
    const nsHex = namespace.replace(/-/g, "");
    if (!/^[0-9a-fA-F]{32}$/.test(nsHex)) {
        throw new Error("Invalid namespace UUID: " + namespace);
    }
    const nsBytes: number[] = [];
    for (let i = 0; i < 16; i++) {
        nsBytes.push(parseInt(nsHex.substr(i * 2, 2), 16));
    }

    // Encode the name as UTF-8 manually (no host encoding APIs).
    // Lone surrogates are replaced with U+FFFD, matching standard UTF-8 encoders.
    const nameBytes: number[] = [];
    for (const ch of name) {
        let cp = ch.codePointAt(0) as number;
        if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd;
        }
        if (cp < 0x80) {
            nameBytes.push(cp);
        } else if (cp < 0x800) {
            nameBytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            nameBytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            nameBytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    // SHA-1 over namespace bytes followed by name bytes.
    const input = new Uint8Array(nsBytes.length + nameBytes.length);
    input.set(nsBytes, 0);
    input.set(nameBytes, nsBytes.length);
    const digest = lib.sha1(input);

    // Take the first 16 bytes and set version (5) and RFC 4122 variant bits.
    const out = new Uint8Array(16);
    for (let i = 0; i < 16; i++) {
        out[i] = digest[i];
    }
    out[6] = (out[6] & 0x0f) | 0x50;
    out[8] = (out[8] & 0x3f) | 0x80;

    // Format as lowercase 8-4-4-4-12.
    let hex = "";
    for (let i = 0; i < 16; i++) {
        hex += (out[i] < 16 ? "0" : "") + out[i].toString(16);
    }
    return (
        hex.slice(0, 8) + "-" +
        hex.slice(8, 12) + "-" +
        hex.slice(12, 16) + "-" +
        hex.slice(16, 20) + "-" +
        hex.slice(20, 32)
    );
}

// A bare pair "<lat>,<lon>": each number is an optional ASCII sign, one or more digits,
// and an optional "." followed by one or more digits. Spaces are allowed only after the comma.
// Groups: 1 = latitude whole part, 2 = latitude fraction,
//         3 = longitude whole part, 4 = longitude fraction.
const COORD_PAIR = /^[+-]?(\d+)(?:\.(\d+))?, *[+-]?(\d+)(?:\.(\d+))?$/;

// True when |value| <= bound, where value = whole + "." + fraction.
// Compares the digit strings exactly, so floating-point rounding cannot admit
// a value just outside the range (e.g. 90.00000000000000001).
function withinBound(whole: string, fraction: string | undefined, bound: number): boolean {
  const digits = whole.replace(/^0+(?=\d)/, ""); // drop leading zeros, keep at least one digit
  const limit = String(bound);
  if (digits.length !== limit.length) return digits.length < limit.length;
  if (digits !== limit) return digits < limit;
  // Whole part equals the bound: only an all-zero fraction keeps the value in range.
  return fraction === undefined || !/[1-9]/.test(fraction);
}

/** True if `text` is a decimal "lat,lon" pair, optionally wrapped in one pair of parentheses. */
export function solve(text: string): boolean {
  const body = /^\(.*\)$/.test(text) ? text.slice(1, -1) : text;

  const match = COORD_PAIR.exec(body);
  if (match === null) return false;

  const [, latWhole, latFrac, lonWhole, lonFrac] = match;
  return withinBound(latWhole, latFrac, 90) && withinBound(lonWhole, lonFrac, 180);
}

export function solve(version: string, range: string): boolean {
  return lib.gtr(version, range);
}

export function solve(iban: string): boolean {
  const normalized = iban.replace(/[\s-]/g, "").toUpperCase();
  return lib.isIBAN(normalized);
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  const s = isbn.replace(/[ -]/g, "");
  const ok10 = /^\d{9}[\dX]$/.test(s) && [...s].reduce((sum, c, i) => sum + (10 - i) * (c === "X" ? 10 : +c), 0) % 11 === 0;
  const ok13 = /^\d{13}$/.test(s) && [...s].reduce((sum, c, i) => sum + +c * (i % 2 ? 3 : 1), 0) % 10 === 0;
  if (version === 10) return ok10;
  if (version === 13) return ok13;
  return ok10 || ok13;
}

export function solve(name: string, namespace: string): string {
    const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (typeof namespace !== "string" || !UUID_RE.test(namespace)) {
        throw new TypeError("Invalid namespace UUID: " + String(namespace));
    }
    return lib.v3(name, namespace.toLowerCase());
}

export function solve(isin: string): boolean {
  if (!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) return false;
  const digits = [...isin]
    .map((c) => (/[A-Z]/.test(c) ? String(c.charCodeAt(0) - 55) : c))
    .join("");
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48;
    if (double) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    double = !double;
  }
  return sum % 10 === 0;
}

export function solve(text: string): string {
    const bytes: number[] = [];
    for (const ch of text) {
        let cp = ch.codePointAt(0) as number;
        // Lone surrogates are not valid Unicode scalar values; encode as U+FFFD.
        if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd;
        }
        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            bytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            bytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    const digest: Uint8Array = lib.sha1(Uint8Array.from(bytes));

    let hex = "";
    for (let i = 0; i < digest.length; i++) {
        hex += digest[i].toString(16).padStart(2, "0");
    }
    return hex;
}

const stripBuild = (version: string): string => {
  const plus = version.indexOf("+");
  return plus === -1 ? version : version.slice(0, plus);
};

export function solve(versions: string[]): string[] {
  return [...versions].sort((a, b) => {
    // Compare precedence only: with build metadata removed, lib.compareBuild
    // returns the SemVer precedence result and never reaches its build tie-break.
    const byPrecedence = lib.compareBuild(stripBuild(a), stripBuild(b));
    if (byPrecedence !== 0) {
      return byPrecedence;
    }
    // Same precedence: order by the full version string, lexically.
    return a < b ? -1 : a > b ? 1 : 0;
  });
}

export function solve(text: string): boolean {
  const m = text.match(/^(\()?([+-]?\d+(?:\.\d+)?),[ ]*([+-]?\d+(?:\.\d+)?)(\))?$/);
  if (!m) return false;
  // Parentheses must be both present or both absent.
  if ((m[1] === undefined) !== (m[4] === undefined)) return false;
  const lat = Number(m[2]);
  const lon = Number(m[3]);
  return Math.abs(lat) <= 90 && Math.abs(lon) <= 180;
}

export function solve(code: string): boolean {
  if (![8, 13, 14].includes(code.length) || !/^\d+$/.test(code)) return false;
  const data = code.slice(0, -1);
  let sum = 0;
  for (let i = 0; i < data.length; i++) {
    const d = Number(data[data.length - 1 - i]);
    sum += d * (i % 2 === 0 ? 3 : 1);
  }
  return (10 - (sum % 10)) % 10 === Number(code[code.length - 1]);
}

export function solve(mac: string): boolean {
  const eui = /^(?:(?:[0-9a-f]{2}:){5}|(?:[0-9a-f]{2}:){7}|(?:[0-9a-f]{2}-){5}|(?:[0-9a-f]{2}-){7})[0-9a-f]{2}$/i;
  const dotted = /^(?:[0-9a-f]{4}\.){2,3}[0-9a-f]{4}$/i;
  return eui.test(mac) || dotted.test(mac);
}

export function solve(issn: string): boolean {
  if (!/^\d{4}-?\d{3}[\dXx]$/.test(issn)) return false;
  const chars = issn.replace("-", "");
  let sum = 0;
  for (let i = 0; i < 8; i++) {
    const c = chars[i];
    const value = c === "X" || c === "x" ? 10 : Number(c);
    sum += (8 - i) * value;
  }
  return sum % 11 === 0;
}

export function solve(a: string, b: string): number {
  if (a.length < b.length) [a, b] = [b, a];
  let prev: number[] = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur: number[] = [i];
    for (let j = 1; j <= b.length; j++) {
      const cost = a.charCodeAt(i - 1) === b.charCodeAt(j - 1) ? 0 : 1;
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost);
    }
    prev = cur;
  }
  return prev[b.length];
}

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === "") return doc;
  if (!pointer.startsWith("/")) throw new Error("Invalid JSON Pointer: must be empty or start with '/'");
  const tokens = pointer.slice(1).split("/").map(t => t.replace(/~1/g, "/").replace(/~0/g, "~"));
  let cur: unknown = doc;
  for (const key of tokens) {
    if (cur === null || typeof cur !== "object") return undefined;
    if (Array.isArray(cur)) {
      if (!/^(0|[1-9]\d*)$/.test(key)) return undefined;
      const i = Number(key);
      if (i >= cur.length) return undefined;
      cur = cur[i];
    } else {
      const obj = cur as Record<string, unknown>;
      if (!Object.prototype.hasOwnProperty.call(obj, key)) return undefined;
      cur = obj[key];
    }
  }
  return cur;
}

export function solve(name: string): boolean {
  if (name.length > 253 || name.endsWith('.')) return false;
  const labels = name.split('.');
  if (labels.length < 2) return false;
  const ok = (l: string) => /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/.test(l);
  const tld = labels[labels.length - 1];
  if (!labels.slice(0, -1).every(ok)) return false;
  if (/^xn--/i.test(tld)) return ok(tld);
  return /^\p{L}{2,}$/u.test(tld) && tld.length <= 63;
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  return lib.inc(version, kind, id) as string | null;
}

export function solve<T>(value: T): T {
  return lib.cloneDeep(value);
}

export function solve(obj: object, updates: [string | (string | number)[], unknown][]): object {
  for (const [path, value] of updates) {
    lib.set(obj, path, value);
  }
  return obj;
}

const SEMVER_MAX_LENGTH = 256;

// Strict semver grammar (as used by npm's semver parser): optional leading "v",
// numeric core without leading zeros, optional prerelease, optional build metadata.
const SEMVER_RE =
  /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][a-zA-Z0-9-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][a-zA-Z0-9-]*))*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;

const isValidVersion = (v: string): boolean => {
  const s = v.trim();
  return s.length <= SEMVER_MAX_LENGTH && SEMVER_RE.test(s);
};

export function solve(installed: string[], range: string): string | null {
  const valid = installed.filter(
    (v) => typeof v === 'string' && isValidVersion(v)
  );
  return lib.maxSatisfying(valid, range, undefined);
}

export function solve(name: string, namespace: string): string {
  return lib.v5(name, namespace);
}

declare const lib: {
  subset: (sub: string, dom: string, options?: object) => boolean
}

export function solve(sub: string, sup: string): boolean {
  // Delegates to the library's subset check. Note: this is a per-simple-range
  // check, so it can return false for a sub comparator set that is covered only
  // by the union of several sup alternatives (e.g. ">=1 <3" vs ">=1 <2 || >=2 <4").
  return lib.subset(sub, sup)
}

export function solve(word: string, dictionary: string[]): string {
    return lib.closest(word, dictionary);
}

export function solve(a: string, b: string): string | null {
  // Delegate to the library for equality, parsing, and the general cases.
  const change: string | null = lib.diff(a, b);
  if (change === null) {
    return null;
  }

  type Core = [number, number, number];
  type Parsed = { core: Core; pre: boolean };

  // Split a version into its numeric core and a prerelease flag.
  // Build metadata (after '+') is ignored.
  const parse = (v: string): Parsed => {
    const noBuild = v.split("+")[0];
    const dash = noBuild.indexOf("-");
    const corePart = dash === -1 ? noBuild : noBuild.slice(0, dash);
    const parts = corePart.split(".").map(Number);
    return {
      core: [parts[0], parts[1], parts[2]] as Core,
      pre: dash !== -1,
    };
  };

  const compareCores = (x: Core, y: Core): number => {
    for (let i = 0; i < 3; i++) {
      if (x[i] !== y[i]) {
        return x[i] > y[i] ? 1 : -1;
      }
    }
    return 0;
  };

  const pa = parse(a);
  const pb = parse(b);
  const cmp = compareCores(pa.core, pb.core);

  // Equal cores: the library's rules already match the specification
  // (major/minor/patch for prerelease -> release, pre-prefixed for release -> prerelease,
  // and 'prerelease' for prerelease -> prerelease).
  if (cmp === 0) {
    return change;
  }

  const high = cmp > 0 ? pa : pb;
  const low = cmp > 0 ? pb : pa;

  // Prerelease -> release with differing cores: the answer is the highest
  // core part that differs. The library's shortcut for minor/patch-zero
  // lower versions is not applied here.
  if (low.pre && !high.pre) {
    if (high.core[0] !== low.core[0]) {
      return "major";
    }
    if (high.core[1] !== low.core[1]) {
      return "minor";
    }
    return "patch";
  }

  // All other cases (release -> prerelease, prerelease -> prerelease) are
  // handled correctly by the library.
  return change;
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error(`Invalid base64 length: ${text.length} is not a multiple of 4`);
  }
  return Array.from(lib.toByteArray(text));
}

export function solve(text: string): string {
    // Encode the string as UTF-8 manually (no TextEncoder, no Node/browser APIs).
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < text.length) {
            const next = text.charCodeAt(i + 1);
            if (next >= 0xdc00 && next <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
                i++;
            } else {
                cp = 0xfffd; // unpaired high surrogate
            }
        } else if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd; // unpaired surrogate
        }

        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            bytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            bytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    // Delegate the MD5 computation to the library.
    const digest = lib.md5(new Uint8Array(bytes));

    // Convert the digest bytes to 32 lowercase hex characters.
    let hex = "";
    for (let i = 0; i < digest.length; i++) {
        hex += digest[i].toString(16).padStart(2, "0");
    }
    return hex;
}

const SCHEME_RE = /^https?:\/\//i;
const LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i;
const TLD_RE = /^(?:[a-z]{2,63}|xn--[a-z0-9-]{1,59})$/i;
const WHITESPACE_RE = /\s/;

/**
 * Extracts the hostname from an http(s) URL string without a port,
 * userinfo, or path. Returns null if the authority cannot be parsed
 * or is an IPv6 literal.
 */
function extractHost(url: string): string | null {
  const schemeMatch = SCHEME_RE.exec(url);
  if (!schemeMatch) return null;

  const rest = url.slice(schemeMatch[0].length);
  const authorityMatch = /^[^/?#]*/.exec(rest);
  let authority = authorityMatch ? authorityMatch[0] : '';

  const at = authority.lastIndexOf('@');
  if (at !== -1) {
    authority = authority.slice(at + 1);
  }

  if (authority.startsWith('[')) return null; // IPv6 literal, not a domain name

  const hostPort = /^([^:]*)(?::(\d{1,5}))?$/.exec(authority);
  if (!hostPort) return null;

  return hostPort[1].toLowerCase();
}

/**
 * Checks that a host is a fully qualified domain name:
 * at least two labels, valid label characters, and a valid TLD
 * (alphabetic, or an IDN punycode "xn--" form). Rejects "localhost"
 * and bare IP addresses.
 */
function isFullyQualifiedDomain(host: string): boolean {
  if (host.length === 0 || host.length > 253) return false;

  const labels = host.split('.');
  if (labels.length < 2) return false;

  for (const label of labels) {
    if (!LABEL_RE.test(label)) return false;
  }

  const tld = labels[labels.length - 1];
  return TLD_RE.test(tld);
}

export function solve(urls: string[]): string[] {
  const options = {
    protocols: ['http', 'https'],
    require_protocol: true,
    require_valid_protocol: true,
    require_tld: true,
    allow_underscores: false,
  };

  return urls.filter((url) => {
    if (typeof url !== 'string') return false;
    if (WHITESPACE_RE.test(url)) return false;
    if (!SCHEME_RE.test(url)) return false;
    if (!lib.isURL(url, options)) return false;

    const host = extractHost(url);
    if (host === null) return false;

    return isFullyQualifiedDomain(host);
  });
}

const OFFSET_TAIL = /(?:Z|[+-]\d{2}(?::?\d{2})?)$/i;

// The library's no-offset branch interprets wall-clock time in the local zone.
// Per the spec, a string without an offset is UTC, so append "Z" to force the
// explicit-offset branch, which yields the UTC instant.
function withUtcDefault(s: string): string {
  const delim = s.search(/[Tt ]/);
  if (delim === -1) {
    // Date-only string: no offset present.
    return s + "Z";
  }
  const timePart = s.slice(delim + 1);
  return OFFSET_TAIL.test(timePart) ? s : s + "Z";
}

export function solve(stamps: string[]): number[] {
  const results = stamps.map((s) => {
    if (typeof s !== "string") {
      throw new RangeError(`Invalid date: ${String(s)}`);
    }
    const t = lib.parseISO(withUtcDefault(s)).getTime();
    if (Number.isNaN(t)) {
      throw new RangeError(`Invalid date: ${s}`);
    }
    return t;
  });
  return results.sort((a, b) => a - b);
}

export function solve(a: string, b: string): boolean {
  try {
    // Range construction throws on malformed input; an invalid range matches no version.
    return lib.intersects(a, b);
  } catch {
    return false;
  }
}

export function solve(emails: string[]): string[] {
  const GMAIL_DOMAINS = new Set(['gmail.com', 'googlemail.com']);
  const OUTLOOK_DOMAINS = new Set(['outlook.com', 'hotmail.com', 'live.com']);

  // Gmail: strip +suffix, strip dots, lowercase, and map googlemail.com to gmail.com.
  const gmailOptions = {
    all_lowercase: true,
    gmail_remove_subaddress: true,
    gmail_remove_dots: true,
    gmail_convert_googlemaildotcom: true,
  };

  // Outlook / Hotmail / Live: strip +suffix and lowercase.
  const outlookOptions = {
    all_lowercase: true,
    outlookdotcom_remove_subaddress: true,
  };

  // Other domains: lowercase only. Disable every library rule that would
  // otherwise alter the local part or domain (iCloud, Yahoo, Yandex, and
  // the broader outlook list, which may include other domains such as msn.com).
  const plainOptions = {
    all_lowercase: true,
    icloud_remove_subaddress: false,
    outlookdotcom_remove_subaddress: false,
    yahoo_remove_subaddress: false,
    yandex_convert_yandexru: false,
  };

  const seen = new Set<string>();
  const result: string[] = [];

  for (const raw of emails) {
    const lower = raw.toLowerCase();
    const at = lower.lastIndexOf('@');
    const domain = at >= 0 ? lower.slice(at + 1) : '';

    let options: Record<string, unknown>;
    if (GMAIL_DOMAINS.has(domain)) {
      options = gmailOptions;
    } else if (OUTLOOK_DOMAINS.has(domain)) {
      options = outlookOptions;
    } else {
      options = plainOptions;
    }

    // lib.normalizeEmail returns false when the local part becomes empty
    // (e.g. "+tag@gmail.com"); fall back to the lowercased input in that case.
    const canonical = lib.normalizeEmail(lower, options);
    const key = typeof canonical === 'string' ? canonical : lower;

    if (!seen.has(key)) {
      seen.add(key);
      result.push(key);
    }
  }

  return result;
}

export function solve(range: string): string | null {
  if (typeof range !== 'string') {
    return null;
  }

  let result: any;
  try {
    result = lib.minVersion(range);
  } catch (_err) {
    // Invalid range expressions make the Range constructor throw.
    return null;
  }

  if (!result) {
    return null;
  }

  return result.version;
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  const known = new Set<string>(nodes);
  for (const [from, to] of edges) {
    if (!known.has(from) || !known.has(to)) {
      throw new Error(`Unknown node in edge [${JSON.stringify(from)}, ${JSON.stringify(to)}]`);
    }
  }
  // lib.toposort throws an Error on cyclic dependencies.
  return lib.toposort(nodes, edges);
}

export function solve(version: string, range: string): boolean {
  return Boolean(lib.gtr(version, range));
}

export function solve(epochMs: number): string {
  // A Date whose local-time getters report UTC fields and whose offset is 0,
  // so lib.formatISO emits UTC wall-clock values with a "Z" suffix
  // regardless of the host time zone.
  class UTCDate extends Date {
    getDate(): number { return this.getUTCDate(); }
    getMonth(): number { return this.getUTCMonth(); }
    getFullYear(): number { return this.getUTCFullYear(); }
    getHours(): number { return this.getUTCHours(); }
    getMinutes(): number { return this.getUTCMinutes(); }
    getSeconds(): number { return this.getUTCSeconds(); }
    getTimezoneOffset(): number { return 0; }
  }

  // Passing a function as `in` makes the library's toDate call it with the
  // input, so we get our UTCDate instead of a plain local-time Date.
  // Milliseconds are dropped because formatISO only emits h/m/s.
  return lib.formatISO(epochMs, {
    in: (value: unknown) => new UTCDate(Number(value)),
  });
}

function isStrictIPv4(s: string): boolean {
  const parts = s.split('.');
  if (parts.length !== 4) return false;
  for (const p of parts) {
    // Reject leading zeros ("01", "00") while allowing "0".
    if (!/^(0|[1-9][0-9]{0,2})$/.test(p)) return false;
    if (Number(p) > 255) return false;
  }
  return lib.isIP(s, { version: 4 });
}

// Validates an IPv6 address without a zone index.
function isIPv6Core(s: string): boolean {
  let body = s;
  if (s.includes('.')) {
    // Embedded dotted IPv4 must be the trailing part, with strict octets.
    const idx = s.lastIndexOf(':');
    const v4 = s.slice(idx + 1);
    if (!isStrictIPv4(v4)) return false;
    // Replace the IPv4 tail with two hex groups so lib.isIP checks the rest.
    body = s.slice(0, idx + 1) + '0:0';
  }
  return lib.isIP(body, { version: 6 });
}

function isIPv6(s: string): boolean {
  const pct = s.indexOf('%');
  if (pct === -1) return isIPv6Core(s);

  const addr = s.slice(0, pct);
  const zone = s.slice(pct + 1);
  if (!/^[A-Za-z0-9]+$/.test(zone)) return false;
  if (!isIPv6Core(addr)) return false;

  // Zone indices are only allowed on link-local addresses (fe80::/10).
  const first = addr.split(':')[0];
  if (!/^[0-9a-fA-F]{1,4}$/.test(first)) return false;
  return (parseInt(first, 16) & 0xffc0) === 0xfe80;
}

export function solve(text: string, version?: 4 | 6): boolean {
  if (version === undefined) return isStrictIPv4(text) || isIPv6(text);
  if (version === 4) return isStrictIPv4(text);
  if (version === 6) return isIPv6(text);
  return false;
}

export function solve(iban: string): boolean {
  const normalized = iban.replace(/[\s-]+/g, "").toUpperCase();
  return lib.isIBAN(normalized);
}

const UUID_CANONICAL_RE =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function solve(name: string, namespace: string): string {
    if (typeof namespace !== "string" || !UUID_CANONICAL_RE.test(namespace)) {
        throw new TypeError("Invalid namespace: expected a canonical UUID string");
    }
    return lib.v3(name, namespace.toLowerCase());
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  // Reject anything that is not a strict SemVer 2.0.0 version string
  // (e.g. leading "v", surrounding whitespace, or leading zeros).
  if (typeof version !== 'string' || !SEMVER_RE.test(version)) {
    return null;
  }
  return lib.inc(version, kind, id);
}

export function solve(versions: string[]): string[] {
  // lib.sort sorts in place, so sort a copy to leave the input untouched.
  const sorted = lib.sort([...versions], undefined);

  // Two versions have equal SemVer precedence exactly when their parts before '+' match.
  const precedenceKey = (v: string): string => {
    const plus = v.indexOf('+');
    return plus === -1 ? v : v.slice(0, plus);
  };

  // Equal-precedence versions are contiguous after sorting. Within each such run,
  // order by the full string, lexically, as the spec requires.
  const result: string[] = [];
  let i = 0;
  while (i < sorted.length) {
    const key = precedenceKey(sorted[i]);
    let j = i + 1;
    while (j < sorted.length && precedenceKey(sorted[j]) === key) {
      j++;
    }
    const group = sorted.slice(i, j);
    if (group.length > 1) {
      group.sort();
    }
    for (const v of group) {
      result.push(v);
    }
    i = j;
  }

  return result;
}

export function solve(text: string): string {
    // Manual UTF-8 encoding (no TextEncoder, since that is a browser/Node API).
    // Lone surrogates are replaced with U+FFFD, matching standard UTF-8 encoders.
    const out: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let c = text.charCodeAt(i);
        if (c >= 0xd800 && c <= 0xdbff) {
            const d = i + 1 < text.length ? text.charCodeAt(i + 1) : 0;
            if (i + 1 < text.length && d >= 0xdc00 && d <= 0xdfff) {
                c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00);
                i++;
            } else {
                c = 0xfffd;
            }
        } else if (c >= 0xdc00 && c <= 0xdfff) {
            c = 0xfffd;
        }

        if (c < 0x80) {
            out.push(c);
        } else if (c < 0x800) {
            out.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
        } else if (c < 0x10000) {
            out.push(
                0xe0 | (c >> 12),
                0x80 | ((c >> 6) & 0x3f),
                0x80 | (c & 0x3f)
            );
        } else {
            out.push(
                0xf0 | (c >> 18),
                0x80 | ((c >> 12) & 0x3f),
                0x80 | ((c >> 6) & 0x3f),
                0x80 | (c & 0x3f)
            );
        }
    }

    const digest: Uint8Array = lib.sha1(Uint8Array.from(out));

    let hex = "";
    for (let i = 0; i < digest.length; i++) {
        hex += digest[i].toString(16).padStart(2, "0");
    }
    return hex;
}

export function solve(text: string): string | null {
  const v = lib.coerce(text);
  if (v === null) {
    return null;
  }
  return `${v.major}.${v.minor}.${v.patch}`;
}

export function solve(isin: string): boolean {
  return lib.isISIN(isin);
}

export function solve(mac: string): boolean {
  // The library's colon/dash pattern uses a per-position class ([-:]),
  // so it accepts mixed separators. Reject any string containing both.
  if (mac.includes(':') && mac.includes('-')) {
    return false;
  }
  return lib.isMACAddress(mac);
}

export function solve(issn: string): boolean {
  if (typeof issn !== 'string') {
    return false;
  }
  return lib.isISSN(issn);
}

export function solve(text: string, version?: 4 | 6): boolean {
  const checkV4 = (): boolean => lib.isIP(text, { version: 4 });

  const checkV6 = (): boolean => {
    const pct = text.indexOf('%');
    if (pct === -1) {
      return lib.isIP(text, { version: 6 });
    }

    // Zone index: only valid after a link-local IPv6 address (fe80::/10).
    const addr = text.slice(0, pct);
    const zone = text.slice(pct + 1);

    if (!/^[A-Za-z0-9]+$/.test(zone)) {
      return false;
    }

    // The first group must be exactly 4 hex digits in the range fe80..febf.
    const firstGroup = addr.split(':')[0];
    if (!/^fe[89ab][0-9a-f]$/i.test(firstGroup)) {
      return false;
    }

    return lib.isIP(addr, { version: 6 });
  };

  if (version === 4) {
    return checkV4();
  }
  if (version === 6) {
    return checkV6();
  }
  return checkV4() || checkV6();
}

function normalize(isbn: string): string {
  return isbn.replace(/[\s-]+/g, "");
}

// lib.isISBN's ISBN-10 branch weights digit i (0-based) by (i + 1), so it
// checks digits 1..10 instead of the standard 10..1 and rejects valid ISBN-10s.
// ISBN-10 is therefore validated here; ISBN-13 is delegated to lib.isISBN.
function isValidIsbn10(s: string): boolean {
  if (!/^[0-9]{9}[0-9X]$/.test(s)) {
    return false;
  }
  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const c = s.charAt(i);
    const value = c === "X" ? 10 : Number(c);
    sum += (10 - i) * value;
  }
  return sum % 11 === 0;
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  const s = normalize(isbn);
  if (version === 10) {
    return isValidIsbn10(s);
  }
  if (version === 13) {
    return lib.isISBN(s, 13);
  }
  return isValidIsbn10(s) || lib.isISBN(s, 13);
}

export function solve(a: string, b: string): number {
    return lib.distance(a, b);
}

// Note: lib.isCreditCard is not used. Its built-in patterns don't implement
// this spec (e.g. they omit Discover 19-digit and 622126-622925 ranges, UnionPay,
// Diners 14-19 digits, and JCB 16-19 digits), and it doesn't expose its Luhn
// check on its own. So prefix/length rules and Luhn are implemented directly.

function prefixIn(d: string, width: number, lo: number, hi: number): boolean {
  if (d.length < width) return false;
  const p = Number(d.slice(0, width));
  return p >= lo && p <= hi;
}

function range(lo: number, hi: number): number[] {
  const out: number[] = [];
  for (let i = lo; i <= hi; i++) out.push(i);
  return out;
}

const issuers: Array<{ lengths: number[]; match: (d: string) => boolean }> = [
  // Visa
  { lengths: [13, 16, 19], match: (d) => d[0] === "4" },
  // Mastercard: 51-55 or 2221-2720
  {
    lengths: [16],
    match: (d) => prefixIn(d, 2, 51, 55) || prefixIn(d, 4, 2221, 2720),
  },
  // American Express: 34 or 37
  {
    lengths: [15],
    match: (d) => prefixIn(d, 2, 34, 34) || prefixIn(d, 2, 37, 37),
  },
  // Discover: 6011, 622126-622925, 644-649, 65
  {
    lengths: [16, 19],
    match: (d) =>
      prefixIn(d, 4, 6011, 6011) ||
      prefixIn(d, 6, 622126, 622925) ||
      prefixIn(d, 3, 644, 649) ||
      prefixIn(d, 2, 65, 65),
  },
  // Diners Club: 300-305, 36, 38
  {
    lengths: range(14, 19),
    match: (d) =>
      prefixIn(d, 3, 300, 305) || prefixIn(d, 2, 36, 36) || prefixIn(d, 2, 38, 38),
  },
  // JCB: 3528-3589
  { lengths: range(16, 19), match: (d) => prefixIn(d, 4, 3528, 3589) },
  // UnionPay: 62
  { lengths: range(16, 19), match: (d) => prefixIn(d, 2, 62, 62) },
];

function luhn(d: string): boolean {
  let sum = 0;
  let double = false;
  for (let i = d.length - 1; i >= 0; i--) {
    let n = d.charCodeAt(i) - 48;
    if (double) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    double = !double;
  }
  return sum % 10 === 0;
}

export function solve(card: string): boolean {
  const d = card.replace(/[ -]/g, "");
  if (!/^[0-9]+$/.test(d)) return false;
  const issuerOk = issuers.some(
    (i) => i.lengths.indexOf(d.length) !== -1 && i.match(d)
  );
  return issuerOk && luhn(d);
}

export function solve(doc: unknown, pointer: string): unknown {
  // The empty pointer refers to the whole document, including primitives.
  if (pointer === '') return doc;

  if (pointer[0] !== '/') {
    throw new Error('Invalid JSON Pointer: must be empty or start with "/".');
  }

  // lib.get throws on non-object roots and dereferences null, so guard here.
  // A non-empty pointer cannot resolve inside a primitive or null.
  if (doc === null || typeof doc !== 'object') return undefined;

  return lib.get(doc, pointer);
}

export function solve(text: string): boolean {
  // Optional single pair of parentheses wrapping the whole value.
  const hasOpen = text.startsWith("(");
  const hasClose = text.endsWith(")");
  if (hasOpen !== hasClose) return false;

  const inner = hasOpen ? text.slice(1, -1) : text;

  // No other parentheses allowed inside.
  if (inner.includes("(") || inner.includes(")")) return false;

  // Exactly one comma separates latitude and longitude.
  const comma = inner.indexOf(",");
  if (comma === -1 || comma !== inner.lastIndexOf(",")) return false;

  const latPart = inner.slice(0, comma);
  // Spaces are allowed only after the comma; strip them before validating.
  const longPart = inner.slice(comma + 1).replace(/^ +/, "");

  return lib.isLatLong(latPart + "," + longPart);
}

// `lib` is assumed to be in scope, as the task specifies.

type Ver = { major: number; minor: number; patch: number; pre: string[] };

function parseVersion(v: string): Ver {
  const m = /^[v=]?\s*(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?$/.exec(v.trim());
  if (!m) throw new Error(`Invalid semver version: ${v}`);
  return {
    major: Number(m[1]),
    minor: Number(m[2]),
    patch: Number(m[3]),
    pre: m[4] ? m[4].split('.') : [],
  };
}

const isNumericId = (s: string): boolean => /^\d+$/.test(s);

// Semver precedence for prerelease identifiers (release > prerelease).
function comparePre(a: string[], b: string[]): number {
  if (a.length === 0 && b.length === 0) return 0;
  if (a.length === 0) return 1;
  if (b.length === 0) return -1;
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const x = a[i];
    const y = b[i];
    const xn = isNumericId(x);
    const yn = isNumericId(y);
    let c = 0;
    if (xn && yn) {
      // numeric identifiers have no leading zeros, so length then lexical works
      c = x.length !== y.length ? x.length - y.length : (x < y ? -1 : x > y ? 1 : 0);
    } else if (xn) {
      c = -1;
    } else if (yn) {
      c = 1;
    } else {
      c = x < y ? -1 : x > y ? 1 : 0;
    }
    if (c !== 0) return c;
  }
  return Math.sign(a.length - b.length);
}

function compareVersions(p: Ver, q: Ver): number {
  if (p.major !== q.major) return p.major > q.major ? 1 : -1;
  if (p.minor !== q.minor) return p.minor > q.minor ? 1 : -1;
  if (p.patch !== q.patch) return p.patch > q.patch ? 1 : -1;
  return comparePre(p.pre, q.pre);
}

// Prerelease (low) -> release (high), with the cores differing or equal.
function fromPrereleaseToRelease(low: Ver, high: Ver): string {
  // Highest differing core part wins.
  if (low.major !== high.major) return 'major';
  if (low.minor !== high.minor) return 'minor';
  if (low.patch !== high.patch) return 'patch';

  // Cores are equal: classify by the lower version's lowest non-zero part.
  if (low.patch !== 0) return 'patch';
  if (low.minor !== 0) return 'minor';
  return 'major';
}

export function solve(a: string, b: string): string | null {
  // Library handles equality (ignoring build metadata) and the general cases.
  const base = lib.diff(a, b);
  if (base === null) return null;

  const pa = parseVersion(a);
  const pb = parseVersion(b);
  const aIsHigher = compareVersions(pa, pb) > 0;
  const low = aIsHigher ? pb : pa;
  const high = aIsHigher ? pa : pb;

  // The library's prerelease -> release special case diverges from the spec
  // (e.g. 1.0.0-1 -> 1.0.1 must be `patch`), so compute that case directly.
  if (low.pre.length > 0 && high.pre.length === 0) {
    return fromPrereleaseToRelease(low, high);
  }

  return base;
}

export function solve(emails: string[]): string[] {
  const seen = new Set<string>();
  const result: string[] = [];

  const GMAIL_DOMAINS = new Set(["gmail.com", "googlemail.com"]);
  const PLUS_ONLY_DOMAINS = new Set(["outlook.com", "hotmail.com", "live.com"]);

  for (const raw of emails) {
    const email = raw.toLowerCase();
    const at = email.lastIndexOf("@");

    let canonical: string;
    if (at < 0) {
      canonical = email;
    } else {
      let local = email.slice(0, at);
      let domain = email.slice(at + 1);

      if (GMAIL_DOMAINS.has(domain)) {
        const plus = local.indexOf("+");
        if (plus >= 0) {
          local = local.slice(0, plus);
        }
        local = local.replace(/\./g, "");
        domain = "gmail.com";
      } else if (PLUS_ONLY_DOMAINS.has(domain)) {
        const plus = local.indexOf("+");
        if (plus >= 0) {
          local = local.slice(0, plus);
        }
      }

      canonical = `${local}@${domain}`;
    }

    if (!seen.has(canonical)) {
      seen.add(canonical);
      result.push(canonical);
    }
  }

  return result;
}

export function solve(name: string): boolean {
  if (typeof name !== 'string' || name.length === 0) {
    return false;
  }

  // No trailing dot allowed
  if (name.endsWith('.')) {
    return false;
  }

  // Whole name at most 253 characters (code points)
  if ([...name].length > 253) {
    return false;
  }

  const labels = name.split('.');

  // At least two labels
  if (labels.length < 2) {
    return false;
  }

  // Each label: 1-63 chars, letters/digits/hyphens only, no leading/trailing hyphen
  const labelPattern = /^[\p{L}0-9-]+$/u;
  for (const label of labels) {
    const len = [...label].length;
    if (len < 1 || len > 63) {
      return false;
    }
    if (!labelPattern.test(label)) {
      return false;
    }
    if (label.startsWith('-') || label.endsWith('-')) {
      return false;
    }
  }

  // TLD: at least 2 chars, either all letters (international allowed) or punycode "xn--..."
  const tld = labels[labels.length - 1];
  const tldIsLetters = /^\p{L}{2,}$/u.test(tld);
  const tldIsPunycode = /^xn--[a-z0-9-]*$/i.test(tld);
  if (!tldIsLetters && !tldIsPunycode) {
    return false;
  }

  // Delegate the heavy lifting to the library. The TLD and length rules are
  // handled above, so those library checks are relaxed here to avoid
  // conflicting with the stricter rules already applied.
  return lib.isFQDN(name, {
    require_tld: false,
    allow_underscores: false,
    allow_trailing_dot: false,
    allow_numeric_tld: false,
    allow_wildcard: false,
    ignore_max_length: true,
  });
}

export function solve(code: string): boolean {
  if (typeof code !== "string" || !/^\d+$/.test(code)) return false;

  switch (code.length) {
    case 8:
    case 13:
      return lib.isEAN(code);

    case 14: {
      // GTIN-14 weights (from left, d0..d12): 3,1,3,1,...,3.
      // Fold d0 into a 13-digit EAN-13 body so lib.isEAN computes the same sum:
      //   t0 = (3*d0 + d1) % 10   (EAN-13 weight 1 at index 0)
      //   t1..t11 = d2..d12       (EAN-13 weights 3,1,... match GTIN-14 weights)
      //   t12 = d13               (check digit)
      const d0 = Number(code[0]);
      const d1 = Number(code[1]);
      const folded = String((3 * d0 + d1) % 10) + code.slice(2);
      return lib.isEAN(folded);
    }

    default:
      return false;
  }
}

type Key = string | number;
type Container = Record<Key, unknown>;

function isIndex(key: Key): boolean {
  if (typeof key === "number") return Number.isInteger(key) && key >= 0;
  return /^(0|[1-9]\d*)$/.test(key);
}

function parsePath(path: string): Key[] {
  const keys: Key[] = [];
  const token = /\.?([^.[\]]+)|\[(\d+)\]|\["([^"]*)"\]|\['([^']*)'\]/y;
  let pos = 0;
  while (pos < path.length) {
    token.lastIndex = pos;
    const m = token.exec(path);
    if (!m) {
      throw new SyntaxError(`Invalid path at position ${pos}: ${path}`);
    }
    if (m[1] !== undefined) {
      keys.push(m[1]);
    } else if (m[2] !== undefined) {
      keys.push(Number(m[2]));
    } else if (m[3] !== undefined) {
      keys.push(m[3]);
    } else {
      keys.push(m[4]);
    }
    pos = token.lastIndex;
  }
  return keys;
}

export function solve(
  obj: object,
  updates: [string | (string | number)[], unknown][]
): object {
  for (const [path, value] of updates) {
    const keys: Key[] = typeof path === "string" ? parsePath(path) : path.slice();
    if (keys.length === 0) {
      throw new RangeError("Update path must not be empty");
    }

    let current = obj as Container;
    for (let i = 0; i < keys.length - 1; i++) {
      const key = keys[i];
      const next = current[key];
      if (typeof next !== "object" || next === null) {
        current[key] = isIndex(keys[i + 1]) ? [] : {};
      }
      current = current[key] as Container;
    }

    current[keys[keys.length - 1]] = value;
  }
  return obj;
}

export function solve(word: string, dictionary: string[]): string {
  if (dictionary.length === 0) {
    return "";
  }

  let best = dictionary[0];
  let bestDist = levenshtein(word, best);

  for (let i = 1; i < dictionary.length; i++) {
    const candidate = dictionary[i];
    const d = levenshtein(word, candidate);
    if (d < bestDist) {
      bestDist = d;
      best = candidate;
    }
  }

  return best;
}

function levenshtein(a: string, b: string): number {
  const m = a.length;
  const n = b.length;

  let prev: number[] = new Array<number>(n + 1);
  let curr: number[] = new Array<number>(n + 1);

  for (let j = 0; j <= n; j++) {
    prev[j] = j;
  }

  for (let i = 1; i <= m; i++) {
    curr[0] = i;
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(
        prev[j] + 1,        // deletion
        curr[j - 1] + 1,    // insertion
        prev[j - 1] + cost  // substitution or match
      );
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[n];
}

export function solve(stamps: string[]): number[] {
  const MS_PER_DAY = 86_400_000;

  const PATTERN =
    /^(\d{4})(?:-(\d{2})-(\d{2})|-W(\d{2})-(\d)|-(\d{3}))(?:T(\d{2}):(\d{2})(?::(\d{2})(?:[.,](\d+))?)?(Z|[+-]\d{2}:\d{2})?)?$/;

  const fail = (input: unknown): never => {
    throw new RangeError(`Invalid ISO 8601 date: ${String(input)}`);
  };

  const isLeap = (y: number): boolean =>
    (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;

  const daysInMonth = (y: number, m: number): number =>
    [31, isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];

  // Days since 1970-01-01 for a proleptic Gregorian date (handles years 0-99 correctly).
  const dayNumber = (y: number, m: number, d: number): number => {
    const t = new Date(0);
    t.setUTCFullYear(y, m - 1, d);
    return Math.round(t.getTime() / MS_PER_DAY);
  };

  // ISO weekday: Monday = 1 ... Sunday = 7. 1970-01-01 (day 0) was a Thursday.
  const isoWeekday = (day: number): number => (((day + 3) % 7) + 7) % 7 + 1;

  // Day number of Monday of ISO week 1 of year y (week 1 contains January 4).
  const mondayOfWeek1 = (y: number): number => {
    const jan4 = dayNumber(y, 1, 4);
    return jan4 - (isoWeekday(jan4) - 1);
  };

  const weeksInYear = (y: number): number =>
    (mondayOfWeek1(y + 1) - mondayOfWeek1(y)) / 7;

  const parseOne = (input: unknown): number => {
    if (typeof input !== "string") return fail(input);
    const m = PATTERN.exec(input);
    if (!m) return fail(input);

    const [
      ,
      yStr,
      calMonth,
      calDay,
      weekStr,
      weekdayStr,
      ordStr,
      hourStr,
      minStr,
      secStr,
      fracStr,
      offsetStr,
    ] = m;

    const year = Number(yStr);
    let day: number;

    if (calMonth !== undefined) {
      const month = Number(calMonth);
      const dom = Number(calDay);
      if (month < 1 || month > 12) return fail(input);
      if (dom < 1 || dom > daysInMonth(year, month)) return fail(input);
      day = dayNumber(year, month, dom);
    } else if (weekStr !== undefined) {
      const week = Number(weekStr);
      const weekday = Number(weekdayStr);
      if (weekday < 1 || weekday > 7) return fail(input);
      if (week < 1 || week > weeksInYear(year)) return fail(input);
      day = mondayOfWeek1(year) + (week - 1) * 7 + (weekday - 1);
    } else {
      const ordinal = Number(ordStr);
      const daysInYear = isLeap(year) ? 366 : 365;
      if (ordinal < 1 || ordinal > daysInYear) return fail(input);
      day = dayNumber(year, 1, 1) + ordinal - 1;
    }

    let timeMs = 0;
    if (hourStr !== undefined) {
      const h = Number(hourStr);
      const mi = Number(minStr);
      const s = secStr !== undefined ? Number(secStr) : 0;
      const frac = fracStr ?? "";

      if (mi < 0 || mi > 59 || s < 0 || s > 59) return fail(input);

      let ms = 0;
      if (frac.length > 0) {
        ms = Number((frac + "00").slice(0, 3));
      }

      if (h === 24) {
        // ISO 8601 allows 24:00:00 as the end of the day.
        if (mi !== 0 || s !== 0 || ms !== 0) return fail(input);
      } else if (h < 0 || h > 23) {
        return fail(input);
      }

      timeMs = h * 3_600_000 + mi * 60_000 + s * 1_000 + ms;
    }

    let offsetMinutes = 0;
    if (offsetStr !== undefined && offsetStr !== "Z") {
      const sign = offsetStr[0] === "-" ? -1 : 1;
      const oh = Number(offsetStr.slice(1, 3));
      const om = Number(offsetStr.slice(4, 6));
      if (oh > 23 || om > 59) return fail(input);
      offsetMinutes = sign * (oh * 60 + om);
    }

    // Local time = UTC + offset, so UTC = local - offset. No offset means UTC.
    return day * MS_PER_DAY + timeMs - offsetMinutes * 60_000;
  };

  const results = stamps.map(parseOne);
  return results.sort((a, b) => a - b);
}

const URL_PATTERN =
  /^https?:\/\/(?:[A-Za-z0-9\-._~%!$&'()*+,;=]+(?::[A-Za-z0-9\-._~%!$&'()*+,;=]*)?@)?((?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+(?:[A-Za-z]{2,63}|xn--[A-Za-z0-9-]{1,59}))(?::(\d{1,5}))?(?:[/?#]\S*)?$/i;

export function solve(urls: string[]): string[] {
  return urls.filter((url) => {
    const match = URL_PATTERN.exec(url);
    if (!match) return false;
    const port = match[2];
    return port === undefined || Number(port) <= 65535;
  });
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  const index = new Map<string, number>();
  nodes.forEach((node, i) => {
    if (index.has(node)) {
      throw new Error(`Duplicate node: ${node}`);
    }
    index.set(node, i);
  });

  const adjacency: number[][] = nodes.map(() => []);
  const indegree: number[] = nodes.map(() => 0);

  for (const [from, to] of edges) {
    const fromIndex = index.get(from);
    const toIndex = index.get(to);
    if (fromIndex === undefined) {
      throw new Error(`Edge mentions unknown node: ${from}`);
    }
    if (toIndex === undefined) {
      throw new Error(`Edge mentions unknown node: ${to}`);
    }
    adjacency[fromIndex].push(toIndex);
    indegree[toIndex]++;
  }

  const queue: number[] = [];
  for (let i = 0; i < nodes.length; i++) {
    if (indegree[i] === 0) {
      queue.push(i);
    }
  }

  const result: string[] = [];
  let head = 0;
  while (head < queue.length) {
    const current = queue[head++];
    result.push(nodes[current]);
    for (const next of adjacency[current]) {
      indegree[next]--;
      if (indegree[next] === 0) {
        queue.push(next);
      }
    }
  }

  if (result.length !== nodes.length) {
    throw new Error("Edges contain a cycle");
  }

  return result;
}

export function solve(name: string, namespace: string): string {
  // Parse the namespace UUID into 16 bytes.
  const nsHex = namespace.replace(/-/g, "");
  if (!/^[0-9a-fA-F]{32}$/.test(nsHex)) {
    throw new Error("Invalid namespace UUID");
  }
  const nsBytes = new Uint8Array(16);
  for (let i = 0; i < 16; i++) {
    nsBytes[i] = parseInt(nsHex.substr(i * 2, 2), 16);
  }

  // Encode the name as UTF-8 manually (lone surrogates become U+FFFD).
  const nameBytesArr: number[] = [];
  for (let i = 0; i < name.length; i++) {
    let cp = name.codePointAt(i) as number;
    if (cp > 0xffff) i++;
    if (cp >= 0xd800 && cp <= 0xdfff) cp = 0xfffd;
    if (cp < 0x80) {
      nameBytesArr.push(cp);
    } else if (cp < 0x800) {
      nameBytesArr.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      nameBytesArr.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      nameBytesArr.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  // Message = namespace bytes || name bytes.
  const msg = new Uint8Array(16 + nameBytesArr.length);
  msg.set(nsBytes, 0);
  msg.set(nameBytesArr, 16);

  const digest = sha1(msg);

  // Set version (5) and RFC 4122 variant bits.
  const out = digest.slice(0, 16);
  out[6] = (out[6] & 0x0f) | 0x50;
  out[8] = (out[8] & 0x3f) | 0x80;

  // Format as lowercase 8-4-4-4-12.
  let hex = "";
  for (let i = 0; i < 16; i++) {
    hex += out[i].toString(16).padStart(2, "0");
    if (i === 3 || i === 5 || i === 7 || i === 9) hex += "-";
  }
  return hex;
}

function sha1(msg: Uint8Array): Uint8Array {
  const bitLen = msg.length * 8;
  const totalLen = Math.ceil((msg.length + 9) / 64) * 64;
  const data = new Uint8Array(totalLen);
  data.set(msg);
  data[msg.length] = 0x80;

  const view = new DataView(data.buffer);
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  view.setUint32(totalLen - 8, hi, false);
  view.setUint32(totalLen - 4, lo, false);

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  const w = new Uint32Array(80);

  const rotl = (x: number, n: number): number => (x << n) | (x >>> (32 - n));

  for (let off = 0; off < totalLen; off += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = view.getUint32(off + t * 4, false);
    }
    for (let t = 16; t < 80; t++) {
      w[t] = rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let t = 0; t < 80; t++) {
      let f: number;
      let k: number;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (rotl(a, 5) + f + e + k + w[t]) | 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) | 0;
    h1 = (h1 + b) | 0;
    h2 = (h2 + c) | 0;
    h3 = (h3 + d) | 0;
    h4 = (h4 + e) | 0;
  }

  const result = new Uint8Array(20);
  const rv = new DataView(result.buffer);
  rv.setUint32(0, h0 >>> 0, false);
  rv.setUint32(4, h1 >>> 0, false);
  rv.setUint32(8, h2 >>> 0, false);
  rv.setUint32(12, h3 >>> 0, false);
  rv.setUint32(16, h4 >>> 0, false);
  return result;
}

type TypedArrayCtor = new (buffer: ArrayBufferLike, byteOffset: number, length: number) => ArrayBufferView;

export function solve<T>(value: T): T {
  const seen = new Map<object, unknown>();
  return cloneValue(value, seen) as T;
}

function cloneValue(value: unknown, seen: Map<object, unknown>): unknown {
  // Primitives and functions are returned as-is (functions cannot be meaningfully copied).
  if (value === null || typeof value !== "object") {
    return value;
  }

  // Circular or repeated references map to the same copy.
  if (seen.has(value)) {
    return seen.get(value);
  }

  if (value instanceof Date) {
    const copy = new Date(value.getTime());
    seen.set(value, copy);
    return copy;
  }

  if (value instanceof RegExp) {
    const copy = new RegExp(value.source, value.flags);
    copy.lastIndex = value.lastIndex;
    seen.set(value, copy);
    return copy;
  }

  // ArrayBuffer and SharedArrayBuffer: slice(0) allocates a new buffer.
  if (
    value instanceof ArrayBuffer ||
    Object.prototype.toString.call(value) === "[object SharedArrayBuffer]"
  ) {
    const copy = (value as ArrayBuffer).slice(0);
    seen.set(value, copy);
    return copy;
  }

  // Typed arrays and DataViews: clone the underlying buffer through the same
  // `seen` map so views sharing a buffer still share one copied buffer.
  if (ArrayBuffer.isView(value)) {
    const buffer = cloneValue(value.buffer, seen) as ArrayBufferLike;
    let copy: ArrayBufferView;
    if (value instanceof DataView) {
      copy = new DataView(buffer, value.byteOffset, value.byteLength);
    } else {
      const Ctor = (value as object).constructor as TypedArrayCtor;
      copy = new Ctor(buffer, value.byteOffset, (value as unknown as ArrayLike<unknown>).length);
    }
    seen.set(value, copy);
    return copy;
  }

  if (value instanceof Map) {
    const copy = new Map<unknown, unknown>();
    seen.set(value, copy);
    for (const [k, v] of value) {
      copy.set(cloneValue(k, seen), cloneValue(v, seen));
    }
    return copy;
  }

  if (value instanceof Set) {
    const copy = new Set<unknown>();
    seen.set(value, copy);
    for (const v of value) {
      copy.add(cloneValue(v, seen));
    }
    return copy;
  }

  if (Array.isArray(value)) {
    const copy: unknown[] = new Array(value.length);
    seen.set(value, copy);
    const proto = Object.getPrototypeOf(value);
    if (proto !== Array.prototype) {
      Object.setPrototypeOf(copy, proto);
    }
    copyOwnProperties(value, copy, seen, ["length"]);
    return copy;
  }

  // Plain objects and other objects: preserve prototype, copy own properties
  // (string and symbol keys, with their descriptors) deeply.
  const copy = Object.create(Object.getPrototypeOf(value)) as object;
  seen.set(value, copy);
  copyOwnProperties(value, copy, seen);
  return copy;
}

function copyOwnProperties(
  source: object,
  target: object,
  seen: Map<object, unknown>,
  skip: PropertyKey[] = []
): void {
  for (const key of Reflect.ownKeys(source)) {
    if (skip.includes(key)) continue;
    const desc = Reflect.getOwnPropertyDescriptor(source, key);
    if (!desc) continue;
    if ("value" in desc) {
      desc.value = cloneValue(desc.value, seen);
    }
    Reflect.defineProperty(target, key, desc);
  }
}

const BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

function base64Value(ch: string): number {
  const idx = BASE64_ALPHABET.indexOf(ch);
  if (idx < 0 || ch.length !== 1) {
    throw new Error(`Invalid base64 character: ${JSON.stringify(ch)}`);
  }
  return idx;
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 length: must be a multiple of 4");
  }

  const out: number[] = [];
  const n = text.length;

  for (let i = 0; i < n; i += 4) {
    const isLast = i + 4 === n;

    const c0 = text.charAt(i);
    const c1 = text.charAt(i + 1);
    const c2 = text.charAt(i + 2);
    const c3 = text.charAt(i + 3);

    const pad2 = c2 === "=";
    const pad3 = c3 === "=";

    // '=' may only appear at the very end, and only as "==" or "=" in the last position.
    if (pad2 && !pad3) {
      throw new Error("Invalid base64 padding");
    }
    if ((pad2 || pad3) && !isLast) {
      throw new Error("Invalid base64 padding position");
    }
    if (c0 === "=" || c1 === "=") {
      throw new Error("Invalid base64 padding position");
    }

    const v0 = base64Value(c0);
    const v1 = base64Value(c1);
    const v2 = pad2 ? 0 : base64Value(c2);
    const v3 = pad3 ? 0 : base64Value(c3);

    const bits = (v0 << 18) | (v1 << 12) | (v2 << 6) | v3;

    out.push((bits >> 16) & 0xff);
    if (!pad2) {
      out.push((bits >> 8) & 0xff);
    }
    if (!pad3) {
      out.push(bits & 0xff);
    }
  }

  return out;
}

export function solve(epochMs: number): string {
  // Valid time range matches ECMAScript Date: ±8.64e15 ms. This also rejects NaN.
  if (!(Math.abs(epochMs) <= 8.64e15)) {
    throw new RangeError("Invalid time value");
  }

  const pad = (n: number, width: number): string => String(n).padStart(width, "0");

  // Whole seconds since epoch, flooring so that negative instants map to the
  // second that contains them (drops any sub-second part).
  const totalSec = Math.floor(epochMs / 1000);

  // Split into days and seconds-of-day (floor division keeps negatives correct).
  const days = Math.floor(totalSec / 86400);
  const secOfDay = totalSec - days * 86400;

  const hh = Math.floor(secOfDay / 3600);
  const mm = Math.floor((secOfDay % 3600) / 60);
  const ss = secOfDay % 60;

  // Civil date from days since 1970-01-01 (proleptic Gregorian calendar).
  const z = days + 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor(
    (doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365
  );
  let year = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const day = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const month = mp < 10 ? mp + 3 : mp - 9;
  if (month <= 2) {
    year += 1;
  }

  // Years 0000-9999 use 4 digits; otherwise use the expanded ISO form ±YYYYYY.
  const yearStr =
    year >= 0 && year <= 9999
      ? pad(year, 4)
      : (year < 0 ? "-" : "+") + pad(Math.abs(year), 6);

  return `${yearStr}-${pad(month, 2)}-${pad(day, 2)}T${pad(hh, 2)}:${pad(mm, 2)}:${pad(ss, 2)}Z`;
}

const MD5_S: number[] = [
  7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
  5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
  4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
  6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21
];

const MD5_K: number[] = (() => {
  const k: number[] = [];
  for (let i = 0; i < 64; i++) {
    k.push(Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296) | 0);
  }
  return k;
})();

function md5RotL(x: number, c: number): number {
  return (x << c) | (x >>> (32 - c));
}

function md5HexLE(x: number): string {
  let s = "";
  for (let k = 0; k < 4; k++) {
    const b = (x >>> (k * 8)) & 0xff;
    s += (b < 16 ? "0" : "") + b.toString(16);
  }
  return s;
}

function utf8Bytes(text: string): number[] {
  const out: number[] = [];
  let i = 0;
  while (i < text.length) {
    let cp = text.codePointAt(i) as number;
    i += cp > 0xffff ? 2 : 1;
    // Lone surrogates are replaced with U+FFFD (matching TextEncoder behavior).
    if (cp >= 0xd800 && cp <= 0xdfff) cp = 0xfffd;
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }
  return out;
}

export function solve(text: string): string {
  const bytes = utf8Bytes(text);
  const origLen = bytes.length;

  // Padding: 0x80, zeros until length ≡ 56 (mod 64), then 64-bit LE bit length.
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);

  const bitLenLo = (origLen * 8) >>> 0;
  const bitLenHi = Math.floor(origLen / 0x20000000) >>> 0;
  for (let k = 0; k < 4; k++) bytes.push((bitLenLo >>> (k * 8)) & 0xff);
  for (let k = 0; k < 4; k++) bytes.push((bitLenHi >>> (k * 8)) & 0xff);

  let a0 = 0x67452301 | 0;
  let b0 = 0xefcdab89 | 0;
  let c0 = 0x98badcfe | 0;
  let d0 = 0x10325476 | 0;

  const M: number[] = new Array<number>(16);

  for (let off = 0; off < bytes.length; off += 64) {
    for (let j = 0; j < 16; j++) {
      const p = off + j * 4;
      M[j] =
        bytes[p] |
        (bytes[p + 1] << 8) |
        (bytes[p + 2] << 16) |
        (bytes[p + 3] << 24);
    }

    let A = a0;
    let B = b0;
    let C = c0;
    let D = d0;

    for (let i = 0; i < 64; i++) {
      let F: number;
      let g: number;
      if (i < 16) {
        F = (B & C) | (~B & D);
        g = i;
      } else if (i < 32) {
        F = (D & B) | (~D & C);
        g = (5 * i + 1) % 16;
      } else if (i < 48) {
        F = B ^ C ^ D;
        g = (3 * i + 5) % 16;
      } else {
        F = C ^ (B | ~D);
        g = (7 * i) % 16;
      }

      F = (F + A + MD5_K[i] + M[g]) | 0;
      A = D;
      D = C;
      C = B;
      B = (B + md5RotL(F, MD5_S[i])) | 0;
    }

    a0 = (a0 + A) | 0;
    b0 = (b0 + B) | 0;
    c0 = (c0 + C) | 0;
    d0 = (d0 + D) | 0;
  }

  return md5HexLE(a0) + md5HexLE(b0) + md5HexLE(c0) + md5HexLE(d0);
}

export function solve(text: string): string | null {
  const re = /(?<!\d)(\d{1,16})(?!\d)(?:\.(\d{1,16})(?!\d))?(?:\.(\d{1,16})(?!\d))?/;
  const m = re.exec(text);
  if (!m) return null;
  const major = m[1];
  const minor = m[2] ?? "0";
  const patch = m[3] ?? "0";
  return `${major}.${minor}.${patch}`;
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

interface ParsedVersion {
  raw: string;
  core: [string, string, string];
  pre: string[] | null;
}

function cmpNumeric(a: string, b: string): number {
  // Valid semver numeric identifiers have no leading zeros, so compare by
  // length first, then lexically. This avoids precision loss for huge numbers.
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

function cmpPreIdent(a: string, b: string): number {
  const aNum = /^\d+$/.test(a);
  const bNum = /^\d+$/.test(b);
  if (aNum && bNum) return cmpNumeric(a, b);
  if (aNum) return -1; // numeric identifiers have lower precedence
  if (bNum) return 1;
  if (a === b) return 0;
  return a < b ? -1 : 1; // ASCII lexical comparison
}

function cmpPre(a: string[] | null, b: string[] | null): number {
  if (a === null && b === null) return 0;
  if (a === null) return 1; // release > prerelease
  if (b === null) return -1;

  const len = Math.min(a.length, b.length);
  for (let i = 0; i < len; i++) {
    const c = cmpPreIdent(a[i], b[i]);
    if (c !== 0) return c;
  }
  if (a.length === b.length) return 0;
  return a.length < b.length ? -1 : 1; // shorter list is lower
}

function compareVersions(a: ParsedVersion, b: ParsedVersion): number {
  for (let i = 0; i < 3; i++) {
    const c = cmpNumeric(a.core[i], b.core[i]);
    if (c !== 0) return c;
  }
  const p = cmpPre(a.pre, b.pre);
  if (p !== 0) return p;
  // Equal precedence: order by full string (build metadata) lexically.
  if (a.raw === b.raw) return 0;
  return a.raw < b.raw ? -1 : 1;
}

export function solve(versions: string[]): string[] {
  const parsed: ParsedVersion[] = [];
  for (const raw of versions) {
    const m = SEMVER_RE.exec(raw);
    if (!m) continue;
    parsed.push({
      raw,
      core: [m[1], m[2], m[3]],
      pre: m[4] === undefined ? null : m[4].split("."),
    });
  }
  parsed.sort(compareVersions);
  return parsed.map((p) => p.raw);
}

export function solve(text: string): string {
  // UTF-8 encode the input manually (no TextEncoder, no imports).
  const bytes: number[] = [];
  for (let i = 0; i < text.length; i++) {
    let cp = text.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < text.length) {
      const next = text.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
        i++;
      }
    }
    // Lone surrogates are replaced with U+FFFD, matching standard UTF-8 encoders.
    if (cp >= 0xd800 && cp <= 0xdfff) {
      cp = 0xfffd;
    }
    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  // Padding (FIPS 180-4 section 5.1.1).
  const len = bytes.length;
  const bitLen = len * 8;
  const total = Math.ceil((len + 9) / 64) * 64;
  const msg = new Uint8Array(total);
  msg.set(bytes);
  msg[len] = 0x80;

  const hi = Math.floor(bitLen / 4294967296);
  const lo = bitLen % 4294967296;
  // 64-bit big-endian message length in the final 8 bytes.
  msg[total - 8] = (hi >>> 24) & 0xff;
  msg[total - 7] = (hi >>> 16) & 0xff;
  msg[total - 6] = (hi >>> 8) & 0xff;
  msg[total - 5] = hi & 0xff;
  msg[total - 4] = (lo >>> 24) & 0xff;
  msg[total - 3] = (lo >>> 16) & 0xff;
  msg[total - 2] = (lo >>> 8) & 0xff;
  msg[total - 1] = lo & 0xff;

  const rotl = (x: number, n: number): number =>
    ((x << n) | (x >>> (32 - n))) >>> 0;

  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;

  const W = new Array<number>(80);

  for (let off = 0; off < total; off += 64) {
    for (let t = 0; t < 16; t++) {
      const j = off + t * 4;
      W[t] =
        ((msg[j] << 24) | (msg[j + 1] << 16) | (msg[j + 2] << 8) | msg[j + 3]) >>> 0;
    }
    for (let t = 16; t < 80; t++) {
      W[t] = rotl(W[t - 3] ^ W[t - 8] ^ W[t - 14] ^ W[t - 16], 1);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let t = 0; t < 80; t++) {
      let f: number;
      let k: number;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (rotl(a, 5) + (f >>> 0) + e + k + W[t]) >>> 0;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }

  const hex = (n: number): string => ("00000000" + (n >>> 0).toString(16)).slice(-8);
  return hex(h0) + hex(h1) + hex(h2) + hex(h3) + hex(h4);
}

type Version = {
  major: string;
  minor: string;
  patch: string;
  pre: string[];
};

function parseVersion(v: string): Version {
  const noBuild = v.split("+")[0];
  const dash = noBuild.indexOf("-");
  const core = dash === -1 ? noBuild : noBuild.slice(0, dash);
  const pre = dash === -1 ? [] : noBuild.slice(dash + 1).split(".");
  const [major, minor, patch] = core.split(".");
  return { major, minor, patch, pre };
}

// Compare non-negative integer strings without precision loss.
function cmpNum(a: string, b: string): number {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

function isNumeric(s: string): boolean {
  return /^\d+$/.test(s);
}

function comparePre(p: string[], q: string[]): number {
  if (p.length === 0 && q.length === 0) return 0;
  if (p.length === 0) return 1; // release > prerelease
  if (q.length === 0) return -1;

  const n = Math.min(p.length, q.length);
  for (let i = 0; i < n; i++) {
    if (p[i] === q[i]) continue;
    const pn = isNumeric(p[i]);
    const qn = isNumeric(q[i]);
    if (pn && qn) return cmpNum(p[i], q[i]);
    if (pn) return -1; // numeric identifiers have lower precedence
    if (qn) return 1;
    return p[i] < q[i] ? -1 : 1;
  }
  if (p.length === q.length) return 0;
  return p.length < q.length ? -1 : 1;
}

function compareVersions(x: Version, y: Version): number {
  let c = cmpNum(x.major, y.major);
  if (c !== 0) return c;
  c = cmpNum(x.minor, y.minor);
  if (c !== 0) return c;
  c = cmpNum(x.patch, y.patch);
  if (c !== 0) return c;
  return comparePre(x.pre, y.pre);
}

export function solve(a: string, b: string): string | null {
  const x = parseVersion(a);
  const y = parseVersion(b);
  const c = compareVersions(x, y);
  if (c === 0) return null;

  const lo = c < 0 ? x : y;
  const hi = c < 0 ? y : x;

  const loPre = lo.pre.length > 0;
  const hiPre = hi.pre.length > 0;

  const majorDiff = cmpNum(lo.major, hi.major) !== 0;
  const minorDiff = cmpNum(lo.minor, hi.minor) !== 0;
  const patchDiff = cmpNum(lo.patch, hi.patch) !== 0;
  const coresEqual = !majorDiff && !minorDiff && !patchDiff;

  if (loPre && !hiPre) {
    // Prerelease -> release: a major-level change when lower minor and patch are 0
    if (lo.minor === "0" && lo.patch === "0") {
      return "major";
    }
    // Same core: classify by the lower's shape
    if (coresEqual) {
      return lo.minor !== "0" && lo.patch === "0" ? "minor" : "patch";
    }
  }

  const prefix = hiPre ? "pre" : "";

  if (majorDiff) return prefix + "major";
  if (minorDiff) return prefix + "minor";
  if (patchDiff) return prefix + "patch";

  return "prerelease";
}

type Kind =
  | 'major'
  | 'minor'
  | 'patch'
  | 'premajor'
  | 'preminor'
  | 'prepatch'
  | 'prerelease';

// Semver 2.0.0 grammar, written as regex sources.
const NUM = '(?:0|[1-9]\\d*)';
const PRE_ID = '(?:0|[1-9]\\d*|\\d*[a-zA-Z-][0-9a-zA-Z-]*)';
const BUILD_ID = '[0-9a-zA-Z-]+';

const VERSION_RE = new RegExp(
  `^(${NUM})\\.(${NUM})\\.(${NUM})` +
    `(?:-(${PRE_ID}(?:\\.${PRE_ID})*))?` +
    `(?:\\+${BUILD_ID}(?:\\.${BUILD_ID})*)?$`
);
const PRE_LIST_RE = new RegExp(`^${PRE_ID}(?:\\.${PRE_ID})*$`);
const NUMERIC_RE = /^(?:0|[1-9]\d*)$/;

/** Increments a non-negative decimal string without losing precision. */
function incDecimal(s: string): string {
  const d = s.split('');
  let i = d.length - 1;
  while (i >= 0) {
    if (d[i] === '9') {
      d[i] = '0';
      i--;
    } else {
      d[i] = String.fromCharCode(d[i].charCodeAt(0) + 1);
      return d.join('');
    }
  }
  return '1' + d.join('');
}

interface Parsed {
  major: string;
  minor: string;
  patch: string;
  pre: string[];
}

function parse(version: string): Parsed | null {
  const m = VERSION_RE.exec(version);
  if (!m) return null;
  return {
    major: m[1],
    minor: m[2],
    patch: m[3],
    pre: m[4] !== undefined ? m[4].split('.') : [],
  };
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  const v = parse(version);
  if (!v) return null;

  if (id !== undefined && id !== '' && !PRE_LIST_RE.test(id)) return null;

  const idParts: string[] = id ? id.split('.') : [];
  let { major, minor, patch, pre } = v;
  const hasPre = pre.length > 0;
  const isZero = (s: string) => s === '0';

  // Prerelease created from scratch: "<id>.0" or "0" when no id is given.
  const freshPre = (): string[] => (idParts.length ? [...idParts, '0'] : ['0']);

  switch (kind as Kind) {
    case 'major':
      if (hasPre && isZero(minor) && isZero(patch)) {
        // Release only: 1.0.0-beta -> 1.0.0
        pre = [];
      } else {
        major = incDecimal(major);
        minor = '0';
        patch = '0';
        pre = [];
      }
      break;

    case 'minor':
      if (hasPre && isZero(patch)) {
        // Release only: 1.2.0-beta -> 1.2.0
        pre = [];
      } else {
        minor = incDecimal(minor);
        patch = '0';
        pre = [];
      }
      break;

    case 'patch':
      if (hasPre) {
        // Release only: 1.2.3-beta.1 -> 1.2.3
        pre = [];
      } else {
        patch = incDecimal(patch);
      }
      break;

    case 'premajor':
      major = incDecimal(major);
      minor = '0';
      patch = '0';
      pre = freshPre();
      break;

    case 'preminor':
      minor = incDecimal(minor);
      patch = '0';
      pre = freshPre();
      break;

    case 'prepatch':
      patch = incDecimal(patch);
      pre = freshPre();
      break;

    case 'prerelease': {
      if (!hasPre) {
        patch = incDecimal(patch);
        pre = freshPre();
        break;
      }

      const sameId =
        idParts.length === 0 ||
        (pre.length >= idParts.length &&
          idParts.every((part, i) => pre[i] === part));

      if (!sameId) {
        pre = freshPre();
        break;
      }

      // Same id: increment the last numeric identifier, or append 0 if none.
      let found = false;
      const next = [...pre];
      for (let i = next.length - 1; i >= 0; i--) {
        if (NUMERIC_RE.test(next[i])) {
          next[i] = incDecimal(next[i]);
          found = true;
          break;
        }
      }
      if (!found) next.push('0');
      pre = next;
      break;
    }

    default:
      return null;
  }

  let result = `${major}.${minor}.${patch}`;
  if (pre.length > 0) result += '-' + pre.join('.');
  return result;
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  // Remove spaces and hyphens
  const s = isbn.replace(/[ -]/g, "");

  const isValidIsbn10 = (): boolean => {
    // 9 digits followed by a digit or uppercase 'X' (only valid as the check character)
    if (!/^[0-9]{9}[0-9X]$/.test(s)) return false;

    let sum = 0;
    for (let i = 0; i < 10; i++) {
      const c = s[i];
      const d = c === "X" ? 10 : c.charCodeAt(0) - 48;
      sum += (10 - i) * d;
    }
    return sum % 11 === 0;
  };

  const isValidIsbn13 = (): boolean => {
    if (!/^[0-9]{13}$/.test(s)) return false;

    let sum = 0;
    for (let i = 0; i < 13; i++) {
      const d = s.charCodeAt(i) - 48;
      sum += i % 2 === 0 ? d : 3 * d;
    }
    return sum % 10 === 0;
  };

  if (version === 10) return isValidIsbn10();
  if (version === 13) return isValidIsbn13();
  return isValidIsbn10() || isValidIsbn13();
}

export function solve(name: string, namespace: string): string {
  if (typeof name !== "string") {
    throw new TypeError("name must be a string");
  }
  if (
    typeof namespace !== "string" ||
    !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(namespace)
  ) {
    throw new TypeError("namespace is not a valid UUID");
  }

  // Parse namespace UUID into 16 bytes.
  const nsHex = namespace.replace(/-/g, "");
  const nsBytes: number[] = [];
  for (let i = 0; i < 32; i += 2) {
    nsBytes.push(parseInt(nsHex.slice(i, i + 2), 16));
  }

  // UTF-8 encode the name manually (lone surrogates become U+FFFD, as TextEncoder does).
  const nameBytes: number[] = [];
  for (const ch of name) {
    let cp = ch.codePointAt(0) as number;
    if (cp >= 0xd800 && cp <= 0xdfff) {
      cp = 0xfffd;
    }
    if (cp < 0x80) {
      nameBytes.push(cp);
    } else if (cp < 0x800) {
      nameBytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      nameBytes.push(
        0xe0 | (cp >> 12),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    } else {
      nameBytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  const digest = md5(nsBytes.concat(nameBytes));

  // Set version (3) and variant (RFC 4122).
  digest[6] = (digest[6] & 0x0f) | 0x30;
  digest[8] = (digest[8] & 0x3f) | 0x80;

  const hex: string[] = [];
  for (let i = 0; i < 16; i++) {
    hex.push(digest[i].toString(16).padStart(2, "0"));
  }
  const h = hex.join("");
  return (
    h.slice(0, 8) + "-" +
    h.slice(8, 12) + "-" +
    h.slice(12, 16) + "-" +
    h.slice(16, 20) + "-" +
    h.slice(20, 32)
  );
}

function md5(msg: number[]): number[] {
  const K: number[] = [];
  for (let i = 0; i < 64; i++) {
    K[i] = Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296) | 0;
  }
  const S = [
    7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
    5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,
    4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
    6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
  ];

  // Padding
  const bitLenLow = (msg.length * 8) >>> 0;
  const bitLenHigh = Math.floor(msg.length / 0x20000000) >>> 0;
  const data = msg.slice();
  data.push(0x80);
  while (data.length % 64 !== 56) {
    data.push(0);
  }
  for (let i = 0; i < 4; i++) data.push((bitLenLow >>> (8 * i)) & 0xff);
  for (let i = 0; i < 4; i++) data.push((bitLenHigh >>> (8 * i)) & 0xff);

  let a0 = 0x67452301 | 0;
  let b0 = 0xefcdab89 | 0;
  let c0 = 0x98badcfe | 0;
  let d0 = 0x10325476 | 0;

  for (let off = 0; off < data.length; off += 64) {
    const M: number[] = [];
    for (let j = 0; j < 16; j++) {
      const p = off + j * 4;
      M[j] =
        (data[p] | (data[p + 1] << 8) | (data[p + 2] << 16) | (data[p + 3] << 24)) | 0;
    }

    let A = a0;
    let B = b0;
    let C = c0;
    let D = d0;

    for (let i = 0; i < 64; i++) {
      let F: number;
      let g: number;
      if (i < 16) {
        F = (B & C) | (~B & D);
        g = i;
      } else if (i < 32) {
        F = (D & B) | (~D & C);
        g = (5 * i + 1) % 16;
      } else if (i < 48) {
        F = B ^ C ^ D;
        g = (3 * i + 5) % 16;
      } else {
        F = C ^ (B | ~D);
        g = (7 * i) % 16;
      }
      F = (F + A + K[i] + M[g]) | 0;
      A = D;
      D = C;
      C = B;
      const s = S[i];
      B = (B + ((F << s) | (F >>> (32 - s)))) | 0;
    }

    a0 = (a0 + A) | 0;
    b0 = (b0 + B) | 0;
    c0 = (c0 + C) | 0;
    d0 = (d0 + D) | 0;
  }

  const out: number[] = [];
  for (const w of [a0, b0, c0, d0]) {
    for (let i = 0; i < 4; i++) {
      out.push((w >>> (8 * i)) & 0xff);
    }
  }
  return out;
}

type Op = '<' | '<=' | '>' | '>=' | '=';

interface Version {
  major: number;
  minor: number;
  patch: number;
  pre: string[];
}

interface Comparator {
  op: Op;
  v: Version;
}

interface Loose {
  major?: number;
  minor?: number;
  patch?: number;
  pre: string[];
}

const ID_RE = /^[0-9A-Za-z-]+$/;
const NUMERIC_RE = /^\d+$/;
const ZERO = ['0'];

function validIds(s: string, strictNumeric: boolean): string[] | null {
  const ids = s.split('.');
  for (const id of ids) {
    if (!ID_RE.test(id)) return null;
    if (strictNumeric && NUMERIC_RE.test(id) && id.length > 1 && id[0] === '0') return null;
  }
  return ids;
}

function parseVersion(input: string): Version | null {
  const m = /^\s*[v=]*\s*(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?\s*$/.exec(input);
  if (!m) return null;
  for (const n of [m[1], m[2], m[3]]) {
    if (n.length > 1 && n[0] === '0') return null;
  }
  let pre: string[] = [];
  if (m[4] !== undefined) {
    const ids = validIds(m[4], true);
    if (!ids) return null;
    pre = ids;
  }
  if (m[5] !== undefined && validIds(m[5], false) === null) return null;
  return { major: Number(m[1]), minor: Number(m[2]), patch: Number(m[3]), pre };
}

function compareIds(a: string, b: string): number {
  const an = NUMERIC_RE.test(a);
  const bn = NUMERIC_RE.test(b);
  if (an && bn) {
    if (a.length !== b.length) return a.length - b.length;
    return a < b ? -1 : a > b ? 1 : 0;
  }
  if (an) return -1;
  if (bn) return 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

function compareVersions(a: Version, b: Version): number {
  if (a.major !== b.major) return a.major < b.major ? -1 : 1;
  if (a.minor !== b.minor) return a.minor < b.minor ? -1 : 1;
  if (a.patch !== b.patch) return a.patch < b.patch ? -1 : 1;
  if (a.pre.length === 0 && b.pre.length === 0) return 0;
  if (a.pre.length === 0) return 1;
  if (b.pre.length === 0) return -1;
  const n = Math.min(a.pre.length, b.pre.length);
  for (let i = 0; i < n; i++) {
    const c = compareIds(a.pre[i], b.pre[i]);
    if (c !== 0) return c;
  }
  if (a.pre.length === b.pre.length) return 0;
  return a.pre.length < b.pre.length ? -1 : 1;
}

function parseLoose(s: string): Loose | null {
  const m = /^v?(\d+|[xX*])(?:\.(\d+|[xX*]))?(?:\.(\d+|[xX*]))?(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?$/.exec(s);
  if (!m) return null;
  const num = (x: string | undefined): number | undefined =>
    x === undefined || /^[xX*]$/.test(x) ? undefined : Number(x);
  const major = num(m[1]);
  const minor = major === undefined ? undefined : num(m[2]);
  const patch = minor === undefined ? undefined : num(m[3]);
  let pre: string[] = [];
  if (patch !== undefined && m[4] !== undefined) {
    const ids = validIds(m[4], true);
    if (!ids) return null;
    pre = ids;
  }
  return { major, minor, patch, pre };
}

function cmp(op: Op, major: number, minor: number, patch: number, pre: string[] = []): Comparator {
  return { op, v: { major, minor, patch, pre } };
}

// Returns [] for "any version", null for invalid input.
function opToComparators(op: string, p: Loose): Comparator[] | null {
  const M = p.major;
  const m = p.minor;
  const pt = p.patch;
  const pre = p.pre;

  if (M === undefined) {
    return op === '<' || op === '>' ? [cmp('<', 0, 0, 0, ZERO)] : [];
  }

  switch (op) {
    case '':
    case '=': {
      if (m === undefined) return [cmp('>=', M, 0, 0), cmp('<', M + 1, 0, 0, ZERO)];
      if (pt === undefined) return [cmp('>=', M, m, 0), cmp('<', M, m + 1, 0, ZERO)];
      return [cmp('=', M, m, pt, pre)];
    }
    case '>': {
      if (m === undefined) return [cmp('>=', M + 1, 0, 0)];
      if (pt === undefined) return [cmp('>=', M, m + 1, 0)];
      return [cmp('>', M, m, pt, pre)];
    }
    case '>=': {
      if (m === undefined) return [cmp('>=', M, 0, 0)];
      if (pt === undefined) return [cmp('>=', M, m, 0)];
      return [cmp('>=', M, m, pt, pre)];
    }
    case '<': {
      if (m === undefined) return [cmp('<', M, 0, 0, ZERO)];
      if (pt === undefined) return [cmp('<', M, m, 0, ZERO)];
      return [cmp('<', M, m, pt, pre)];
    }
    case '<=': {
      if (m === undefined) return [cmp('<', M + 1, 0, 0, ZERO)];
      if (pt === undefined) return [cmp('<', M, m + 1, 0, ZERO)];
      return [cmp('<=', M, m, pt, pre)];
    }
    case '~':
    case '~>': {
      if (m === undefined) return [cmp('>=', M, 0, 0), cmp('<', M + 1, 0, 0, ZERO)];
      if (pt === undefined) return [cmp('>=', M, m, 0), cmp('<', M, m + 1, 0, ZERO)];
      return [cmp('>=', M, m, pt, pre), cmp('<', M, m + 1, 0, ZERO)];
    }
    case '^': {
      const lo = cmp('>=', M, m ?? 0, pt ?? 0, pre);
      let hi: Comparator;
      if (M > 0 || m === undefined) {
        hi = cmp('<', M + 1, 0, 0, ZERO);
      } else if (m > 0 || pt === undefined) {
        hi = cmp('<', 0, m + 1, 0, ZERO);
      } else {
        hi = cmp('<', 0, 0, pt + 1, ZERO);
      }
      return [lo, hi];
    }
    default:
      return null;
  }
}

function hyphenComparators(a: string, b: string): Comparator[] | null {
  const lo = parseLoose(a);
  const hi = parseLoose(b);
  if (!lo || !hi) return null;
  const out: Comparator[] = [];
  if (lo.major !== undefined) {
    out.push(cmp('>=', lo.major, lo.minor ?? 0, lo.patch ?? 0, lo.pre));
  }
  if (hi.major !== undefined) {
    const M = hi.major;
    const m = hi.minor;
    const pt = hi.patch;
    if (m === undefined) {
      out.push(cmp('<', M + 1, 0, 0, ZERO));
    } else if (pt === undefined) {
      out.push(cmp('<', M, m + 1, 0, ZERO));
    } else {
      out.push(cmp('<=', M, m, pt, hi.pre));
    }
  }
  return out;
}

function parseSet(text: string): Comparator[] | null {
  const s = text.trim();
  if (s === '') return [];

  const hy = /^(\S+)\s+-\s+(\S+)$/.exec(s);
  if (hy) return hyphenComparators(hy[1], hy[2]);

  const tokens = s.split(/\s+/);
  const out: Comparator[] = [];
  for (let i = 0; i < tokens.length; i++) {
    let term = tokens[i];
    // Allow an operator separated from its version by whitespace.
    if (/^(<=|>=|<|>|=|~>|~|\^)$/.test(term) && i + 1 < tokens.length) {
      term += tokens[++i];
    }
    const tm = /^(<=|>=|<|>|=|~>|~|\^)?(.*)$/.exec(term);
    if (!tm) return null;
    const p = parseLoose(tm[2]);
    if (!p) return null;
    const comps = opToComparators(tm[1] ?? '', p);
    if (!comps) return null;
    out.push(...comps);
  }
  return out;
}

function parseRange(range: string): Comparator[][] | null {
  const sets: Comparator[][] = [];
  for (const alt of range.split('||')) {
    const set = parseSet(alt);
    if (!set) return null;
    sets.push(set);
  }
  return sets;
}

function matchesComparator(c: Comparator, v: Version): boolean {
  const r = compareVersions(v, c.v);
  switch (c.op) {
    case '<': return r < 0;
    case '<=': return r <= 0;
    case '>': return r > 0;
    case '>=': return r >= 0;
    case '=': return r === 0;
    default: return false;
  }
}

function matchesSet(v: Version, set: Comparator[]): boolean {
  if (v.pre.length > 0) {
    // A prerelease only matches if the set names a prerelease on the same major.minor.patch.
    const allowed = set.some(
      (c) =>
        c.v.pre.length > 0 &&
        c.v.major === v.major &&
        c.v.minor === v.minor &&
        c.v.patch === v.patch
    );
    if (!allowed) return false;
  }
  return set.every((c) => matchesComparator(c, v));
}

export function solve(installed: string[], range: string): string | null {
  const sets = parseRange(range);
  if (!sets) return null;

  let best: string | null = null;
  let bestVer: Version | null = null;

  for (const raw of installed) {
    if (typeof raw !== 'string') continue;
    const v = parseVersion(raw);
    if (!v) continue;
    if (!sets.some((set) => matchesSet(v, set))) continue;
    if (bestVer === null || compareVersions(v, bestVer) > 0) {
      best = raw;
      bestVer = v;
    }
  }

  return best;
}

export function solve(card: string): boolean {
  // Ignore spaces and hyphens; anything else must be a digit.
  const digits = card.replace(/[\s-]/g, "");
  if (!/^\d+$/.test(digits)) return false;

  // True if the leading digits of d fall within [lo, hi].
  // lo and hi must be digit strings of equal length.
  const prefixInRange = (d: string, lo: string, hi: string): boolean => {
    const n = lo.length;
    if (d.length < n) return false;
    const p = d.slice(0, n);
    return p >= lo && p <= hi;
  };

  const range = (lo: number, hi: number): number[] =>
    Array.from({ length: hi - lo + 1 }, (_, i) => lo + i);

  interface Rule {
    matches: (d: string) => boolean;
    lengths: number[];
  }

  const rules: Rule[] = [
    // Visa
    {
      matches: (d) => d.startsWith("4"),
      lengths: [13, 16, 19],
    },
    // Mastercard: 51–55 or 2221–2720
    {
      matches: (d) =>
        prefixInRange(d, "51", "55") || prefixInRange(d, "2221", "2720"),
      lengths: [16],
    },
    // American Express
    {
      matches: (d) => d.startsWith("34") || d.startsWith("37"),
      lengths: [15],
    },
    // Discover: 6011, 622126–622925, 644–649, 65
    {
      matches: (d) =>
        d.startsWith("6011") ||
        prefixInRange(d, "622126", "622925") ||
        prefixInRange(d, "644", "649") ||
        d.startsWith("65"),
      lengths: [16, 19],
    },
    // Diners Club: 300–305, 36, 38
    {
      matches: (d) =>
        prefixInRange(d, "300", "305") ||
        d.startsWith("36") ||
        d.startsWith("38"),
      lengths: range(14, 19),
    },
    // JCB: 3528–3589
    {
      matches: (d) => prefixInRange(d, "3528", "3589"),
      lengths: range(16, 19),
    },
    // UnionPay: 62
    {
      matches: (d) => d.startsWith("62"),
      lengths: range(16, 19),
    },
  ];

  const issuerOk = rules.some(
    (r) => r.lengths.includes(digits.length) && r.matches(digits)
  );
  if (!issuerOk) return false;

  // Luhn checksum
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = digits.charCodeAt(i) - 48;
    if (double) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    double = !double;
  }

  return sum % 10 === 0;
}

export function solve(isin: string): boolean {
  if (typeof isin !== "string" || !/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) {
    return false;
  }

  // Convert letters to numbers (A=10 ... Z=35), keeping digits as-is.
  let digits = "";
  for (let i = 0; i < isin.length; i++) {
    const code = isin.charCodeAt(i);
    if (code >= 65 && code <= 90) {
      digits += String(code - 55); // 'A' (65) -> 10, 'Z' (90) -> 35
    } else {
      digits += isin[i];
    }
  }

  // Luhn check over the full digit string (including the check digit).
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48;
    if (double) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    double = !double;
  }

  return sum % 10 === 0;
}

export function solve(mac: string): boolean {
  // Cisco dotted form: three or four groups of four hex digits
  if (/^[0-9a-fA-F]{4}(\.[0-9a-fA-F]{4}){2,3}$/.test(mac)) {
    return true;
  }

  // Colon or hyphen form: six (EUI-48) or eight (EUI-64) groups of two hex digits
  let sep: string;
  if (mac.includes(":")) {
    sep = ":";
  } else if (mac.includes("-")) {
    sep = "-";
  } else {
    return false;
  }

  const parts = mac.split(sep);
  if (parts.length !== 6 && parts.length !== 8) {
    return false;
  }

  // Any mixed separator would leave a non-hex part (e.g. "01-23") and fail here
  return parts.every((p) => /^[0-9a-fA-F]{2}$/.test(p));
}

const DEC_OCTET = /^(0|[1-9][0-9]{0,2})$/;
const HEX_GROUP = /^[0-9A-Fa-f]{1,4}$/;
const ZONE_ID = /^[A-Za-z0-9]+$/;

function isIPv4(s: string): boolean {
  const parts = s.split(".");
  if (parts.length !== 4) return false;
  return parts.every((p) => DEC_OCTET.test(p) && Number(p) <= 255);
}

/**
 * Validates an IPv6 address without zone index.
 * Returns whether it is valid and the value of its first 16-bit group.
 */
function parseIPv6(addr: string): { ok: boolean; first: number } {
  const fail = { ok: false, first: 0 };

  let s = addr;

  // Handle an optional trailing dotted IPv4 address (occupies last two groups).
  const lastColon = s.lastIndexOf(":");
  if (lastColon < 0) return fail;
  const tail = s.slice(lastColon + 1);
  if (tail.includes(".")) {
    if (!isIPv4(tail)) return fail;
    s = s.slice(0, lastColon + 1) + "0:0";
  }

  // At most one "::" is allowed.
  const dc = s.indexOf("::");
  if (dc !== s.lastIndexOf("::")) return fail;

  let first: string;

  if (dc >= 0) {
    const left = s.slice(0, dc);
    const right = s.slice(dc + 2);
    const l = left === "" ? [] : left.split(":");
    const r = right === "" ? [] : right.split(":");

    // "::" must stand for at least one zero group.
    if (l.length + r.length > 7) return fail;

    const all = [...l, ...r];
    if (!all.every((g) => HEX_GROUP.test(g))) return fail;

    first = l.length > 0 ? l[0] : "0";
  } else {
    const groups = s.split(":");
    if (groups.length !== 8) return fail;
    if (!groups.every((g) => HEX_GROUP.test(g))) return fail;
    first = groups[0];
  }

  return { ok: true, first: parseInt(first, 16) };
}

function isIPv6(text: string): boolean {
  const pct = text.indexOf("%");
  let addr = text;
  let zone: string | undefined;

  if (pct >= 0) {
    addr = text.slice(0, pct);
    zone = text.slice(pct + 1);
    if (!ZONE_ID.test(zone)) return false;
  }

  const result = parseIPv6(addr);
  if (!result.ok) return false;

  // A zone index is only permitted on link-local addresses (fe80::/10).
  if (zone !== undefined) {
    return (result.first & 0xffc0) === 0xfe80;
  }

  return true;
}

export function solve(text: string, version?: 4 | 6): boolean {
  if (version === undefined || version === 4) {
    if (isIPv4(text)) return true;
  }
  if (version === undefined || version === 6) {
    return isIPv6(text);
  }
  return false;
}

export function solve(code: string): boolean {
  if (!/^[0-9]+$/.test(code)) return false;

  const len = code.length;
  if (len !== 8 && len !== 13 && len !== 14) return false;

  let sum = 0;
  for (let i = 0; i < len - 1; i++) {
    const digit = code.charCodeAt(i) - 48;
    const posFromCheck = len - 1 - i; // rightmost data digit has position 1
    const weight = posFromCheck % 2 === 1 ? 3 : 1;
    sum += digit * weight;
  }

  const expectedCheck = (10 - (sum % 10)) % 10;
  const actualCheck = code.charCodeAt(len - 1) - 48;

  return expectedCheck === actualCheck;
}

export function solve(text: string): boolean {
  let body = text;
  if (text.length >= 2 && text.startsWith("(") && text.endsWith(")")) {
    body = text.slice(1, -1);
  }
  const m = /^([+-]?\d+(?:\.\d+)?), *([+-]?\d+(?:\.\d+)?)$/.exec(body);
  if (m === null) {
    return false;
  }
  const lat = Number(m[1]);
  const lon = Number(m[2]);
  return Math.abs(lat) <= 90 && Math.abs(lon) <= 180;
}

export function solve(issn: string): boolean {
  // Four digits, optional hyphen, three digits, then a digit or X/x as the check character.
  if (!/^\d{4}-?\d{3}[\dXx]$/.test(issn)) {
    return false;
  }

  const chars = issn.replace("-", "");

  // Weights are 8 down to 1 across the eight characters; the check character has weight 1.
  let sum = 0;
  for (let i = 0; i < 8; i++) {
    const c = chars[i];
    const value = c === "X" || c === "x" ? 10 : c.charCodeAt(0) - 48;
    sum += (8 - i) * value;
  }

  return sum % 11 === 0;
}

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === "") {
    return doc;
  }
  if (!pointer.startsWith("/")) {
    throw new Error(
      `Invalid JSON Pointer: must be empty or start with "/": ${JSON.stringify(pointer)}`
    );
  }

  const tokens = pointer.slice(1).split("/");
  let current: unknown = doc;

  for (const raw of tokens) {
    // RFC 6901: decode ~1 to "/" first, then ~0 to "~" (in that order).
    const token = raw.replace(/~1/g, "/").replace(/~0/g, "~");

    if (Array.isArray(current)) {
      // Array index: "0" or a non-zero-leading decimal integer. "-" never resolves.
      if (!/^(0|[1-9][0-9]*)$/.test(token)) {
        return undefined;
      }
      const index = Number(token);
      if (index >= current.length) {
        return undefined;
      }
      current = current[index];
    } else if (typeof current === "object" && current !== null) {
      const obj = current as Record<string, unknown>;
      if (!Object.prototype.hasOwnProperty.call(obj, token)) {
        return undefined;
      }
      current = obj[token];
    } else {
      // Primitive or null: cannot descend further.
      return undefined;
    }
  }

  return current;
}

type Ver = { major: number; minor: number; patch: number; pre: string[] };
type Bound = { v: Ver; incl: boolean };

function mk(major: number, minor: number, patch: number, pre: string = ""): Ver {
  return { major, minor, patch, pre: pre ? pre.split(".") : [] };
}

function compare(a: Ver, b: Ver): number {
  if (a.major !== b.major) return a.major < b.major ? -1 : 1;
  if (a.minor !== b.minor) return a.minor < b.minor ? -1 : 1;
  if (a.patch !== b.patch) return a.patch < b.patch ? -1 : 1;

  const pa = a.pre, pb = b.pre;
  if (pa.length === 0 && pb.length === 0) return 0;
  if (pa.length === 0) return 1;
  if (pb.length === 0) return -1;

  const n = Math.min(pa.length, pb.length);
  for (let i = 0; i < n; i++) {
    const x = pa[i], y = pb[i];
    const xn = /^\d+$/.test(x), yn = /^\d+$/.test(y);
    if (xn && yn) {
      if (x.length !== y.length) return x.length < y.length ? -1 : 1;
      if (x !== y) return x < y ? -1 : 1;
    } else if (xn) {
      return -1;
    } else if (yn) {
      return 1;
    } else if (x !== y) {
      return x < y ? -1 : 1;
    }
  }
  if (pa.length === pb.length) return 0;
  return pa.length < pb.length ? -1 : 1;
}

function parsePartial(s: string): {
  major: number | null;
  minor: number | null;
  patch: number | null;
  pre: string;
} {
  const mt = /^(\d+|[xX*])(?:\.(\d+|[xX*]))?(?:\.(\d+|[xX*]))?(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?$/.exec(s);
  if (!mt) throw new Error("invalid comparator");
  const num = (t: string | undefined): number | null =>
    t === undefined || !/^\d+$/.test(t) ? null : Number(t);
  let major = num(mt[1]);
  let minor = num(mt[2]);
  let patch = num(mt[3]);
  if (major === null) { minor = null; patch = null; }
  if (minor === null) patch = null;
  return { major, minor, patch, pre: mt[4] ?? "" };
}

// Returns the upper bound implied by a single comparator, or undefined if none.
function comparatorBound(tok: string): Bound | undefined {
  const mm = /^(<=|>=|<|>|=|~>|~|\^)?(.*)$/.exec(tok);
  if (!mm) throw new Error("invalid comparator");
  const op = mm[1] ?? "";
  const p = parsePartial(mm[2].replace(/^v/i, ""));
  const M = p.major, m = p.minor, pa = p.patch, pre = p.pre;

  switch (op) {
    case "":
    case "=":
      if (M === null) return undefined;
      if (m === null) return { v: mk(M + 1, 0, 0), incl: false };
      if (pa === null) return { v: mk(M, m + 1, 0), incl: false };
      return { v: mk(M, m, pa, pre), incl: true };
    case "<":
      if (M === null) return { v: mk(0, 0, 0), incl: false };
      if (m === null) return { v: mk(M, 0, 0), incl: false };
      if (pa === null) return { v: mk(M, m, 0), incl: false };
      return { v: mk(M, m, pa, pre), incl: false };
    case "<=":
      if (M === null) return undefined;
      if (m === null) return { v: mk(M + 1, 0, 0), incl: false };
      if (pa === null) return { v: mk(M, m + 1, 0), incl: false };
      return { v: mk(M, m, pa, pre), incl: true };
    case "~":
    case "~>":
      if (M === null) return undefined;
      if (m === null) return { v: mk(M + 1, 0, 0), incl: false };
      return { v: mk(M, m + 1, 0), incl: false };
    case "^":
      if (M === null) return undefined;
      if (m === null || M > 0) return { v: mk(M + 1, 0, 0), incl: false };
      if (m > 0) return { v: mk(0, m + 1, 0), incl: false };
      if (pa === null) return { v: mk(0, 1, 0), incl: false };
      return { v: mk(0, 0, pa + 1), incl: false };
    default:
      // ">" and ">=" impose no upper bound
      return undefined;
  }
}

function minBound(a: Bound | undefined, b: Bound | undefined): Bound | undefined {
  if (!a) return b;
  if (!b) return a;
  const c = compare(a.v, b.v);
  if (c < 0) return a;
  if (c > 0) return b;
  return a.incl ? b : a;
}

// Upper bound of a single comparator set (space-separated, may contain hyphen ranges).
function altBound(alt: string): Bound | undefined {
  const toks = alt.trim().split(/\s+/).filter((t) => t.length > 0);
  let acc: Bound | undefined = undefined;
  let i = 0;
  while (i < toks.length) {
    if (i + 2 < toks.length && toks[i + 1] === "-") {
      // Hyphen range: upper bound is the "<=" form of the right side.
      acc = minBound(acc, comparatorBound("<=" + toks[i + 2]));
      i += 3;
      continue;
    }
    let tok = toks[i];
    if (/^(<=|>=|<|>|=|~>|~|\^)$/.test(tok) && i + 1 < toks.length) {
      tok = tok + toks[i + 1];
      i += 2;
    } else {
      i += 1;
    }
    acc = minBound(acc, comparatorBound(tok));
  }
  return acc;
}

export function solve(version: string, range: string): boolean {
  try {
    const vm = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$/.exec(version);
    if (!vm) return false;
    const v = mk(Number(vm[1]), Number(vm[2]), Number(vm[3]), vm[4] ?? "");

    for (const alt of range.split("||")) {
      const b = altBound(alt);
      // No upper bound in this alternative: the version can never be above it.
      if (b === undefined) return false;
      const c = compare(v, b.v);
      // Must be strictly above an inclusive bound, or at/above an exclusive bound.
      if (b.incl ? c <= 0 : c < 0) return false;
    }
    return true;
  } catch (_e) {
    return false;
  }
}

export function solve(a: string, b: string): number {
  const n = a.length;
  const m = b.length;
  if (n === 0) return m;
  if (m === 0) return n;

  let prev = new Int32Array(m + 1);
  let curr = new Int32Array(m + 1);
  for (let j = 0; j <= m; j++) prev[j] = j;

  for (let i = 1; i <= n; i++) {
    curr[0] = i;
    const ca = a.charCodeAt(i - 1);
    for (let j = 1; j <= m; j++) {
      const cost = ca === b.charCodeAt(j - 1) ? 0 : 1;
      let v = prev[j - 1] + cost;
      const del = prev[j] + 1;
      if (del < v) v = del;
      const ins = curr[j - 1] + 1;
      if (ins < v) v = ins;
      curr[j] = v;
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }
  return prev[m];
}

export function solve(name: string): boolean {
  if (typeof name !== "string") return false;

  // Whole name at most 253 characters (counted by code points).
  if (Array.from(name).length > 253) return false;

  // At least two labels; split yields an empty last label for a trailing dot,
  // and empty labels (leading or doubled dots) are rejected by the label regex.
  const labels = name.split(".");
  if (labels.length < 2) return false;

  // Label of 1-63 ASCII letters/digits/hyphens, not starting or ending with a hyphen.
  const labelRe = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/;

  const tld = labels[labels.length - 1];
  const others = labels.slice(0, -1);

  // All non-TLD labels must be valid (digits-only labels are allowed).
  if (!others.every((label) => labelRe.test(label))) return false;

  // TLD option 1: punycode label starting with "xn--".
  if (/^xn--/i.test(tld) && labelRe.test(tld)) return true;

  // TLD option 2: at least two characters, letters only (Unicode letters allowed).
  // Any digit or hyphen in a non-punycode TLD makes it invalid.
  const tldLength = Array.from(tld).length;
  return (
    tldLength >= 2 &&
    tldLength <= 63 &&
    /^\p{L}+$/u.test(tld)
  );
}

