/**
 * Returns the entry of `dictionary` closest to `word` in Levenshtein distance
 * (single-character insertions, deletions and substitutions, each costing 1).
 * On a tie, the entry that appears first in `dictionary` is returned.
 *
 * Characters are Unicode code points, so an astral character such as an emoji
 * counts as one character.
 *
 * @throws {RangeError} if `dictionary` is empty, since there is no entry to return.
 */
export function solve(word: string, dictionary: string[]): string {
  const source = Array.from(word);
  let best: string | undefined;
  let bestDistance = Infinity;

  for (const entry of dictionary) {
    // Only a strictly smaller distance replaces the best, so on a tie the earlier entry is kept.
    const distance = boundedLevenshtein(source, Array.from(entry), bestDistance);
    if (distance < bestDistance) {
      best = entry;
      bestDistance = distance;
      if (distance === 0) break; // exact match: nothing can be strictly closer
    }
