/**
 * Levenshtein distance between two character arrays, computed one row at a time
 * (O(|a|·|b|) time, O(min(|a|, |b|)) space).
 *
 * If the true distance is at least `bound`, the result is some value >= `bound`;
 * the computation stops as soon as that is certain. Hence `result < bound` holds
 * exactly when the true distance is below `bound`. Pass Infinity for the exact distance.
 */
function boundedLevenshtein(a: string[], b: string[], bound: number): number {
  const aIsLonger = a.length > b.length;
  const s = aIsLonger ? b : a; // the shorter sequence indexes each row, keeping rows short
  const t = aIsLonger ? a : b;
  const m = s.length;
  const n = t.length;

  // Any alignment needs at least |n - m| insertions or deletions.
  if (n - m >= bound) return n - m;

  // Rows of the DP table: prev holds row j-1 and curr receives row j,
  // where row[i] = distance between s[0..i) and t[0..j).
  let prev: number[] = [];
  let curr: number[] = [];
  for (let i = 0; i <= m; i++) {
    prev.push(i); // distance between s[0..i) and the empty string
    curr.push(0);
  }

  for (let j = 1; j <= n; j++) {
    curr[0] = j;
    let rowMin = j;
    for (let i = 1; i <= m; i++) {
      const cost = s[i - 1] === t[j - 1] ? 0 : 1;
      const value = Math.min(
        prev[i - 1] + cost, // substitution, or a free match
        prev[i] + 1, // t[j-1] has no counterpart in s
        curr[i - 1] + 1 // s[i-1] has no counterpart in t
      );
      curr[i] = value;
      if (value < rowMin) rowMin = value;
    }
    // Every alignment passes through row j, and its cost never decreases as it proceeds,
    // so the smallest value in this row is a lower bound on the final distance.
    if (rowMin >= bound) return rowMin;
    [prev, curr] = [curr, prev];
  }
  return prev[m];
}

function decodeDigit(code: number): number {
  if (code >= 65 && code <= 90) return code - 65;        // 'A'-'Z' -> 0..25
  if (code >= 97 && code <= 122) return code - 97 + 26;  // 'a'-'z' -> 26..51
  if (code >= 48 && code <= 57) return code - 48 + 52;   // '0'-'9' -> 52..61
  if (code === 43) return 62;                            // '+'
  if (code === 47) return 63;                            // '/'
  return -1;
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error(
      `Invalid base64 length: ${text.length} is not a multiple of 4`
    );
  }

  // Trailing '=' characters are padding; at most two are allowed.
  let end = text.length;
  while (end > 0 && text.charAt(end - 1) === "=") {
    end--;
  }
  if (text.length - end > 2) {
    throw new Error("Invalid base64 padding: more than two '=' characters");
  }

  const bytes: number[] = [];
  let acc = 0;  // bit accumulator, masked so it never grows beyond 16 bits
  let bits = 0; // number of bits in `acc` not yet emitted as bytes

  for (let i = 0; i < end; i++) {
    const value = decodeDigit(text.charCodeAt(i));
    if (value < 0) {
      throw new Error(`Invalid base64 character at index ${i}`);
    }
    acc = ((acc << 6) | value) & 0xffff;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      bytes.push((acc >> bits) & 0xff);
    }
  }

  return bytes;
}

const SEMVER_RE =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

const NUMERIC_ID = /^[0-9]+$/;

interface ParsedVersion {
  raw: string;
  major: string;
  minor: string;
  patch: string;
  prerelease: readonly string[] | null;
}

function parseVersion(raw: string): ParsedVersion | null {
  const m = SEMVER_RE.exec(raw);
  if (m === null) return null;
  const [, major, minor, patch, pre] = m;
  return {
    raw,
    major,
    minor,
    patch,
    prerelease: pre === undefined ? null : pre.split("."),
  };
}

// Numeric comparison of digit strings of any length (no precision loss).
function compareNumeric(a: string, b: string): number {
  const x = a.replace(/^0+/, "") || "0";
  const y = b.replace(/^0+/, "") || "0";
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  return x === y ? 0 : x < y ? -1 : 1;
}

// Lexical comparison by code unit (ASCII for valid identifiers).
function compareText(a: string, b: string): number {
  return a === b ? 0 : a < b ? -1 : 1;
}

function compareIdentifier(a: string, b: string): number {
  const aNum = NUMERIC_ID.test(a);
  const bNum = NUMERIC_ID.test(b);
  if (aNum && bNum) return compareNumeric(a, b);
  if (aNum) return -1; // numeric identifiers rank below alphanumeric ones
  if (bNum) return 1;
  return compareText(a, b);
}

function comparePrerelease(a: readonly string[], b: readonly string[]): number {
  const len = Math.min(a.length, b.length);
  for (let i = 0; i < len; i++) {
    const c = compareIdentifier(a[i], b[i]);
    if (c !== 0) return c;
  }
  // With all shared identifiers equal, the longer list has higher precedence.
  return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
}

// SemVer 2.0.0 precedence; build metadata is ignored.
function comparePrecedence(a: ParsedVersion, b: ParsedVersion): number {
  const core =
    compareNumeric(a.major, b.major) ||
    compareNumeric(a.minor, b.minor) ||
    compareNumeric(a.patch, b.patch);
  if (core !== 0) return core;

  const pa = a.prerelease;
  const pb = b.prerelease;
  if (pa === null || pb === null) {
    // A release outranks any prerelease of the same major.minor.patch.
    if (pa === pb) return 0;
    return pa === null ? 1 : -1;
  }
  return comparePrerelease(pa, pb);
}

export function solve(versions: string[]): string[] {
  const parsed: ParsedVersion[] = [];
  for (const v of versions) {
    const p = parseVersion(v);
    if (p !== null) parsed.push(p);
  }
  // Equal precedence: order by the full version string, lexically.
  parsed.sort((a, b) => comparePrecedence(a, b) || compareText(a.raw, b.raw));
  return parsed.map((p) => p.raw);
}

/**
 * Returns true if `isbn` is a valid ISBN-10 and/or ISBN-13.
 * Spaces and hyphens are ignored. When `version` is given, only that version is accepted.
 */
export function solve(isbn: string, version?: 10 | 13): boolean {
  const s = isbn.replace(/[\s-]/g, "");

  if (version === undefined) {
    return isValidIsbn10(s) || isValidIsbn13(s);
  }
  if (version === 10) {
    return isValidIsbn10(s);
  }
  if (version === 13) {
    return isValidIsbn13(s);
  }
  return false; // unsupported version (only reachable from untyped callers)
}

/**
 * ISBN-10: nine digits followed by a digit or an upper-case 'X' (= 10).
 * Check: Σ (10 − i)·dᵢ ≡ 0 (mod 11), with i = 0..9 (0-based), so weights run 10..1.
 */
function isValidIsbn10(s: string): boolean {
  if (!/^[0-9]{9}[0-9X]$/.test(s)) return false;

  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const c = s.charAt(i);
    const value = c === "X" ? 10 : Number(c);
    sum += (10 - i) * value;
  }
  return sum % 11 === 0;
}

/**
 * ISBN-13: thirteen digits with the EAN-13 check.
 * Weights 1,3,1,3,... over all 13 digits; the weighted sum must be ≡ 0 (mod 10).
 */
function isValidIsbn13(s: string): boolean {
  if (!/^[0-9]{13}$/.test(s)) return false;

  let sum = 0;
  for (let i = 0; i < 13; i++) {
    const d = Number(s.charAt(i));
    sum += i % 2 === 0 ? d : 3 * d;
  }
  return sum % 10 === 0;
}

export function solve(isin: string): boolean {
  // Format: 2 upper-case letters, 9 upper-case alphanumerics, 1 check digit.
  if (typeof isin !== "string" || !/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) {
    return false;
  }

  // Expand to a digit string: digits stay as they are, letters become A=10 ... Z=35.
  let digits = "";
  for (const ch of isin) {
    digits += /[A-Z]/.test(ch) ? String(ch.charCodeAt(0) - 55) : ch;
  }

  // Luhn check over the full digit string (check digit included): scanning from the
  // rightmost digit, double every second digit (subtracting 9 from results above 9),
  // and the total must be a multiple of 10.
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    let d = digits.charCodeAt(digits.length - 1 - i) - 48; // '0' is code 48
    if (i % 2 === 1) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
  }

  return sum % 10 === 0;
}

export function solve(code: string): boolean {
  if (typeof code !== "string") return false;
  if (!/^[0-9]+$/.test(code)) return false;

  const n = code.length;
  if (n !== 8 && n !== 13 && n !== 14) return false;

  // Weights alternate 3, 1, 3, ... starting from the rightmost data digit
  // (the digit just left of the check digit).
  let sum = 0;
  for (let i = 0; i < n - 1; i++) {
    const digit = code.charCodeAt(n - 2 - i) - 48; // '0' is char code 48
    sum += digit * (i % 2 === 0 ? 3 : 1);
  }

  const check = (10 - (sum % 10)) % 10;
  return check === code.charCodeAt(n - 1) - 48;
}

// EUI-48 / EUI-64 with ':' or '-' separators. The first separator is captured,
// and every later separator must match it, so separators cannot be mixed.
const COLON_HYPHEN_EUI48 = /^[0-9A-Fa-f]{2}([:-])[0-9A-Fa-f]{2}(?:\1[0-9A-Fa-f]{2}){4}$/;
const COLON_HYPHEN_EUI64 = /^[0-9A-Fa-f]{2}([:-])[0-9A-Fa-f]{2}(?:\1[0-9A-Fa-f]{2}){6}$/;

// Dotted (Cisco) form: 3 groups (EUI-48) or 4 groups (EUI-64) of 4 hex digits.
const DOTTED_EUI48 = /^[0-9A-Fa-f]{4}\.[0-9A-Fa-f]{4}\.[0-9A-Fa-f]{4}$/;
const DOTTED_EUI64 = /^[0-9A-Fa-f]{4}\.[0-9A-Fa-f]{4}\.[0-9A-Fa-f]{4}\.[0-9A-Fa-f]{4}$/;

export function solve(mac: string): boolean {
  return (
    COLON_HYPHEN_EUI48.test(mac) ||
    COLON_HYPHEN_EUI64.test(mac) ||
    DOTTED_EUI48.test(mac) ||
    DOTTED_EUI64.test(mac)
  );
}

export function solve(issn: string): boolean {
  if (typeof issn !== 'string') {
    return false;
  }

  // Four digits, an optional hyphen, three more digits, then a check
  // character that is a digit or X/x (either case).
  if (!/^\d{4}-?\d{3}[\dXx]$/.test(issn)) {
    return false;
  }

  // Remove the optional hyphen, leaving exactly 8 characters.
  const compact = issn.replace('-', '');

  // The zero-based index i of each of the first seven digits gets weight (8 - i),
  // i.e. 8, 7, 6, 5, 4, 3, 2 as specified by ISO 3297.
  let sum = 0;
  for (let i = 0; i < 7; i++) {
    sum += (8 - i) * Number(compact.charAt(i));
  }

  // The check character has weight 1; X (or x) stands for 10.
  const last = compact.charAt(7).toUpperCase();
  sum += last === 'X' ? 10 : Number(last);

  return sum % 11 === 0;
}

/** A card network: prefix must fall in one of `prefixes`, length must be one of `lengths`. */
interface IssuerRule {
  /** Inclusive [low, high] prefix ranges. Both bounds of a range have the same number of digits. */
  readonly prefixes: ReadonlyArray<readonly [string, string]>;
  readonly lengths: ReadonlyArray<number>;
}

const ISSUERS: ReadonlyArray<IssuerRule> = [
  // Visa: prefix 4; 13, 16 or 19 digits
  { prefixes: [["4", "4"]], lengths: [13, 16, 19] },

  // Mastercard: 51-55 or 2221-2720; 16 digits
  { prefixes: [["51", "55"], ["2221", "2720"]], lengths: [16] },

  // American Express: 34 or 37; 15 digits
  { prefixes: [["34", "34"], ["37", "37"]], lengths: [15] },

  // Discover: 6011, 622126-622925, 644-649, 65; 16 or 19 digits
  {
    prefixes: [
      ["6011", "6011"],
      ["622126", "622925"],
      ["644", "649"],
      ["65", "65"],
    ],
    lengths: [16, 19],
  },

  // Diners Club: 300-305, 36, 38; 14-19 digits
  {
    prefixes: [["300", "305"], ["36", "36"], ["38", "38"]],
    lengths: [14, 15, 16, 17, 18, 19],
  },

  // JCB: 3528-3589; 16-19 digits
  { prefixes: [["3528", "3589"]], lengths: [16, 17, 18, 19] },

  // UnionPay: 62; 16-19 digits
  { prefixes: [["62", "62"]], lengths: [16, 17, 18, 19] },
];

/**
 * True if `digits` begins with a prefix within the inclusive range [low, high].
 * The bounds have equal length, so lexicographic comparison of digit strings
 * is the same as numeric comparison.
 */
function startsInRange(digits: string, [low, high]: readonly [string, string]): boolean {
  const head = digits.slice(0, low.length);
  return head.length === low.length && head >= low && head <= high;
}

/** Luhn (mod 10) checksum over a string of decimal digits. */
function passesLuhn(digits: string): boolean {
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    // i = 0 is the rightmost (check) digit; every second digit from the right is doubled.
    let d = Number(digits.charAt(digits.length - 1 - i));
    if (i % 2 === 1) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
  }
  return sum % 10 === 0;
}

export function solve(card: string): boolean {
  // Spaces and hyphens are separators; every other character must be a digit.
  const digits = card.replace(/[ -]/g, "");
  if (!/^\d+$/.test(digits)) return false;

  const matchesIssuer = ISSUERS.some(
    ({ prefixes, lengths }) =>
      lengths.includes(digits.length) &&
      prefixes.some((range) => startsInRange(digits, range)),
  );

  return matchesIssuer && passesLuhn(digits);
}

export function solve(text: string): boolean {
  // Optionally wrapped in exactly one pair of parentheses (no spaces inside them).
  const wrapped = /^\(([^()]*)\)$/.exec(text);
  const body = wrapped === null ? text : wrapped[1];

  // Exactly one comma: no space before it, zero or more spaces after it.
  const pair = /^([^,]*),(?: *)([^,]*)$/.exec(body);
  if (pair === null) {
    return false;
  }

  // Latitude first, then longitude.
  return withinLimit(pair[1], 90) && withinLimit(pair[2], 180);
}

// True if `value` is an optionally signed decimal (digits with an optional
// "." fraction) whose absolute value is <= limit. The comparison is done on
// the digit strings, so values like "90.00000000000000001" are not rounded
// into range by floating-point arithmetic.
function withinLimit(value: string, limit: number): boolean {
  const m = /^[+-]?(\d+)(?:\.(\d+))?$/.exec(value);
  if (m === null) {
    return false;
  }

  const whole = Number(m[1]); // leading zeros do not change the value
  if (whole !== limit) {
    return whole < limit;
  }

  // Whole part equals the limit: only zero fractional digits keep it in range.
  return !m[2] || /^0*$/.test(m[2]);
}
